def expand_coin_grade(grade):
    """Expand a grade code's prefix for display: cAU -> "Choice AU", gVF -> "Good VF",
    aEF -> "About EF". Bare grades (VF, EF, MS, "VF+", ...) are returned unchanged."""
    g = (grade or '').strip()
    if not g:
        return ''
    m = re.match(r'^([cag])([A-Z].*)$', g)
    prefixes = {'c': 'Choice', 'a': 'About', 'g': 'Good'}
    if m and m.group(1) in prefixes:
        return f'{prefixes[m.group(1)]} {m.group(2)}'
    return g


@app.template_global()
def coin_grade_display(grade, grade_modifier=None):
    """Grade with its NGC modifier attached for display/PDF: EF + ★ -> "EF★", cAU + ★ -> "Choice AU★".
    The modifier (★ Star, + Plus) is part of the grade; surface conditions live in their own field."""
    g = expand_coin_grade(grade)
    mod = (grade_modifier or '').strip()
    return f'{g}{mod}' if (g and mod) else (g or mod)


def normalize_grade_modifier(value):
    """Reduce a grade designation to the canonical symbol(s): NGC Star -> "★", Plus -> "+", both -> "★+"."""
    raw = value if isinstance(value, str) else ('' if value is None else str(value))
    low = raw.lower()
    star = '★' in raw or '✪' in raw or 'star' in low
    plus = '+' in raw or 'plus' in low
    out = ('★' if star else '') + ('+' if plus else '')
    return out or None


_GRADING_AUTHORITY_CANON = {
    'ncg': 'NGC', 'ngc': 'NGC', 'pcgs': 'PCGS', 'anacs': 'ANACS', 'icg': 'ICG',
    'pmg': 'PMG', 'cac': 'CAC', 'cacg': 'CACG', 'segs': 'SEGS',
}


def normalize_grading_authority(value):
    """Clean a grading-company name and fix the common 'NCG' typo for 'NGC'."""
    v = value.strip() if isinstance(value, str) else (str(value).strip() if value is not None else '')
    if not v:
        return None
    return _GRADING_AUTHORITY_CANON.get(v.lower(), v)


def coin_grade_value_list_match(value):
    """Map collector grade variants to the configured coin grade list.

    Returns a canonical VALUE_LISTS['coin_grade'] entry, or None when the
    source grade cannot be represented by the configured dropdown.
    """
    if value is None:
        return None
    import unicodedata
    raw = unicodedata.normalize('NFC', str(value)).strip()
    if not raw:
        return None

    allowed = {g.lower(): g for g in VALUE_LISTS['coin_grade']}
    direct = allowed.get(raw.lower())
    if direct:
        return direct

    normalized = raw.lower().replace('&', ' and ')
    normalized = re.sub(r'[\[\](){},.;:/_–—-]+', ' ', normalized)
    normalized = re.sub(r'\s+', ' ', normalized).strip()

    aliases = FIELD_ALIASES.get(('coins', 'grade'), {})
    alias = aliases.get(normalized)
    if alias:
        return alias

    compact = re.sub(r'[^a-z0-9+]+', '', normalized)
    if (
        'mintstate' in compact
        or compact in {'unc', 'uncirc'}
        or 'uncirculated' in compact
        or re.search(r'\b(?:m\s*s|ms|unc)\s*\d{0,2}\b', normalized)
    ):
        return 'MS'
    compact_aliases = {
        'brilliantuncirculated': 'BU',
        'bu': 'BU',
        'fleurdecoin': 'FDC',
        'fdc': 'FDC',
        'mintstate': 'MS',
        'uncirculated': 'MS',
        'ms': 'MS',
        'proof': 'PF',
        'prf': 'PF',
        'pr': 'PF',
        'pf': 'PF',
        'choiceau': 'cAU',
        'chau': 'cAU',
        'cau': 'cAU',
        'aboutau': 'aAU',
        'almostau': 'aAU',
        'nearlyau': 'aAU',
        'nearau': 'aAU',
        'aau': 'aAU',
        'au': 'AU',
        'choiceef': 'cEF',
        'choicexf': 'cEF',
        'chex': 'cEF',
        'chef': 'cEF',
        'chxf': 'cEF',
        'cef': 'cEF',
        'cxf': 'cEF',
        'aboutef': 'aEF',
        'aboutxf': 'aEF',
        'almostef': 'aEF',
        'almostxf': 'aEF',
        'nearlyef': 'aEF',
        'nearlyxf': 'aEF',
        'nearef': 'aEF',
        'nearxf': 'aEF',
        'aef': 'aEF',
        'axf': 'aEF',
        'ef': 'EF',
        'xf': 'EF',
        'choicevf': 'cVF',
        'chvf': 'cVF',
        'cvf': 'cVF',
        'goodvf': 'gVF',
        'gvf': 'gVF',
        'aboutvf': 'aVF',
        'almostvf': 'aVF',
        'nearlyvf': 'aVF',
        'nearvf': 'aVF',
        'avf': 'aVF',
        'veryfine+': 'VF+',
        'veryfineplus': 'VF+',
        'vfplus': 'VF+',
        'vf+': 'VF+',
        'vf': 'VF',
    }
    if re.fullmatch(r'ms\d{1,2}', compact):
        return 'MS'
    if re.fullmatch(r'pf\d{1,2}|pr\d{1,2}', compact):
        return 'PF'
    mapped = compact_aliases.get(compact)
    if mapped:
        return mapped

    phrase_patterns = [
        (r'\b(?:brilliant\s+uncirculated|bu)\b', 'BU'),
        (r'\bfleur\s+de\s+coin\b|\bfdc\b', 'FDC'),
        (r'\bmint\s+state\b|\buncirculated\b|\bms\s*\d{0,2}\b', 'MS'),
        (r'\bproof\b|\bpr\s*\d{0,2}\b|\bpf\s*\d{0,2}\b', 'PF'),
        (r'\b(?:choice|ch)\s+(?:au|about\s+uncirculated|almost\s+uncirculated)\b', 'cAU'),
        (r'\b(?:about|almost|near|nearly)\s+(?:au|uncirculated)\b', 'aAU'),
        (r'\bau\b', 'AU'),
        (r'\b(?:choice|ch)\s+(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'cEF'),
        (r'\b(?:about|almost|near|nearly)\s+(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'aEF'),
        (r'\b(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'EF'),
        (r'\b(?:choice|ch)\s+(?:vf|very\s+fine)\b', 'cVF'),
        (r'\bgood\s+(?:vf|very\s+fine)\b', 'gVF'),
        (r'\b(?:about|almost|near|nearly)\s+(?:vf|very\s+fine)\b', 'aVF'),
        (r'\b(?:vf|very\s+fine)\s*(?:\+|plus\b)', 'VF+'),
        (r'\b(?:vf|very\s+fine)\b', 'VF'),
    ]
    for pattern, canonical in phrase_patterns:
        if re.search(pattern, normalized):
            return canonical
    return None


def banknote_grade_value_list_match(value):
    """Map paper-money grade variants to VALUE_LISTS['banknote_grade'].

    PMG/PCGS-Banknote wording ("Superb Gem Uncirculated 67 EPQ",
    "Gem UNC", "Choice About Unc 58") folds to the canonical adjectival
    entry. Returns None when nothing in the list fits.
    """
    if value is None:
        return None
    import unicodedata
    raw = unicodedata.normalize('NFC', str(value)).strip()
    if not raw:
        return None

    allowed = {g.lower(): g for g in VALUE_LISTS['banknote_grade']}
    direct = allowed.get(raw.lower())
    if direct:
        return direct

    normalized = raw.lower()
    normalized = re.sub(r'[\[\](){},.;:/_–—-]+', ' ', normalized)
    normalized = re.sub(r'\s+', ' ', normalized).strip()

    alias = FIELD_ALIASES.get(('banknotes', 'grade'), {}).get(normalized)
    if alias:
        return alias

    # Ordered: most specific phrasing first. Numeric suffixes ("65 EPQ")
    # and the EPQ/★ designation are ignored here — they live in
    # grade_numeric / grade_modifier.
    phrase_patterns = [
        (r'\bsuperb?\s+gem\s+(?:unc|uncirculated|cu)\b', 'Superb Gem UNC'),
        (r'\bgem\s+(?:crisp\s+)?(?:unc|uncirculated|cu)\b', 'Gem UNC'),
        (r'\b(?:choice|ch)\s+(?:crisp\s+)?(?:unc|uncirculated|cu)\b', 'Choice UNC'),
        (r'\b(?:crisp\s+)?(?:unc|uncirculated)\b|\bcu\s*\d{0,2}\b', 'UNC'),
        (r'\b(?:choice|ch)\s+(?:au|about\s+unc(?:irculated)?)\b', 'cAU'),
        (r'\b(?:about|almost|near|nearly)\s+(?:au|unc(?:irculated)?)\b', 'aAU'),
        (r'\bau\s*\d{0,2}\b', 'AU'),
        (r'\b(?:choice|ch)\s+(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'cEF'),
        (r'\b(?:about|almost|near|nearly)\s+(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'aEF'),
        (r'\b(?:ef|xf|extremely\s+fine|extra\s+fine)\b', 'EF'),
        (r'\b(?:choice|ch)\s+(?:vf|very\s+fine)\b', 'cVF'),
        (r'\b(?:about|almost|near|nearly)\s+(?:vf|very\s+fine)\b', 'aVF'),
        (r'\b(?:vf|very\s+fine)\b', 'VF'),
        (r'\bvery\s+good\b|\bvg\b', 'VG'),
        (r'\b(?:fine|f)\s*\d{0,2}\b', 'F'),
        (r'\bgood\b|\bg\s*\d{1,2}\b', 'G'),
        (r'\bfair\b', 'Fair'),
        (r'\bpoor\b', 'Poor'),
    ]
    for pattern, canonical in phrase_patterns:
        if re.search(pattern, normalized):
            return canonical
    return None


FOUR_DIGIT_YEAR_FIELDS = {'year', 'year_recorded', 'year_built'}


def _normalize_four_digit_year(value):
    s = str(value or '').strip()
    if not re.fullmatch(r'\d{1,2}', s):
        return value
    yy = int(s)
    current_year = datetime.now().year
    current_century = (current_year // 100) * 100
    candidate = current_century + yy
    if candidate > current_year + 25:
        candidate -= 100
    elif candidate < current_year - 75:
        candidate += 100
    return str(candidate)


def _normalize_coin_year_input(value):
    s = str(value or '').strip()
    if not s:
        return ''
    m = re.match(r'^\s*(-?\d+)\s*(BC|BCE|AD|CE)?\s*$', s, re.IGNORECASE)
    if not m:
        return value
    n = int(m.group(1))
    era = (m.group(2) or '').upper()
    if era in ('BC', 'BCE') and n > 0:
        n = -n
    elif era in ('AD', 'CE') and n < 0:
        n = abs(n)
    return str(n)


def normalize_field_value(table, field_name, value):
    """Return the canonical value for a known alias, or the input
    unchanged. Strings are first NFC-normalized so pre-composed and
    decomposed Unicode forms of the same character (e.g. 'ü' as U+00FC
    vs U+0075+U+0308) collapse to one canonical form before any alias
    lookup or DB write — keeps a pasted brand name from creating two
    visually-identical-but-different entries down the line."""
    if value is None:
        return value
    if isinstance(value, str):
        import unicodedata
        value = unicodedata.normalize('NFC', value)
    if field_name in FOUR_DIGIT_YEAR_FIELDS:
        return _normalize_four_digit_year(value)
    if table in ('coins', 'banknotes') and field_name in ('date_1', 'date_2'):
        return _normalize_coin_year_input(value)
    if field_name == 'status' and value.strip().lower() == 'owned':
        return 'Own'
    if table == 'coins' and field_name == 'grade':
        grade = coin_grade_value_list_match(value)
        if grade:
            return grade
    if table == 'banknotes' and field_name == 'grade':
        grade = banknote_grade_value_list_match(value)
        if grade:
            return grade
    if re.fullmatch(r'med_type_\d+', field_name or ''):
        med_type = value.strip().upper()
        if med_type == 'RX':
            return 'Rx'
        if med_type == 'OTC':
            return 'OTC'
        return ''
    aliases = FIELD_ALIASES.get((table, field_name))
    if not aliases:
        return value
    return aliases.get(value.strip().lower(), value)


# US notes must be catalogued under one country spelling or they split
# into separate blocks in the country-sorted list; grading services and
# Friedberg treat them as one. We store the fullest form.
_US_DENOM_RE = re.compile(r'^\s*(\d+)\s+dollars?\s*$', re.I)


def _canonical_banknote_country(value):
    if not isinstance(value, str):
        return value
    # Strip everything but letters/digits so punctuation and invisible
    # characters (NBSP, zero-width space) can't defeat the fold.
    key = re.sub(r'[^a-z0-9]', '', value.lower())
    if key in ('unitedstates', 'unitedstatesofamerica', 'usa', 'us'):
        return 'United States of America'
    return value


def _canonical_us_denomination(value):
    """US denominations follow the numismatic '$1' convention (Friedberg /
    PMG / PCGS), not '1 Dollar'. World notes keep the spelled unit
    ('5 Francs', 'EIGHT DOLLARS') and are left untouched — this only ever
    runs for US-country notes."""
    if not isinstance(value, str):
        return value
    m = _US_DENOM_RE.match(value)
    return f'${m.group(1)}' if m else value


def canonicalize_banknote_fields(fields, existing=None):
    """Row-aware canonicalization applied on every banknote save: fold US
    country spellings to one, and — only for US notes — put dollar
    denominations in '$N' form so they sort as a single block. Mutates and
    returns `fields`. `existing` supplies the country on a partial update
    that didn't touch it."""
    if 'country' in fields:
        fields['country'] = _canonical_banknote_country(fields['country'])
    country = fields.get('country')
    if country is None and existing is not None:
        country = existing['country']
    if _country_key(country) == 'us' and 'denomination' in fields:
        fields['denomination'] = _canonical_us_denomination(fields['denomination'])
    return fields


def _migrate_canonicalize_us_banknotes(db):
    """One-shot + idempotent backfill: apply canonicalize_banknote_fields to
    every existing note and resequence Display Numbers if anything changed.
    Fixes notes added under 'United States' / '1 Dollar' before the save
    hook existed."""
    cols = _table_cols(db, 'banknotes')
    if not {'country', 'denomination'}.issubset(cols):
        return
    changed = False
    for r in db.execute("SELECT id, country, denomination FROM banknotes").fetchall():
        fields = {'country': r['country'], 'denomination': r['denomination']}
        canonicalize_banknote_fields(fields, existing=r)
        if fields['country'] != r['country'] or fields['denomination'] != r['denomination']:
            db.execute(
                "UPDATE banknotes SET country = ?, denomination = ? WHERE id = ?",
                (fields['country'], fields['denomination'], r['id']))
            changed = True
    if changed:
        _renumber_banknotes(db)


def _normalize_owned_status_values(db):
    """Fold legacy status='Owned' rows to the canonical status='Own'."""
    tables = [
        r['name'] for r in db.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()
    ]
    for table in tables:
        cols = [r['name'] for r in db.execute(f"PRAGMA table_info({table})").fetchall()]
        if 'status' in cols:
            db.execute(
                f"UPDATE {table} SET status = 'Own' "
                "WHERE LOWER(TRIM(COALESCE(status, ''))) = 'owned'"
            )


def _backfill_blank_status_own(db):
    """Default blank lifecycle statuses to Own for item tables."""
    for category, info in CATEGORIES.items():
        table = info['table']
        cols = [r['name'] for r in db.execute(f"PRAGMA table_info({table})").fetchall()]
        if 'status' in cols:
            db.execute(
                f"UPDATE {table} SET status = 'Own' "
                "WHERE status IS NULL OR TRIM(status) = ''"
            )


def _merge_coin_condition_history(existing_notes, history_context):
    """Preserve manual notes while replacing the generated history block."""
    notes = (existing_notes or '').strip()
    body = (history_context or '').strip()
    if not body:
        return notes

    body = re.sub(r'(?is)\A\s*Historical Context\s*:?\s*\n+', '', body).strip()
    notes = re.sub(
        r'(?is)(?:\A|\n{2,})(?:Historical Context\s*:?\s*\n+)?'
        r'\s*(?:\*\*)?\s*Historical environment\s*(?:\*\*)?\s*:?\s*\n.*\Z',
        '',
        notes,
    ).strip()
    notes = re.sub(r'(?is)\A\s*Historical Context\s*:?\s*\n+', '', notes).strip()
    if not notes:
        return body
    if body in notes:
        return notes
    return f"{notes}\n\n{body}"


def _backfill_english_banknote_lettering(db):
    """One-time split for English-text banknotes: Check historically put
    all inscriptions (Front: + Back:) in `lettering` and left the
    translation empty for English notes. The convention is now
    side-per-panel for English notes — front text in `lettering` (left
    panel, under the front image), back text in `lettering_translation`
    (right panel, under the back image). Idempotent: transformed rows
    have a Back:-leading translation and are skipped on later boots;
    non-English notes (real translations) are untouched."""
    english_markers = {
        'the', 'of', 'and', 'will', 'pay', 'bearer', 'on', 'demand',
        'dollar', 'dollars', 'pound', 'pounds', 'bank', 'states',
        'america', 'this', 'note', 'legal', 'tender', 'promise',
        'treasury', 'reserve', 'one', 'two', 'five', 'ten', 'twenty',
        'fifty', 'hundred',
    }

    def looks_english(text):
        try:
            text.encode('ascii')
        except UnicodeEncodeError:
            return False
        words = set(re.findall(r"[a-z']+", text.lower()))
        return len(words & english_markers) >= 2

    def split_sides(text):
        front, back, side = [], [], None
        for line in text.splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            lowered = stripped.lower()
            if lowered.startswith('front:') or lowered.startswith('obverse:'):
                side = 'front'
            elif lowered.startswith('back:') or lowered.startswith('reverse:'):
                side = 'back'
            elif side is None:
                # Unstructured leading line — leave the row alone.
                return None
            (front if side == 'front' else back).append(stripped)
        if not back:
            return None  # nothing to move right; leave as-is
        return '\n'.join(front) or None, '\n'.join(back)

    rows = db.execute(
        "SELECT id, lettering, lettering_translation FROM banknotes "
        "WHERE lettering IS NOT NULL AND TRIM(lettering) != ''"
    ).fetchall()
    changed = 0
    for row in rows:
        lettering = (row['lettering'] or '').strip()
        translation = (row['lettering_translation'] or '').strip()
        if translation and translation.lower() != lettering.lower():
            # A real translation (or already-transformed row) — skip.
            continue
        if translation.lower().startswith('back:'):
            continue
        if not looks_english(lettering):
            continue
        split = split_sides(lettering)
        if not split:
            continue
        front_text, back_text = split
        db.execute(
            "UPDATE banknotes SET lettering = ?, lettering_translation = ? WHERE id = ?",
            (front_text, back_text, row['id']),
        )
        changed += 1
    if changed:
        db.commit()
        print(f"[migrate] split English lettering into front/back panels on {changed} banknotes", flush=True)


def _migrate_coin_history_context_into_condition(db):
    """Move legacy generated coin history into the editable notes field."""
    cols = _table_cols(db, 'coins')
    if not {'condition', 'history_context'}.issubset(cols):
        return

    rows = db.execute(
        "SELECT id, condition, history_context FROM coins "
        "WHERE history_context IS NOT NULL AND TRIM(history_context) != ''"
    ).fetchall()
    if not rows:
        return

    now = datetime.utcnow().isoformat()
    for row in rows:
        combined = _merge_coin_condition_history(row['condition'], row['history_context'])
        db.execute(
            "UPDATE coins SET condition = ?, history_context = NULL, updated_at = ? "
            "WHERE id = ?",
            (combined, now, row['id']),
        )
    db.commit()


def _cleanup_coin_research_headings(db):
    """Remove legacy generated section wrapper headings from coin prose."""
    cols = _table_cols(db, 'coins')
    needed = {'id', 'condition', 'coin_references'}
    if not needed.issubset(cols):
        return

    has_refs_research = 'coin_references_research' in cols
    select_extra = ', coin_references_research' if has_refs_research else ''
    rows = db.execute(
        f"SELECT id, condition, coin_references{select_extra} FROM coins"
    ).fetchall()
    now = datetime.utcnow().isoformat()
    changed = False
    for row in rows:
        condition = (row['condition'] or '').strip()
        refs = (row['coin_references'] or '').strip()
        new_condition = re.sub(
            r'(?is)\A\s*Historical Context\s*:?\s*\n+',
            '',
            condition,
        ).strip()
        refs_research = (
            (row['coin_references_research'] or '').strip()
            if has_refs_research else ''
        )
        new_refs = refs
        match = re.search(
            r'(?is)(\A|\n{2,})Numismatic importance\s*:?\s*\n+(.*)\Z',
            refs,
        )
        if match:
            before = refs[:match.start()].strip()
            refs_research = match.group(2).strip()
            new_refs = before
        if new_condition != condition or new_refs != refs or (
            has_refs_research and refs_research != (row['coin_references_research'] or '').strip()
        ):
            if has_refs_research:
                db.execute(
                    "UPDATE coins SET condition = ?, coin_references = ?, "
                    "coin_references_research = ?, updated_at = ? WHERE id = ?",
                    (new_condition, new_refs, refs_research, now, row['id']),
                )
            else:
                db.execute(
                    "UPDATE coins SET condition = ?, coin_references = ?, updated_at = ? "
                    "WHERE id = ?",
                    (new_condition, new_refs, now, row['id']),
                )
            changed = True
    if changed:
        db.commit()


