# ---------------------------------------------------------------------------
# Database helpers
# ---------------------------------------------------------------------------

def _strip_diacritics(s):
    """Fold a string to ASCII lowercase, dropping diacritical marks so
    'Roumégoux' compares as 'roumegoux' and 'Blåder' as 'blader'.
    SQLite's built-in LOWER() / NOCASE only handles ASCII A-Z, which
    leaves multi-byte UTF-8 characters in odd positions in a sort.
    """
    import unicodedata as _ud
    if s is None:
        return ''
    return _ud.normalize('NFKD', str(s)).encode('ascii', 'ignore').decode('ascii').lower()


def _nodiacritic_collation(a, b):
    """Custom SQLite collation: lexicographic order on the diacritic-
    folded, lowercased forms. Used in CATEGORY_ORDER_BY for art (and
    anywhere else humans expect 'café' to sort next to 'cafe')."""
    a = _strip_diacritics(a)
    b = _strip_diacritics(b)
    if a < b: return -1
    if a > b: return 1
    return 0


# Denominations are free text ('50 Pfennig', '1 Million Mark'), so a
# plain text sort would read 1, 10, 100, 2 and would file Mark ahead of
# Pfennig. These helpers split a denomination into the three parts the
# note list sorts on: the currency family ('mark'), the worth of its
# unit within that family (Pfennig 0.01 sorts ahead of Mark 1.0), and
# the number itself (1 Million -> 1000000).
#
# Subunit -> main unit, so the small change leads: cent before dollar,
# pfennig before mark. Unlisted currencies fall back to their own name
# as the family at unit 1.0, which keeps them grouped and alphabetical
# rather than silently mis-sorted.
_CURRENCY_UNITS = {
    # German mark (the bulk of the Notgeld)
    'pfennig': ('mark', 0.01), 'pfennige': ('mark', 0.01),
    'reichspfennig': ('mark', 0.01),
    'mark': ('mark', 1.0), 'reichsmark': ('mark', 1.0),
    'goldmark': ('mark', 1.0), 'rentenmark': ('mark', 1.0),
    # Austrian / Hungarian
    'heller': ('krone', 0.01), 'filler': ('krone', 0.01),
    'krone': ('krone', 1.0), 'kronen': ('krone', 1.0),
    'korona': ('krone', 1.0),
    'groschen': ('schilling', 0.01),
    'schilling': ('schilling', 1.0), 'schillinge': ('schilling', 1.0),
    # US / dollar
    'cent': ('dollar', 0.01), 'cents': ('dollar', 0.01),
    'dollar': ('dollar', 1.0), 'dollars': ('dollar', 1.0),
    # Franc (French and Swiss)
    'centime': ('franc', 0.01), 'centimes': ('franc', 0.01),
    'rappen': ('franc', 0.01),
    'franc': ('franc', 1.0), 'francs': ('franc', 1.0),
    'franken': ('franc', 1.0),
    # Pre-decimal sterling: 12 pence to a shilling, 20 to a pound.
    'penny': ('pound', 1 / 240), 'pence': ('pound', 1 / 240),
    'shilling': ('pound', 1 / 20), 'shillings': ('pound', 1 / 20),
    'pound': ('pound', 1.0), 'pounds': ('pound', 1.0),
    # Others that turn up in the collection
    'kopek': ('ruble', 0.01), 'kopeks': ('ruble', 0.01),
    'ruble': ('ruble', 1.0), 'rubles': ('ruble', 1.0),
    'rouble': ('ruble', 1.0), 'roubles': ('ruble', 1.0),
    'centavo': ('peso', 0.01), 'centavos': ('peso', 0.01),
    'peso': ('peso', 1.0), 'pesos': ('peso', 1.0),
    'ore': ('krona', 0.01),
    'krona': ('krona', 1.0), 'kronor': ('krona', 1.0),
    'stotinka': ('lev', 0.01), 'stotinki': ('lev', 0.01),
    'lev': ('lev', 1.0), 'leva': ('lev', 1.0),
    'para': ('dinar', 0.01),
    'dinar': ('dinar', 1.0), 'dinara': ('dinar', 1.0),
    'dinars': ('dinar', 1.0),
    # Indian subcontinent: 16 annas to the rupee.
    'anna': ('rupee', 1 / 16), 'annas': ('rupee', 1 / 16),
    'rupee': ('rupee', 1.0), 'rupees': ('rupee', 1.0),
    'rupia': ('rupee', 1.0), 'rupien': ('rupee', 1.0),
    'rial': ('rial', 1.0), 'rials': ('rial', 1.0),
    'riyal': ('rial', 1.0), 'riyals': ('rial', 1.0),
    # Israel: 1000 pruta to the (Israel) pound — country sorts first,
    # so the sterling collision never surfaces.
    'pruta': ('pound', 0.001), 'prutot': ('pound', 0.001),
}
_DENOM_SCALES = {
    'tausend': 1e3,
    'million': 1e6, 'millionen': 1e6,
    'milliarde': 1e9, 'milliarden': 1e9,
    # German 'Billion' is 1e12, not the English 1e9.
    'billion': 1e12, 'billionen': 1e12,
}
# 1.000 / 1,000 are thousands separators; 1.5 / 1,5 are decimals. Three
# trailing digits is the only reliable tell between them.
_DENOM_THOUSANDS_RE = re.compile(r'(?<=\d)[.,](?=\d{3}(?:\D|$))')
_DENOM_FRACTION_RE = re.compile(r'(\d+)\s*/\s*(\d+)')
_DENOM_NUMBER_RE = re.compile(r'\d+(?:[.,]\d+)?')
# Sorts blank/unparseable denominations last, matching the 'zzz' and
# 99999 blanks-last convention the rest of CATEGORY_ORDER_BY uses.
_DENOM_VALUE_LAST = 1e18


def _denom_value(text):
    """Numeric value of a denomination: '50 Pfennig' -> 50.0,
    '1 Million Mark' -> 1e6, '1/2 Mark' -> 0.5. Blank or numberless
    text sorts last."""
    s = _strip_diacritics(text).strip()
    if not s:
        return _DENOM_VALUE_LAST
    frac = _DENOM_FRACTION_RE.search(s)
    if frac:
        num, den = float(frac.group(1)), float(frac.group(2))
        base = num / den if den else num
    else:
        m = _DENOM_NUMBER_RE.search(_DENOM_THOUSANDS_RE.sub('', s))
        if not m:
            return _DENOM_VALUE_LAST
        base = float(m.group(0).replace(',', '.'))
    scale = 1.0
    for word in s.split():
        if word in _DENOM_SCALES:
            scale = _DENOM_SCALES[word]
            break
    return base * scale


def _denom_lookup(text):
    """(family, unit worth) for a denomination's currency. Unknown
    currencies become their own family at unit 1.0; blank sorts last."""
    s = _strip_diacritics(text)
    s = _DENOM_FRACTION_RE.sub(' ', s)
    s = _DENOM_NUMBER_RE.sub(' ', s)
    words = [w.strip('.,-/') for w in s.split()]
    words = [w for w in words if w and w not in _DENOM_SCALES]
    for w in words:
        if w in _CURRENCY_UNITS:
            return _CURRENCY_UNITS[w]
    # Unknown currency: fold a trailing plural 's' so '2 Rupees' and
    # '1 Rupee' land in ONE family instead of two adjacent ones.
    folded = [w[:-1] if len(w) > 3 and w.endswith('s') else w
              for w in words]
    return (' '.join(folded), 1.0) if folded else ('zzz', 1.0)


def _denom_currency(text):
    """Currency family of a denomination: '1 Million Mark' and
    '50 Pfennig' both -> 'mark', so a town's German notes group
    together before splitting by unit."""
    return _denom_lookup(text)[0]


def _denom_unit(text):
    """Worth of the denomination's unit within its family: Pfennig
    0.01, Mark 1.0. Sorting on this puts the change before the note."""
    return _denom_lookup(text)[1]


# A note's series is a free-text label ('Series of 1896 (Educational
# Series)', 'Series of 1880', or just '1896'); its embedded year is the
# meaningful sort key, so the same issue-year groups regardless of how
# the label was typed. Matches a 4-digit 1600s-2099 year.
_SERIES_YEAR_RE = re.compile(r'\b(1[6-9]\d\d|20\d\d)\b')


def _series_year(text):
    """Year embedded in a series label, for sorting: 'Series of 1896
    (Educational Series)' and '1896' both -> 1896. Fractional Currency
    issue labels ('Fourth Issue') map to the issue's actual start year
    (1869) — such notes carry the authorizing Act's date (1863), which
    would file them out of order. Returns None when the series carries
    no year, so the caller falls back to the note's own date."""
    if not text:
        return None
    m = _SERIES_YEAR_RE.search(str(text))
    if m:
        return int(m.group(1))
    issue = _fractional_issue(text)
    return issue[0] if issue else None


# ── US series panels ────────────────────────────────────────────────────
#
# A header block that precedes each series in the US banknote list: what
# class of note it is, who stood behind it, what the note actually promised
# to pay, and what was happening at the time that produced it.
#
# The class is not a structured field — issue_type only carries the
# National / Notgeld / Colonial axis — so it is read out of the text the
# note itself carries (series label, issuer, and the transcribed lettering,
# which is where "GOLD CERTIFICATE" or "NATIONAL CURRENCY" actually
# appears). Patterns are ordered most-specific first: a Federal Reserve
# Bank Note is not a Federal Reserve Note, and the two differ on exactly
# the point this panel exists to explain — who is liable.

US_COUNTRY_NAMES = {
    'united states', 'united states of america', 'usa', 'us', 'u.s.',
    'u.s.a.', 'united states of america (usa)',
}


def _is_us_note(row):
    country = (_row_get(row, 'country') or '').strip().lower().rstrip('.')
    if country in US_COUNTRY_NAMES or country.rstrip('.') in US_COUNTRY_NAMES:
        return True
    return country.startswith('united states')


