                  "COALESCE(NULLIF(country, ''), 'zzz') COLLATE NODIACRITIC, "
                  "COALESCE(NULLIF(municipality, ''), 'zzz') COLLATE NODIACRITIC, "
                  "DENOM_CURRENCY(denomination) COLLATE NODIACRITIC, "
