def _first_configured_env(names):
    if not names:
        return ''
    if isinstance(names, str):
        names = (names,)
    for name in names:
        configured = (os.environ.get(name) or '').strip()
        if configured:
            return configured
    return ''


def perplexity_lookup_model(env_names=None, default='sonar-pro'):
    return (_first_configured_env(env_names) or
            (os.environ.get('PERPLEXITY_LOOKUP_MODEL') or '').strip() or
            default)


def perplexity_search_context(env_names=None, default='high'):
    configured = (_first_configured_env(env_names) or
                  (os.environ.get('PERPLEXITY_SEARCH_CONTEXT_SIZE') or '').strip() or
                  default)
    configured = configured.lower()
    return configured if configured in {'low', 'medium', 'high'} else default


def perplexity_chat_completion(api_key, prompt, *, env_names=None,
                               default_model='sonar-pro', max_tokens=2048,
                               response_schema=None, schema_name='lookup',
                               search_context_env_names=None,
                               default_search_context='high', images=None):
    """Call Perplexity's search-grounded chat endpoint with retries.

    ``images`` (optional) is a list of ``{label, data, media_type}`` from
    _load_coin_vision_images; when given they're sent as base64 image_url
    content blocks ahead of the prompt so Sonar can see the actual item.
    """
    import urllib.request
    import urllib.error
    import time as _time

    if images:
        user_content = []
        for img in images:
            user_content.append({'type': 'text', 'text': f'{img["label"].capitalize()} of THIS coin:'})
            user_content.append({'type': 'image_url', 'image_url': {
                'url': f'data:{img["media_type"]};base64,{img["data"]}'}})
        user_content.append({'type': 'text', 'text': prompt})
    else:
        user_content = prompt

    body_data = {
        'model': perplexity_lookup_model(env_names, default_model),
        'messages': [{'role': 'user', 'content': user_content}],
        'max_tokens': max_tokens,
        'temperature': 0.1,
        'web_search_options': {
            'search_context_size': perplexity_search_context(
                search_context_env_names, default_search_context),
        },
    }
    if response_schema is not None:
        body_data['response_format'] = {
            'type': 'json_schema',
            'json_schema': {
                'name': schema_name,
                'schema': response_schema,
            },
        }
    body = json.dumps(body_data).encode('utf-8')

    last_err = None
    for attempt in range(3):
        req = urllib.request.Request(
            PERPLEXITY_CHAT_COMPLETIONS_URL,
            data=body,
            headers={
                'Authorization': f'Bearer {api_key}',
                'Content-Type': 'application/json',
                'Accept': 'application/json',
            },
            method='POST',
        )
        try:
            with urllib.request.urlopen(req, timeout=240) as resp:
                api_data = json.loads(resp.read().decode('utf-8'))
            try:
                text = api_data['choices'][0]['message']['content'] or ''
            except (KeyError, IndexError, TypeError):
                raise RuntimeError(
                    f'Unexpected Perplexity response: {str(api_data)[:200]}')
            return api_data, text.strip()
        except urllib.error.HTTPError as e:
            last_err = e
            if e.code == 429 or 500 <= e.code < 600:
                wait = 10 * (attempt + 1)
                try:
                    ra = e.headers.get('retry-after') if getattr(e, 'headers', None) else None
                    if ra:
                        wait = max(wait, int(float(ra)))
                except Exception:
                    pass
                _time.sleep(wait)
                continue
            try:
                detail = e.read().decode('utf-8', 'ignore')[:200]
            except Exception:
                detail = ''
            raise RuntimeError(f'Perplexity HTTP {e.code}: {detail}')
        except urllib.error.URLError as e:
            last_err = e
            _time.sleep(10 * (attempt + 1))
    raise RuntimeError(f'Lookup failed after retries: {last_err}')


def _require_anthropic_key():
    """Return the Anthropic API key, or raise RuntimeError if unset. The
    `import anthropic` stays inline at each call site — the module name is
    referenced by the retry/except blocks there, so it can't move here."""
    api_key = os.environ.get('ANTHROPIC_API_KEY')
    if not api_key:
        raise RuntimeError('ANTHROPIC_API_KEY not configured')
    return api_key
    return api_key


def _message_text(resp):
    """Concatenate the text blocks of an Anthropic Messages response into
    one string (non-text blocks — tool_use, etc. — are skipped)."""
    return ''.join(b.text for b in resp.content
                   if getattr(b, 'type', None) == 'text')


def parse_model_json_object(text):
    text = (text or '').strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass
    m = re.search(r'\{.*\}', text, re.DOTALL)
    if not m:
        raise RuntimeError(f'Could not parse JSON from model output: {text[:200]}')
    return json.loads(m.group(0))


def _coerce_number(value):
    if value is None:
        return None
    try:
        return float(value)
    except (ValueError, TypeError):
        return None


def fetch_watch_valuation_anthropic(watch):
    """Use Claude's web_search tool to estimate current market value.

    Returns dict {value: float|None, results: str}. Raises RuntimeError
    on missing key or API failure.
    """
    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed. Run 'pip install anthropic'.")

    brand = (watch['brand'] or '').strip()
    model = (watch['model'] or '').strip()
    reference = (watch['reference'] or '').strip()
    year = watch['year']
    metal = (watch['metal'] or '').strip()
    description = (watch['description'] or '').strip()

    ident = ' '.join(x for x in [brand, model, f'Ref. {reference}' if reference else '',
                                 f'({metal})' if metal else '',
                                 str(year) if year else ''] if x)

    prompt = f"""You are valuing a specific wristwatch from public web data.

Watch: {ident}
Description: {(description[:280] + '…') if len(description) > 280 else description or '(none)'}

Use at most 5 concise web searches. Focus on:
- Chrono24 active listings for this reference (one search; note median/range)
- WatchCharts market data / price history for this reference (one search)
- One recent auction result (Phillips, Christie's, Sotheby's, Antiquorum, or Bonhams)
- Watchbox or A Collected Man if this reference is listed (one search combined)

Compute a consensus USD value (central estimate of the comps found).
Also capture the WatchCharts market median specifically, if that page publishes one for this reference.

Reply with ONLY a JSON object, no prose, no code fences:
{{"consensus_usd": 12345, "watchcharts_median_usd": 12000, "results_markdown": "- Chrono24 (N listings, median): $X,XXX — URL\\n- WatchCharts median: $X,XXX — URL\\n- Phillips, Month YYYY: $X,XXX — URL\\n- ..."}}

results_markdown rules:
- 3–6 bullet lines for comps that have a URL source (prefix each with '- ').
- You MAY add 1–2 short plain (non-bullet) lines of context above or below the comps when it's useful — e.g. rarity / production numbers, condition-sensitive caveats, or noting why a comp doesn't apply. These don't need a URL.
- Keep the whole field under ~600 chars.
- Use null for consensus_usd / watchcharts_median_usd if not available."""

    client = anthropic.Anthropic(api_key=api_key)
    lookup_model = anthropic_lookup_model(api_key, 'ANTHROPIC_WATCH_LOOKUP_MODEL')
    web_search = anthropic_web_search_tool(5)

    import time as _time
    last_err = None
    for attempt in range(3):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=1536,
                tools=[web_search],
                messages=[{'role': 'user', 'content': prompt}],
            )
            break
        except anthropic.RateLimitError as e:
            last_err = e
            # honour Retry-After if present, else exponential backoff
            wait = 10 * (attempt + 1)
            try:
                ra = e.response.headers.get('retry-after') if getattr(e, 'response', None) else None
                if ra: wait = max(wait, int(float(ra)))
            except Exception:
                pass
            _time.sleep(wait)
    else:
        raise RuntimeError(f'Rate limited after retries: {last_err}')

    # Concatenate all text blocks in the final assistant message
    text = _message_text(resp)
    text = text.strip()

    # Strip possible markdown code fences
    m = re.search(r'\{.*\}', text, re.DOTALL)
    if not m:
        raise RuntimeError(f'Could not parse JSON from model output: {text[:200]}')
    data = json.loads(m.group(0))

    def _num(x):
        if x is None:
            return None
        try:
            return float(x)
        except (ValueError, TypeError):
            return None

    consensus = _num(data.get('consensus_usd'))
    wc_median = _num(data.get('watchcharts_median_usd'))
    orig_price = _num(watch['price'])

    # Fallback chain: AI consensus → WatchCharts median → original purchase price
    value = consensus
    fallback_note = None
    if value is None:
        if wc_median is not None:
            value = wc_median
            fallback_note = (f"_No consensus computed — defaulted to WatchCharts median "
                             f"(${wc_median:,.0f})._")
        elif orig_price is not None:
            value = orig_price
            fallback_note = (f"_No consensus or WatchCharts median found — defaulted to "
                             f"original purchase price (${orig_price:,.0f})._")

    # Models sometimes emit HTML entities (&#39;, &amp;, etc.) in JSON string
    # values. Decode them once so the downstream format_results filter only
    # performs a single round of HTML-escaping when rendering.
    import html as _html
    results_md = _html.unescape(data.get('results_markdown') or '')
    if fallback_note:
        results_md = (results_md + '\n\n' + fallback_note).strip()
    return {'value': value, 'results': results_md}


def fetch_watch_valuation_perplexity(watch):
    """Use Perplexity/Sonar Pro to estimate current watch market value."""
    api_key = os.environ.get('PERPLEXITY_API_KEY')
    if not api_key:
        raise RuntimeError('PERPLEXITY_API_KEY not configured')

    brand = (watch['brand'] or '').strip()
    model = (watch['model'] or '').strip()
    reference = (watch['reference'] or '').strip()
    year = watch['year']
    metal = (watch['metal'] or '').strip()
    description = (watch['description'] or '').strip()

    if not (brand or model or reference):
        raise RuntimeError('Need at least brand, model, or reference to fetch value.')

    ident = ' '.join(x for x in [
        brand, model, f'Ref. {reference}' if reference else '',
        f'({metal})' if metal else '', str(year) if year else '',
    ] if x)

    prompt = f"""You are valuing a specific wristwatch from current public web data.

Watch: {ident}
Description: {(description[:280] + '…') if len(description) > 280 else description or '(none)'}

Use high-quality, current web results. Focus on:
- Chrono24 active listings for this reference (note median/range when available)
- WatchCharts market data / price history for this reference
- Recent auction results (Phillips, Christie's, Sotheby's, Antiquorum, Bonhams)
- WatchBox / The 1916 Company or A Collected Man if this reference is listed

Compute a consensus USD value (central estimate of the comps found).
Also capture the WatchCharts market median specifically, if that page publishes one for this reference.

Reply with ONLY a JSON object matching the requested schema:
{{"consensus_usd": 12345, "watchcharts_median_usd": 12000, "results_markdown": "- Chrono24 (N listings, median): $X,XXX — URL\\n- WatchCharts median: $X,XXX — URL\\n- Phillips, Month YYYY: $X,XXX — URL\\n- ..."}}

results_markdown rules:
- 3–6 bullet lines for comps that have a URL source (prefix each with '- ').
- You MAY add 1–2 short plain (non-bullet) lines of context above or below the comps when useful, e.g. rarity, production numbers, condition caveats, or why a comp does not apply.
- Keep the whole field under ~700 chars.
- Use null for consensus_usd / watchcharts_median_usd if not available."""

    api_data, text = perplexity_chat_completion(
        api_key,
        prompt,
        env_names=('PERPLEXITY_WATCH_VALUE_MODEL',
                   'PERPLEXITY_WATCH_LOOKUP_MODEL'),
        default_model='sonar-pro',
        max_tokens=1536,
        response_schema=WATCH_VALUE_RESPONSE_SCHEMA,
        schema_name='watchValue',
        search_context_env_names=('PERPLEXITY_WATCH_VALUE_SEARCH_CONTEXT',
                                  'PERPLEXITY_WATCH_SEARCH_CONTEXT'),
        default_search_context='high',
    )
    data = parse_model_json_object(text)

    consensus = _coerce_number(data.get('consensus_usd'))
    wc_median = _coerce_number(data.get('watchcharts_median_usd'))
    orig_price = _coerce_number(watch['price'])

    value = consensus
    fallback_note = None
    if value is None:
        if wc_median is not None:
            value = wc_median
            fallback_note = (f"_No consensus computed — defaulted to WatchCharts median "
                             f"(${wc_median:,.0f})._")
        elif orig_price is not None:
            value = orig_price
            fallback_note = (f"_No consensus or WatchCharts median found — defaulted to "
                             f"original purchase price (${orig_price:,.0f})._")

    import html as _html
    results_md = _html.unescape(data.get('results_markdown') or '').strip()
    citations = api_data.get('citations') or []
    if citations and 'http' not in results_md.lower():
        results_md = (results_md + '\n\nCitations: ' +
                      '; '.join(citations[:6])).strip()
    if fallback_note:
        results_md = (results_md + '\n\n' + fallback_note).strip()
    return {'value': value, 'results': results_md}


def fetch_watch_valuation(watch):
    """Fetch value with Perplexity/Sonar Pro by default, Claude as fallback."""
    if os.environ.get('PERPLEXITY_API_KEY'):
        return fetch_watch_valuation_perplexity(watch)
    if os.environ.get('ANTHROPIC_API_KEY'):
        return fetch_watch_valuation_anthropic(watch)
    raise RuntimeError('PERPLEXITY_API_KEY or ANTHROPIC_API_KEY not configured')


WATCH_SPEC_SOURCES = [
    "manufacturer's official website",
    "chrono24.com",
    "watchbox / thewatchbox.com",
    "calibercorner.com",
    "17jewels.info",
    "sjx.com.sg",
    "emmywatch.com",
    "thewatchpages.com",
    "hodinkee.com",
    "monochrome-watches.com",
    "watch-wiki.org / wikipedia watch entries",
]

# When the watch already has a calibre value, the lookup can go
# straight to calibre-specific reference sites for movement detail
# (jewels, escapement, beat, reserve). These two cover the long tail
# of obscure references better than the generalist watch sites.
WATCH_CALIBRE_SOURCES = [
    "calibercorner.com",
    "17jewels.info",
]


def fetch_watch_specs(watch):
    """Use Perplexity's web-search-grounded completions to look up a
    watch's specs from reputable sources and return {field: value}
    suggestions.

    Perplexity is search-first by design — every response is grounded
    in web results — and in side-by-side testing against Anthropic's
    web_search tool it tends to surface more reference / movement
    detail per query. Prompt and return shape are unchanged from the
    Claude version so the calling code (apply-lookup propagation,
    field-by-field validation, blank-only rules) doesn't need to know.

    Only fields the model is confident about should be populated; all
    others come back null. Raises RuntimeError on missing key or
    API failure.
    """
    api_key = os.environ.get('PERPLEXITY_API_KEY')
    if not api_key:
        raise RuntimeError('PERPLEXITY_API_KEY not configured')

    brand = (watch['brand'] or '').strip()
    model = (watch['model'] or '').strip()
    reference = (watch['reference'] or '').strip()
    calibre_hint = (watch['calibre'] or '').strip()
    case_num = (watch['case_num'] or '').strip()
    movement_num = (watch['movement_num'] or '').strip()
    purchase_date = (watch['date'] or '').strip()
    description = (watch['description'] or '').strip()
    notes = (watch['notes'] or '').strip()
    year_hint = watch['year']

    if not (brand or model or reference):
        raise RuntimeError('Need at least brand, model, or reference to look up specs.')

    ident = ' '.join(x for x in [
        brand, model,
        f'Ref. {reference}' if reference else '',
        f'Cal. {calibre_hint}' if calibre_hint else '',
        f'Case {case_num}' if case_num else '',
        f'Movement {movement_num}' if movement_num else '',
        str(year_hint) if year_hint else '',
    ] if x)

    sources_bullets = '\n'.join(f'- {s}' for s in WATCH_SPEC_SOURCES)
    metals = ', '.join(VALUE_LISTS['metal_watch'])
    origins = ', '.join(VALUE_LISTS['movement_origin'])
    escapements = ', '.join(VALUE_LISTS['escapement'])
    complications = ', '.join(COMPLICATIONS_OPTIONS)

    # When the record already has a calibre, point the searcher at
    # the two calibre-specific reference sites for movement detail
    # (jewels / escapement / beat / reserve). They cover obscure
    # references better than the generalist watch sites.
    if calibre_hint:
        calibre_sources_bullets = '\n'.join(
            f'- {s}' for s in WATCH_CALIBRE_SOURCES
        )
        calibre_hint_block = (
            f"\nThe calibre is already known: {calibre_hint}. For "
            f"movement-detail fields (movement_jewels, escapement, "
            f"balance_wheel, beat, reserve, movement_type, "
            f"movement_origin, calibre_notes) prefer these "
            f"calibre-specific sources first:\n"
            f"{calibre_sources_bullets}\n"
        )
    else:
        calibre_hint_block = ''

    prompt = f"""You are filling in specification fields for a specific wristwatch using reputable public sources.

Watch: {ident}
Record context that may contain piece-specific dating evidence:
- Description: {(description[:300] + '…') if len(description) > 300 else description or '(none)'}
- Notes: {(notes[:220] + '…') if len(notes) > 220 else notes or '(none)'}

Use at most 6 web searches, preferring these sources (roughly in order):
{sources_bullets}
{calibre_hint_block}
For each field below, return the value you find in any of those sources. If one reputable source states a value clearly, use it; do not require unanimous agreement. Return null only when NO source you searched mentions the field at all. Prefer sourced values over leaving fields null.

Target fields:
- metal: one of [{metals}]
- case_diameter: number in mm (float)
- dial_color: short string (e.g. "Black", "Blue", "Silver")
- year: integer production year of THIS individual watch, not the model/reference introduction year. Only return a year when you can derive it from piece-specific evidence: case/serial number, movement number when present (common for Lange and a few others, not most brands), papers, archive extract, warranty card, certificate, or a brand serial-to-year table. If sources only say when the reference/model was introduced or produced generally, return null. Never return a year later than the purchase date ({purchase_date or 'unknown'}).
- year_basis: one short phrase explaining the evidence for year, e.g. "movement number dates to 2003 via Omega serial table" or null. If year is null, year_basis must be null.
- edition: total count of pieces in a limited edition / limited run (integer). Return null for non-limited / open-production references.
- calibre: movement calibre name in its complete canonical form, with the manufacturer prefix when one is conventionally used (e.g. "F.P. Journe Calibre 1300.3", "A. Lange & Söhne L951.5", "ETA 7750", "Frédéric Piguet 1185", "Patek Philippe CH 29-535 PS"). Avoid returning just a bare number ("1304", "7750") — those are ambiguous because multiple manufacturers reuse number-style designations. CRITICAL: the case/reference number is NOT the calibre. The "Ref." value above is the case reference (e.g. Lange 1815 Chronograph references like 414.031 / 414.028 / 401.026; Patek Nautilus 5711/1A) — never copy that value into this field. The calibre is the MOVEMENT designation (Lange L951.5, Patek 26-330, Rolex 3135, etc.) and is published on calibercorner.com / 17jewels.info / brand technical sheets, not on retailer reference pages. If sources only mention the reference and don't disclose the movement calibre, return null.
- movement_type: one of ["Manual", "Automatic", "Quartz", "Spring Drive", "Co-Axial", "Tuning Fork"]. "Manual"/"Automatic" for traditional mechanical, "Quartz" for battery-powered crystal-regulated, "Spring Drive" only for Seiko/Grand Seiko Spring Drive, "Co-Axial" only for Omega watches the brand explicitly markets as Co-Axial, "Tuning Fork" for Bulova Accutron and similar hum movements.
- movement_origin: EXACTLY one of [{origins}] and nothing else. "In-House" = designed and made by the manufacturer; "Ébauche" = bought-in rough movement (e.g. ETA, Sellita, Valjoux) used as-is; "Modified" = an ébauche that has been noticeably reworked. Do not invent values like "Swiss" or "Ebauche-based".
- movement_jewels: integer
- escapement: EXACTLY one of [{escapements}]. Do NOT assume — return null when no source mentions the escapement. But when a source explicitly names one (e.g. "Swiss Lever escapement", "lever escapement", "anchor escapement", "Co-Axial", "natural escapement", "constant-force escapement", "detent", "tuning fork", "quartz"), you MUST return the matching enum — silence in that case is a bug. "Swiss Lever" is the canonical lever-escapement bucket; map "lever", "Swiss lever", "anchor", "straight-line lever" all to "Swiss Lever". "Co-Axial" only for Omega's George Daniels-derived escapement. "Natural" for Breguet's natural escapement (also revived by Daniels and others). "Constant Force" for Lange Zeitwerk, Romain Gauthier, F.P. Journe Chronomètre Optimum-style. "Detent" / "Chronometer" for marine/pivoted-detent escapements. "Cylinder", "Verge", "Pin Lever", "Duplex" for vintage/historical pieces. "Tuning Fork" for Accutron / Bulova hum movements. "Quartz" for quartz watches. "Other" only if a clearly novel escapement is named (e.g. Genequand silicon, Ulysse Nardin Anchor) and none above fit.
- balance_wheel: short text describing the regulating organ — balance wheel AND its hairspring/balance-spring together, including material, construction, and any notable detail. Examples: "Glucydur with regulating screws", "Beryllium copper, free-sprung", "Variable-inertia gold mass with silicon hairspring", "Modern bimetallic screw balance paired with contemporary balance spring, both selected and tuned by Sekiguchi". Keep it under 160 characters. Return null only if no source mentions any balance-wheel or hairspring detail.
- beat: vibrations per hour (VPH) for mechanical movements, or raw Hz for quartz/tuning-fork movements. For mechanical (Manual/Automatic) pick from [18000, 19800, 21600, 25200, 28800, 36000, 72000]; if the source gives Hz, multiply by 7200 (2.5 Hz = 18000, 3 Hz = 21600, 4 Hz = 28800, 5 Hz = 36000, 10 Hz = 72000). For battery-powered/quartz/tuning-fork movements, return the actual rate as stated (e.g. 360 for Accutron, 32768 for a quartz crystal, 7200 for a 1 Hz stepping quartz). Do NOT assume 28800 as a default — only return a value if the source clearly states it.
- reserve: power reserve in hours (integer)
- complications: array of strings drawn from [{complications}]
- clasp_type: clasp mechanism (short string)
- lug_mm: lug width in mm (float)
- strap_material: e.g. "Leather", "Steel", "Rubber"
- notes: a 2-4 sentence quality blurb about what makes this specific reference notable — its place in the brand's history, design innovation, technical distinction, or cultural significance. Write in a knowledgeable but concise collector's voice. Keep under 500 characters. Return null only if sources offer nothing substantive.
- calibre_notes: a 1-3 sentence summary of the calibre's distinguishing features — architecture (e.g. twin barrels in parallel, going train under the dial), key complications integrated into the movement, escapement / regulator design, hand-finishing, family lineage (which calibre it evolved from), or any patented mechanisms. This is about the MOVEMENT, not the watch as a whole — write what a movement-savvy collector would want to know. Keep under 400 characters. Return null if sources don't describe the calibre's internals.

Reply with ONLY a JSON object, no prose, no code fences:
{{
  "metal": null,
  "case_diameter": null,
  "dial_color": null,
  "year": null,
  "year_basis": null,
  "edition": null,
  "calibre": null,
  "movement_type": null,
  "movement_origin": null,
  "movement_jewels": null,
  "escapement": null,
  "balance_wheel": null,
  "beat": null,
  "reserve": null,
  "complications": null,
  "clasp_type": null,
  "lug_mm": null,
  "strap_material": null,
  "notes": null,
  "calibre_notes": null,
  "sources": "one-line note of which sources hit"
}}
"""

    api_data, text = perplexity_chat_completion(
        api_key,
        prompt,
        env_names='PERPLEXITY_WATCH_LOOKUP_MODEL',
        default_model='sonar-pro',
        max_tokens=2048,
        response_schema=WATCH_SPECS_RESPONSE_SCHEMA,
        schema_name='watchSpecs',
        search_context_env_names=('PERPLEXITY_WATCH_LOOKUP_SEARCH_CONTEXT',
                                  'PERPLEXITY_WATCH_SEARCH_CONTEXT'),
        default_search_context='high',
    )
    parsed = parse_model_json_object(text)

    # Surface Perplexity's citation URLs alongside the model's own
    # one-line "sources" note. Helpful when reviewing a lookup result
    # to see which pages it actually drew from.
    citations = api_data.get('citations') or []
    if citations and isinstance(parsed, dict):
        existing = (parsed.get('sources') or '').strip()
        cite_list = '; '.join(citations[:6])
        parsed['sources'] = (f'{existing} | citations: {cite_list}'
                             if existing else f'citations: {cite_list}')
    return parsed


def _sniff_image_media_type(raw):
    """Detect a raster image's media type from its magic bytes, or None.

    The catalog images are often mislabeled (a .jpg that is really PNG bytes),
    and the vision APIs reject a media_type that doesn't match the actual bytes,
    so trust the content over the file extension.
    """
    if raw[:8] == b'\x89PNG\r\n\x1a\n':
        return 'image/png'
    if raw[:3] == b'\xff\xd8\xff':
        return 'image/jpeg'
    if raw[:6] in (b'GIF87a', b'GIF89a'):
        return 'image/gif'
    if raw[:4] == b'RIFF' and raw[8:12] == b'WEBP':
        return 'image/webp'
    return None


# Anthropic rejects any image whose base64 payload exceeds 10 MB and
# recommends <=1568 px on the long edge. Keep a safety margin under the hard
# limit so a large catalog scan never trips a 400 on the whole request.
_VISION_IMAGE_B64_CAP = 4_500_000   # ~4.5 MB base64 (~3.4 MB of image bytes)
_VISION_IMAGE_MAX_EDGE = 1568


def _fit_vision_image(raw, media_type):
    """Return ``(base64_data, media_type)`` for a vision API call, shrinking the
    image when its base64 would exceed the size cap. Small images pass through
    untouched; oversized ones are downscaled to <=1568 px and re-encoded as
    progressively-more-compressed JPEG until they fit."""
    import base64
    b64 = base64.b64encode(raw).decode('ascii')
    if len(b64) <= _VISION_IMAGE_B64_CAP:
        return b64, media_type
    try:
        import io
        from PIL import Image, ImageOps
        with Image.open(io.BytesIO(raw)) as im:
            im = ImageOps.exif_transpose(im)
            if im.mode not in ('RGB', 'L'):
                im = im.convert('RGB')
            longest = max(im.size)
            if longest > _VISION_IMAGE_MAX_EDGE:
                scale = _VISION_IMAGE_MAX_EDGE / float(longest)
                im = im.resize((max(1, round(im.width * scale)),
                                max(1, round(im.height * scale))),
                               Image.LANCZOS)
            last = b64
            for quality in (85, 75, 65, 55, 45):
                buf = io.BytesIO()
                im.save(buf, format='JPEG', quality=quality, optimize=True)
                last = base64.b64encode(buf.getvalue()).decode('ascii')
                if len(last) <= _VISION_IMAGE_B64_CAP:
                    return last, 'image/jpeg'
            return last, 'image/jpeg'
    except Exception:
        # If PIL can't process it, hand back the original encoding — no worse
        # than before, and the other image (if any) may still go through.
        return b64, media_type


_VISION_EXT_MEDIA = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
    'png': 'image/png', 'webp': 'image/webp', 'gif': 'image/gif',
}


def _load_vision_images(items):
    """Base64-encode a record's images for a vision API call, downscaling any
    that are too large (see ``_fit_vision_image``).

    ``items`` is an iterable of ``(filename, label)``. Returns a list of
    ``{label, data, media_type}`` in order, skipping anything missing on disk
    or not a supported raster type. Category-agnostic — coins and any future
    category that wants to show the model its photos share this one path.
    """
    supported = set(_VISION_EXT_MEDIA.values())
    images = []
    for name, label in items:
        if not name:
            continue
        path = os.path.join(UPLOAD_FOLDER, name)
        if not os.path.exists(path):
            continue
        try:
            with open(path, 'rb') as fh:
                raw = fh.read()
        except Exception:
            continue
        # Trust the actual bytes over the extension — a .jpg holding PNG bytes
        # otherwise makes the vision API reject the whole request (HTTP 400).
        media_type = _sniff_image_media_type(raw) or _VISION_EXT_MEDIA.get(
            os.path.splitext(name)[1].lower().lstrip('.'))
        if media_type not in supported:
            continue
        data_b64, media_type = _fit_vision_image(raw, media_type)
        images.append({'label': label, 'data': data_b64,
                       'media_type': media_type})
    return images


def _load_coin_vision_images(coin):
    """Obverse/reverse images for a coin, ready for a vision API call.

    Thin wrapper over ``_load_vision_images``; shared by the image audit and
    the coin Research / Perplexity passes so they all show the model the coin.
    """
    return _load_vision_images((
        (coin['image_1'], 'obverse'),
        (coin['image_2'], 'reverse'),
    ))


def audit_coin_image_vs_description(coin):
    """Send a coin's obverse + reverse images and its catalog description
    to Claude vision and ask whether they describe the same coin.

    Returns {match: True|False|None, confidence: float|None, reason: str}.
    Returns match=None when there isn't enough material to judge.
    """
    api_key = _require_anthropic_key()
    desc = (coin['description'] or '').strip()
    if not desc:
        return {'match': None, 'confidence': None,
                'reason': 'no description on record'}
    images = _load_coin_vision_images(coin)
    if not images:
        return {'match': None, 'confidence': None,
                'reason': 'no usable images on record'}

    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed.")
    content = []
    for img in images:
        content.append({'type': 'text', 'text': f'{img["label"].capitalize()}:'})
        content.append({'type': 'image', 'source': {
            'type': 'base64',
            'media_type': img['media_type'],
            'data': img['data'],
        }})
    content.append({'type': 'text', 'text':
        f"""Catalog description for the same coin:
\"\"\"{desc}\"\"\"

Compare the image(s) above to the description. Focus on iconography
(figures, animals, legends, layout, key symbols). Wear, lighting,
angle, and minor flan differences do NOT count as mismatches. A
mismatch means the depicted subject is fundamentally different from
what the description says.

Reply with ONLY a JSON object, no prose:
{{"match": true|false, "confidence": 0.0, "reason": "one short sentence"}}"""})
    client = anthropic.Anthropic(api_key=api_key)
    resp = client.messages.create(
        model='claude-haiku-4-5-20251001',
        max_tokens=300,
        messages=[{'role': 'user', 'content': content}],
    )
    text = _message_text(resp)
    text = text.strip()
    m = re.search(r'\{.*\}', text, re.DOTALL)
    if not m:
        return {'match': None, 'confidence': None,
                'reason': f'parse error: {text[:80]}'}
    try:
        data = json.loads(m.group(0))
    except ValueError:
        return {'match': None, 'confidence': None,
                'reason': f'JSON error: {text[:80]}'}
    return {
        'match': bool(data.get('match')) if data.get('match') is not None else None,
        'confidence': data.get('confidence'),
        'reason': (data.get('reason') or '').strip(),
    }


def _coin_research_retry_settings():
    try:
        timeout = float(os.environ.get('ANTHROPIC_COIN_RESEARCH_TIMEOUT', '75'))
    except (TypeError, ValueError):
        timeout = 75.0
    try:
        attempts = int(os.environ.get('ANTHROPIC_COIN_RESEARCH_ATTEMPTS', '1'))
    except (TypeError, ValueError):
        attempts = 1
    timeout = max(20.0, min(timeout, 75.0))
    max_attempts = 2 if timeout <= 35.0 else 1
    attempts = max(1, min(attempts, max_attempts))
    return timeout, attempts


def _coin_research_int_setting(name, default, min_value, max_value):
    try:
        value = int(os.environ.get(name, default))
    except (TypeError, ValueError):
        value = default
    return max(min_value, min(value, max_value))


def _coin_research_generation_settings():
    return {
        'searches': _coin_research_int_setting(
            'ANTHROPIC_COIN_RESEARCH_SEARCHES', 2, 1, 4),
        'max_tokens': _coin_research_int_setting(
            'ANTHROPIC_COIN_RESEARCH_MAX_TOKENS', 950, 700, 1400),
    }


def _bounded_retry_wait(err, fallback, cap=15):
    wait = fallback
    try:
        ra = err.response.headers.get('retry-after') if getattr(err, 'response', None) else None
        if ra:
            wait = max(wait, int(float(ra)))
    except Exception:
        pass
    return max(1, min(wait, cap))


def _anthropic_transient_errs(anthropic):
    """Anthropic exception classes worth an automatic retry.

    529 Overloaded maps to its own OverloadedError class — NOT
    InternalServerError — so it must be listed explicitly or a transient
    capacity blip becomes a hard failure with a raw error blob in the
    user's face. The class isn't exported at the package top level in
    every SDK version, so resolve it defensively."""
    overloaded = getattr(anthropic, 'OverloadedError', None)
    if overloaded is None:
        try:
            from anthropic._exceptions import OverloadedError as overloaded
        except ImportError:
            overloaded = None
    errs = [anthropic.RateLimitError, anthropic.APIConnectionError,
            anthropic.APITimeoutError, anthropic.InternalServerError]
    if overloaded is not None:
        errs.append(overloaded)
    return tuple(errs)


def _friendly_lookup_error(label, err):
    raw = str(err or '').strip()
    if not raw:
        return f'{label} failed.'
    status_match = (
        re.search(r'\b(?:status|code|http)\D{0,12}([45]\d{2})\b', raw, re.IGNORECASE)
        or re.search(r'\b([45]\d{2})\b', raw)
    )
    status = status_match.group(1) if status_match else ''
    if re.search(r'<!doctype|<html|</html>', raw, re.IGNORECASE):
        if status:
            return f'{label} temporarily unavailable (HTTP {status}). Please try again.'
        return f'{label} temporarily unavailable. Please try again.'
    if status in {'429', '500', '502', '503', '504', '529'}:
        return f'{label} temporarily unavailable (HTTP {status}). Please try again.'
    if re.search(r'\b(?:timeout|timed out|read timed out)\b', raw, re.IGNORECASE):
        return f'{label} timed out before the public gateway limit. Please try again.'
    cleaned = re.sub(r'<[^>]+>', ' ', raw)
    cleaned = re.sub(r'\s+', ' ', cleaned).strip()
    return cleaned[:280] if cleaned else f'{label} failed.'


COIN_CONTEXT_JOBS = {}
COIN_CONTEXT_JOBS_LOCK = threading.Lock()
COIN_CONTEXT_JOB_TTL_SECONDS = 60 * 60


def _prune_coin_context_jobs(now_ts=None):
    now_ts = now_ts or time.time()
    stale_before = now_ts - COIN_CONTEXT_JOB_TTL_SECONDS
    for job_id, job in list(COIN_CONTEXT_JOBS.items()):
        if job.get('updated_ts', job.get('started_ts', now_ts)) < stale_before:
            COIN_CONTEXT_JOBS.pop(job_id, None)


def _set_coin_context_job(job_id, **updates):
    now_ts = time.time()
    updates['updated_ts'] = now_ts
    with COIN_CONTEXT_JOBS_LOCK:
        job = COIN_CONTEXT_JOBS.setdefault(job_id, {})
        job.update(updates)
        _prune_coin_context_jobs(now_ts)
        return dict(job)


def _get_coin_context_job(job_id):
    with COIN_CONTEXT_JOBS_LOCK:
        _prune_coin_context_jobs()
        job = COIN_CONTEXT_JOBS.get(job_id)
        return dict(job) if job else None


def _store_coin_context_result(record_id, coin, markdown):
    now = datetime.utcnow().isoformat()
    history_context, reference_notes = _split_coin_context_markdown(markdown)
    condition = _merge_coin_condition_history(coin.get('condition'), history_context)
    db = open_db_connection()
    try:
        db.execute(
            "UPDATE coins SET condition = ?, history_context = NULL, "
            "coin_references_research = ?, history_searched_at = ?, "
            "updated_at = ? WHERE id = ?",
            (condition, reference_notes, now, now, record_id),
        )
        db.commit()
    finally:
        db.close()
    return {
        'status': 'done',
        'markdown': history_context,
        'condition': condition,
        'history_context': history_context,
        'reference_notes': reference_notes,
        'coin_references_research': reference_notes,
        'searched_at': now,
    }


def _run_coin_context_job(job_id, record_id, coin):
    try:
        provider = coin.pop('_research_provider', 'claude')
        if provider == 'perplexity':
            data = fetch_coin_context_perplexity(coin)
            error_label = 'Perplexity coin research lookup'
        else:
            data = fetch_coin_context(coin)
            error_label = 'Coin research lookup'
        result = _store_coin_context_result(record_id, coin, data['markdown'])
        _set_coin_context_job(
            job_id,
            status='done',
            result=result,
            completed_at=datetime.utcnow().isoformat(),
        )
    except RuntimeError as e:
        _set_coin_context_job(
            job_id,
            status='error',
            error=_friendly_lookup_error(error_label if 'error_label' in locals() else 'Coin research lookup', e),
            completed_at=datetime.utcnow().isoformat(),
        )
    except Exception as e:
        import traceback
        print(traceback.format_exc(), flush=True)
        detail = str(e) or e.__class__.__name__
        _set_coin_context_job(
            job_id,
            status='error',
            error=f'Context lookup failed: {detail}',
            completed_at=datetime.utcnow().isoformat(),
        )


COIN_CONTEXT_PREAMBLE_RE = re.compile(
    r'^(?:now i have sufficient information to write (?:the|this) profile\.?|'
    r'here is the requested profile\.?|here is the coin profile\.?)$',
    re.IGNORECASE,
)


def _strip_markdown_wrappers(value):
    """Remove model wrapper tags and setup chatter from coin context notes."""
    text = (value or '').strip()
    if not text:
        return ''
    text = re.sub(r'&lt;/?\s*markdown\s*&gt;', '', text, flags=re.IGNORECASE)
    text = re.sub(r'</?\s*markdown\s*>', '', text, flags=re.IGNORECASE)
    lines = text.splitlines()
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and COIN_CONTEXT_PREAMBLE_RE.match(lines[0].strip()):
        lines.pop(0)
        while lines and not lines[0].strip():
            lines.pop(0)
    text = '\n'.join(lines).strip()
    return re.sub(r'\n{3,}', '\n\n', text)


def _coin_context_response_markdown(text):
    text = (text or '').strip()
    md = ''
    m = re.search(r'<markdown>(.*?)</markdown>', text, re.DOTALL | re.IGNORECASE)
    if m:
        md = m.group(1).strip()
    else:
        m = re.search(r'\{.*\}', text, re.DOTALL)
        if m:
            try:
                data = json.loads(m.group(0))
                md = (data.get('markdown') or '').strip()
            except ValueError:
                md = ''
        if not md:
            md = text
    if not md:
        raise RuntimeError(f'Empty response from model: {text[:200]}')
    import html as _html
    md = _html.unescape(md).strip()
    md = re.sub(r'</?cite\b[^>]*>', '', md, flags=re.IGNORECASE)
    return _strip_markdown_wrappers(md)


def _coin_context_inputs(coin):
    region = (_coin_row_value(coin, 'region') or '').strip()
    authority = (_coin_row_value(coin, 'authority') or '').strip()
    mint = (_coin_row_value(coin, 'mint') or '').strip()
    desc = (_coin_row_value(coin, 'description') or '').strip()
    refs = (_coin_row_value(coin, 'coin_references') or '').strip()
    grade_notes = (_coin_row_value(coin, 'notes') or '').strip()
    date_1_text = (_coin_row_value(coin, 'date_1_text') or '').strip()
    date_2_text = (_coin_row_value(coin, 'date_2_text') or '').strip()
    date_hint = ''
    if date_1_text or date_2_text:
        date_hint = date_1_text
        if date_2_text:
            date_hint = f"{date_hint} – {date_2_text}"
    if not (region or authority or mint or date_hint):
        raise RuntimeError('Fill in at least region, authority, mint, or date first.')
    return {
        'region': region,
        'authority': authority,
        'mint': mint,
        'desc': desc,
        'refs': refs,
        'grade_notes': grade_notes,
        'date_hint': date_hint,
    }


def _coin_scholarly_source_guidance(parts):
    search_text = ' '.join([
        parts.get('region') or '',
        parts.get('authority') or '',
        parts.get('mint') or '',
        parts.get('desc') or '',
        parts.get('refs') or '',
    ]).lower()
    sicily_terms = (
        'sicily', 'sicilian', 'syracuse', 'akragas', 'gela',
        'katane', 'naxos', 'selinus', 'himera', 'leontini',
        'messana', 'kamarina', 'camarina',
    )
    is_greek_sicilian = any(term in search_text for term in sicily_terms)

    lines = [
        "Source strategy for scholarly references:",
        "- Start with Newman Numismatic Portal (NNP) for digitized numismatic literature; prefer books, journals, sale catalogues, and items tied to the S&S Library / S&S digitization project when available.",
        "- Use Internet Archive collection filters when useful: collection:snslibraryrestricted, collection:s-and-s-library-restricted, and newmannumismaticrestricted.",
        "- Prefer classic corpora, monographs, sale catalogues with plates, die studies, and standard references over generic dealer summaries. Use auction archives mainly for pedigree, plate matches, and sale history.",
        "- Use S&S/NNP digitization announcements as a roadmap for scanned rare works, catalog runs, and reference shelves; when relevant, try named reference/category seeds such as Sicilian coinage, Greek coins of Sicily, Syracuse coins, Haeberlin, Mitchiner, Middendorf, Elisabeth Washburn King, Sotheby, Leu, Hess, CNG, and Roma.",
        "- Search within promising PDFs/catalogues for the exact mint, ruler, polity, magistrate, denomination, and reference numbers entered by the user.",
        "- Cite only sources you actually opened and only reference numbers you actually saw there. Do not reconstruct a plausible-looking citation, catalog number, plate, or page from memory — an unverified citation is worse than none.",
    ]
    if is_greek_sicilian:
        lines.extend([
            "- For Greek/Sicilian coins, try focused NNP and Internet Archive searches such as: Sicily tetradrachm; Akragas coinage; Gela coinage; Greek coins Syracuse; Sicily coins collection:snslibraryrestricted; Syracuse collection:s-and-s-library-restricted.",
            "- For Sicilian material, prioritize references that speak directly to Syracuse, Akragas, Gela, Katane, Naxos, and related poleis, especially plate catalogues and die-study literature.",
        ])
    return "\n".join(lines)


def _build_coin_context_prompt(coin):
    parts = _coin_context_inputs(coin)
    gen_settings = _coin_research_generation_settings()
    search_count = gen_settings['searches']
    max_tokens = gen_settings['max_tokens']
    bullet_count = '1–2' if search_count <= 2 else '1–3'
    source_count = '1–3' if search_count <= 2 else '2–4'
    char_budget = 1100 if max_tokens <= 1000 else 1600
    scholarly_source_guidance = _coin_scholarly_source_guidance(parts)

    prompt = f"""You are an ancient-numismatics historian writing a short,
factual profile of a specific coin. You have the inputs below — text fields,
plus obverse/reverse images of THIS coin when attached; weave them
together — don't just restate them. Put special weight on pedigree,
provenance, sale history, hoard context, and catalog references that are
ACTUALLY PRESENT in the record or that a source confirms. The catalog
references and grade notes often carry a lot of signal (BCD pedigree,
Calciati number, SNG / HGC / RIC / RPC / Crawford / Ravel references, hoard
provenance, strike quality, rarity call-outs); mine what is there and cite
the reference trail when it matters.

Region:      {parts['region'] or '(not specified)'}
Authority:   {parts['authority'] or '(not specified)'}
Mint:        {parts['mint'] or '(not specified)'}
Date range:  {parts['date_hint'] or '(not specified)'}
Description: {parts['desc'] or '(not specified)'}
Pedigree / References: {parts['refs'] or '(not specified)'}
Grade / Conditions:    {parts['grade_notes'] or '(not specified)'}

AUTHORITATIVE, NOT SPECULATIVE — this is the overriding rule. Every statement
must be backed by one of: the record's text above, an attached image, or a
source you actually cite with its URL. If you cannot back a claim, leave it
out. A specific value you can't verify is worse than saying nothing. Do NOT
invent, estimate, or infer from general knowledge any of:
- design elements (a named figure/allegory, portrait subject, scene, symbol,
  signature, or legend reading) — read these only off the images or the
  description/legend;
- catalog or reference numbers (KM, Davenport, Pagani, Montenegro, SNG, RIC,
  HGC, Crawford, Calciati…) — give a number only if a source confirms it,
  otherwise name the reference work without a number or omit it;
- mintage figures, rarity codes, or example counts (and never a fabricated
  "N examples per auction cycle");
- pedigree, prior sales, hoard provenance, or die studies.
Write about THIS coin, not the series in the abstract: do not attribute a
general fact about the type to this specimen as if it were specific to it.
Prefer omission over padding — "not established" / "no pedigree on record"
is a valid and preferred answer when the evidence isn't there.

{scholarly_source_guidance}

Use up to {search_count} focused web searches to ground the facts. Prefer
queries that combine the authority/mint/date with the strongest catalog
reference, so each search can support more than one section. Cover, in
this order:

1. Historical environment — the political / military situation at this
   mint during the date range; who was in power (dynasty, magistrate,
   satrap, emperor…) and what they were reacting to (war, trade boom,
   succession, reform).

2. Coin style — the iconography, engraving school, fabric / flan, and
   any artistic signatures (e.g. late-Classical Syracusan masters,
   Hellenistic realism, archaic incuse reverse, Roman provincial
   portrait conventions). Name the style when it's identifiable. Read the
   iconography off the attached images and the description / legend; do not
   name a figure, portrait, or allegory the images and inputs don't support.

3. Pedigree and reference notes — write a scholarly, catalogue-style
   discussion of the pedigree and reference information THAT IS ACTUALLY
   in the record or that a source confirms. Lead with whichever of these
   the record/sources actually support: collection pedigree, prior sale,
   hoard, die-study, catalog placement, or significance within the series
   (first portrait of a ruler, earliest use of a legend, benchmark type).
   Explain terse catalog citations the record already lists in collector-
   friendly language — e.g. for "SNG Kayhan 880; BMC Caria pg. 183, 1",
   say what each source is and what it confirms. Do not add catalog numbers
   the record doesn't have unless a cited source gives them.
   Rarity: state it ONLY when a cited source or an actual mintage figure
   supports it, and cite that basis; then you may name the standard code
   (C, S, R1–R5). A large mintage means the coin is common overall even if
   scarce in high grade — say which, and never invent an example count or a
   "per auction cycle" figure. If rarity isn't sourced, omit it.
   Skip padding; only include what actually applies.

4. How this coin reflected the times — propaganda choices, civic pride,
   response to economic or military pressure, religious festival,
   trade denomination. Tie the imagery or metal to the moment only where the
   record, the images, or a cited source supports it; do not manufacture a
   motive. If there's nothing solid to say here, keep it to one line or omit.

Write four short sections using these bold labels on their own lines:
**Historical environment**, **Style**, **Pedigree and reference notes**,
**Reflection of the times**. Each label is followed by {bullet_count}
bullets starting with '- '. Include {source_count} source URLs as trailing
bare URLs after relevant bullets. Under ~{char_budget} chars total.

Reply with ONLY one <markdown>…</markdown> block. Do not include any setup
sentence before it, do not nest another <markdown> tag inside it, and do not
include code fences or JSON."""
    return prompt, gen_settings


def fetch_coin_context(coin):
    """Claude-driven historical-environment summary for a coin, drawing
    on region, authority, mint, date, and description together.
    Returns dict {markdown: str}. Raises RuntimeError on missing key
    / API failure.
    """
    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed. Run 'pip install anthropic'.")

    prompt, gen_settings = _build_coin_context_prompt(coin)
    search_count = gen_settings['searches']
    max_tokens = gen_settings['max_tokens']

    # Show the model the actual coin so its Style / iconography section is read
    # off the images, not invented. Falls back to text-only when none are usable.
    images = _load_coin_vision_images(coin)
    if images:
        message_content = []
        for img in images:
            message_content.append({'type': 'text', 'text': f'{img["label"].capitalize()} of THIS coin:'})
            message_content.append({'type': 'image', 'source': {
                'type': 'base64', 'media_type': img['media_type'], 'data': img['data']}})
        message_content.append({'type': 'text', 'text': prompt})
    else:
        message_content = prompt

    timeout, attempts = _coin_research_retry_settings()
    client = anthropic.Anthropic(api_key=api_key, timeout=timeout)
    lookup_model = anthropic_lookup_model(
        api_key,
        ('ANTHROPIC_COIN_RESEARCH_MODEL', 'ANTHROPIC_COIN_LOOKUP_MODEL'),
        default='auto-sonnet',
        fable_fallback='sonnet',
    )
    web_search = anthropic_web_search_tool(
        search_count, default_tool='web_search_20260209')
    import time as _time
    last_err = None
    transient_errs = _anthropic_transient_errs(anthropic)
    for attempt in range(attempts):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=max_tokens,
                tools=[web_search],
                messages=[{'role': 'user', 'content': message_content}],
            )
            break
        except transient_errs as e:
            last_err = e
            wait = _bounded_retry_wait(e, 8 * (attempt + 1))
            if attempt == attempts - 1:
                raise RuntimeError(_friendly_lookup_error('Coin research lookup', last_err))
            _time.sleep(wait)
    else:
        raise RuntimeError(_friendly_lookup_error('Coin research lookup', last_err))

    text = _message_text(resp)
    text = text.strip()

    md = _coin_context_response_markdown(text)
    return {'markdown': md}


def fetch_coin_context_perplexity(coin):
    """Perplexity/Sonar research pass for the coin detail Perplexity button."""
    api_key = os.environ.get('PERPLEXITY_API_KEY')
    if not api_key:
        raise RuntimeError('PERPLEXITY_API_KEY not configured')

    prompt, gen_settings = _build_coin_context_prompt(coin)
    max_tokens = gen_settings['max_tokens']

    api_data, text = perplexity_chat_completion(
        api_key,
        prompt,
        env_names='PERPLEXITY_COIN_RESEARCH_MODEL',
        default_model='sonar-pro',
        max_tokens=max_tokens,
        search_context_env_names='PERPLEXITY_COIN_RESEARCH_CONTEXT',
        default_search_context='high',
        images=_load_coin_vision_images(coin),
    )
    md = _coin_context_response_markdown(text)
    citations = api_data.get('citations') or []
    if citations and not re.search(r'https?://', md, re.IGNORECASE):
        md = (md + '\n' + '\n'.join(citations[:3])).strip()
    return {'markdown': md}


COIN_CONTEXT_SECTION_RE = re.compile(
    r'(?im)^\s*(?:\*\*)?\s*'
    r'(Historical environment|Style|Numismatic importance|Pedigree and reference notes|Reflection of the times)'
    r'\s*(?:\*\*)?\s*:?\s*$'
)


def _split_coin_context_markdown(markdown):
    """Return (historical_context, reference_notes).

    The History lookup asks for four labeled sections. Store the
    pedigree/reference section in its own notes field, while the remaining
    sections stay in the historical-context field.
    """
    md = _strip_markdown_wrappers(markdown)
    if not md:
        return '', ''
    matches = list(COIN_CONTEXT_SECTION_RE.finditer(md))
    if not matches:
        return md, ''

    context_parts = []
    reference_parts = []
    if matches[0].start() > 0:
        context_parts.append(md[:matches[0].start()].strip())

    for idx, match in enumerate(matches):
        heading = match.group(1).strip().lower()
        next_start = matches[idx + 1].start() if idx + 1 < len(matches) else len(md)
        section_body = md[match.end():next_start].strip()
        section_text = md[match.start():next_start].strip()
        if heading in ('numismatic importance', 'pedigree and reference notes'):
            reference_parts.append(section_body)
        else:
            context_parts.append(section_text)

    historical_context = '\n\n'.join(part for part in context_parts if part).strip()
    reference_notes = '\n\n'.join(part for part in reference_parts if part).strip()
    return historical_context, reference_notes


def fetch_coin_history(field_name, topic, coin):
    """Use Claude's web_search tool to describe the history of a coin's
    region or authority. Returns dict {markdown: str}.
    Raises RuntimeError on missing key or API failure.
    """
    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed. Run 'pip install anthropic'.")

    topic = (topic or '').strip()
    if not topic:
        raise RuntimeError(f'No {field_name} set for this coin')

    date_hint = ''
    if coin['date_1_text'] or coin['date_2_text']:
        date_hint = (coin['date_1_text'] or '')
        if coin['date_2_text']:
            date_hint = f"{date_hint} – {coin['date_2_text']}"
    context_bits = [x for x in [coin['denomination'], coin['metal'], coin['mint']] if x]
    ctx = (' / '.join(context_bits)) if context_bits else ''
    kind = 'region' if field_name == 'region' else 'issuing authority'
    desc = (coin['description'] or '').strip()
    refs = (coin['coin_references'] or '').strip()
    grade_notes = (coin['notes'] or '').strip()

    prompt = f"""You are an ancient-numismatics historian summarizing the {kind} of a specific coin. Obverse/reverse images of the coin are attached when available.

{kind.capitalize()}: {topic}
Date range: {date_hint or '(not specified)'}
Other coin context: {ctx or '(none)'}
Description: {desc[:500] if desc else '(not specified)'}
Pedigree / References: {refs[:500] if refs else '(not specified)'}
Grade / Conditions: {grade_notes[:300] if grade_notes else '(not specified)'}

AUTHORITATIVE, NOT SPECULATIVE — every claim must be backed by the record
above, an attached image, or a source you actually cite with its URL. If you
can't back it, leave it out. Do not invent or estimate catalog/reference
numbers, mintage figures, rarity codes or example counts, pedigree, sales, or
die studies; an unverified specific is worse than none. Read any design detail
off the images or the description/legend, not from general knowledge.

Use up to 4 concise web searches to ground facts. Stress the pedigree and
references the record actually gives you: collection pedigree, prior sale,
hoard provenance, die-study, catalog numbers, rarity notes, or standard
references (SNG, HGC, RIC, RPC, Crawford, Ravel, Calciati, BCD, etc.). Do not
bury real evidence behind generic political history, and do not pad with
unsourced narrative.

Focus on:
- What this {kind} was (city-state, kingdom, satrapy, Roman province, etc.)
- Key political/cultural events during the coin's date range that shaped its coinage
- Notable rulers or mint activity tied to this {kind}
- Pedigree / reference evidence that helps identify why this coin matters
- One-line significance in the broader Greek/Roman world

Reply with ONLY a JSON object, no prose, no code fences:
{{"markdown": "4–7 short lines. Prefix factual claims with '- '. Lead with pedigree / reference evidence when present, then add necessary historical context. Include 2–4 source URLs as trailing bare URLs after relevant bullets. Under ~900 chars total."}}"""

    timeout, attempts = _coin_research_retry_settings()
    client = anthropic.Anthropic(api_key=api_key, timeout=timeout)
    lookup_model = anthropic_lookup_model(
        api_key,
        ('ANTHROPIC_COIN_RESEARCH_MODEL', 'ANTHROPIC_COIN_LOOKUP_MODEL'),
        default='auto-sonnet',
        fable_fallback='sonnet',
    )
    web_search = anthropic_web_search_tool(
        4, default_tool='web_search_20260209')

    # Show the model the actual coin so any design/iconography read is grounded.
    images = _load_coin_vision_images(coin)
    if images:
        message_content = []
        for img in images:
            message_content.append({'type': 'text', 'text': f'{img["label"].capitalize()} of THIS coin:'})
            message_content.append({'type': 'image', 'source': {
                'type': 'base64', 'media_type': img['media_type'], 'data': img['data']}})
        message_content.append({'type': 'text', 'text': prompt})
    else:
        message_content = prompt

    import time as _time
    last_err = None
    transient_errs = _anthropic_transient_errs(anthropic)
    for attempt in range(attempts):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=900,
                tools=[web_search],
                messages=[{'role': 'user', 'content': message_content}],
            )
            break
        except transient_errs as e:
            last_err = e
            wait = _bounded_retry_wait(e, 8 * (attempt + 1))
            if attempt == attempts - 1:
                raise RuntimeError(_friendly_lookup_error('Coin history lookup', last_err))
            _time.sleep(wait)
    else:
        raise RuntimeError(_friendly_lookup_error('Coin history lookup', last_err))

    text = _message_text(resp)
    text = text.strip()

    m = re.search(r'\{.*\}', text, re.DOTALL)
    if not m:
        raise RuntimeError(f'Could not parse JSON from model output: {text[:200]}')
    data = json.loads(m.group(0))
    import html as _html
    md = _html.unescape(data.get('markdown') or '').strip()
    # Strip Claude web_search <cite index="...">...</cite> wrappers.
    md = re.sub(r'</?cite\b[^>]*>', '', md, flags=re.IGNORECASE)
    return {'markdown': md}


def resolve_anthropic_lookup_model(api_key, configured_model, fable_fallback='opus'):
    """Resolve auto/latest lookup model settings through Anthropic's Models API."""
    model = (configured_model or '').strip() or 'auto-sonnet'
    selector = re.sub(r'[\s_]+', '-', model.lower())
    family = None
    if selector in {'latest-fable', 'auto-fable'} or selector.startswith('claude-fable-'):
        # Fable can be listed but unavailable to this API account. Use the
        # caller's preferred fallback family so public endpoints can choose
        # speed while deeper offline jobs can choose depth.
        fallback = (fable_fallback or 'opus').strip().lower()
        family = fallback if fallback in {'opus', 'sonnet', 'haiku'} else 'opus'
    elif selector in {'auto', 'latest', 'latest-sonnet', 'auto-sonnet'}:
        family = 'sonnet'
    elif selector in {'latest-opus', 'auto-opus'}:
        family = 'opus'
    elif selector in {'latest-haiku', 'auto-haiku'}:
        family = 'haiku'
    else:
        return model

    try:
        import urllib.request
        req = urllib.request.Request(
            'https://api.anthropic.com/v1/models?limit=100',
            headers={
                'x-api-key': api_key,
                'anthropic-version': '2023-06-01',
            },
        )
        with urllib.request.urlopen(req, timeout=5) as resp:
            payload = json.loads(resp.read().decode('utf-8'))
        for item in payload.get('data', []):
            model_id = (item.get('id') or '').strip()
            display_name = (item.get('display_name') or '').strip()
            haystack = f'{model_id} {display_name}'.lower()
            if model_id and family in haystack:
                return model_id
    except Exception:
        pass
    fallbacks = {
        'opus': 'claude-opus-4-8',
        'sonnet': 'claude-sonnet-4-6',
        'haiku': 'claude-haiku-4-5-20251001',
    }
    return fallbacks.get(family, model)


def anthropic_lookup_model(api_key, env_name=None, default='auto-sonnet',
                           fable_fallback='opus'):
    configured = ''
    env_names = env_name if isinstance(env_name, (tuple, list)) else [env_name]
    for name in env_names:
        if name:
            configured = os.environ.get(name) or ''
            if configured:
                break
    configured = configured or os.environ.get('ANTHROPIC_LOOKUP_MODEL') or default
    return resolve_anthropic_lookup_model(
        api_key, configured, fable_fallback=fable_fallback)


def anthropic_web_search_tool(max_uses, default_tool='web_search_20250305'):
    tool_type = (os.environ.get('ANTHROPIC_WEB_SEARCH_TOOL') or '').strip() or default_tool
    try:
        uses = int(os.environ.get('ANTHROPIC_WEB_SEARCH_MAX_USES', max_uses) or max_uses)
    except ValueError:
        uses = max_uses
    return {
        'type': tool_type,
        'name': 'web_search',
        'max_uses': uses,
    }


def _clean_recording_label(value):
    """Normalize lookup-returned record labels for the compact UI field."""
    label = re.sub(r'\s+', ' ', (value or '')).strip(' ,"\'')
    if not label:
        return ''
    label = re.sub(r'\s*/\s*', ' / ', label)
    label = re.sub(r'\s*&\s*', ' & ', label)
    label = re.sub(r'\s{2,}', ' ', label).strip()
    label = re.sub(
        r'\s*\((?:catalog(?:ue)?|cat\.?|matrix|release|reissue|imprint)\b[^)]*\)\s*',
        '',
        label,
        flags=re.IGNORECASE,
    ).strip(' ,"\'')
    return label[:80].strip()


def _recording_notes_look_generated(notes):
    """Heuristic for legacy lookup text so refreshed lookups can replace it."""
    text = (notes or '').strip()
    if not text:
        return True
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    bullet_lines = [line for line in lines if re.match(r'^[-•*]\s+', line)]
    return bool(bullet_lines) and len(bullet_lines) >= max(2, len(lines) // 2)


def fetch_recording_notes(rec):
    """Claude-driven review + historical-context summary for a recording.
    Returns dict {markdown: str}. Raises RuntimeError on missing key
    or empty model output. Uses Anthropic with web_search, output
    wrapped in <markdown>...</markdown>.
    """
    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed.")

    lookup_model = anthropic_lookup_model(api_key, 'ANTHROPIC_RECORDING_MODEL')
    web_search = anthropic_web_search_tool(4)

    title  = (rec['title']  or '').strip()
    artist = (rec['artist'] or '').strip()
    if not (title or artist):
        raise RuntimeError('Need a title or artist before fetching notes.')

    rec_type = (rec['type'] or '').strip()
    year   = (rec['year_recorded'] or '').strip()
    genre  = ' / '.join(x for x in [
        (rec['genre'] or '').strip(),
        (rec['genre_2'] or '').strip(),
    ] if x)
    try:
        label = (rec['label'] or '').strip()
    except (IndexError, KeyError):
        label = ''
    try:
        existing_notes = (rec['notes'] or '').strip()
    except (IndexError, KeyError):
        existing_notes = ''
    if existing_notes:
        # Notes can accumulate multiple lookups and personal annotations.
        # Keep enough context to disambiguate editions / personnel / label
        # clues without crowding out the lookup instructions.
        existing_notes = re.sub(r'\s+', ' ', existing_notes).strip()
        if len(existing_notes) > 1800:
            existing_notes = existing_notes[:1800].rsplit(' ', 1)[0].rstrip() + '...'
    # players column may not exist on older DBs that haven't run the
    # ALTER yet — sqlite3.Row raises IndexError on missing columns.
    try:
        players = (rec['players'] or '').strip()
    except (IndexError, KeyError):
        players = ''
    fmt_bits = [x for x in [
        (rec['type']  or '').strip(),
        (rec['speed'] or '').strip(),
        (rec['sound'] or '').strip(),
        (rec['other'] or '').strip(),
    ] if x]
    fmt = ' · '.join(fmt_bits)

    players_block = ("\nAlso return a comma-separated list of the "
                     "key musicians on this recording (lead artist + "
                     "sidemen / band members), each followed by their "
                     "primary instrument or role in parentheses — "
                     "e.g. \"John Coltrane (tenor sax), McCoy Tyner "
                     "(piano), Jimmy Garrison (bass), Elvin Jones "
                     "(drums)\". Use short instrument names (sax, not "
                     "tenor saxophone Selmer Mark VI). Wrap the list "
                     "in a <players>...</players> tag immediately "
                     "after the <markdown> block. Omit the <players> "
                     "tag entirely if you can't determine personnel "
                     "with reasonable confidence. Existing Players may "
                     "be stale; if existing notes or web sources point "
                     "to different performers for this copy, return the "
                     "corrected list.")

    # Ask for the tracklist on every lookup. Lookup is the user's
    # correction pass for the open record, so it must be able to replace
    # stale track data from a prior misidentified recording. Duplicate
    # sibling records remain fill-if-empty later because editions and
    # formats can differ.
    try:
        existing_tracks = (rec['tracks'] or '').strip()
    except (IndexError, KeyError):
        existing_tracks = ''
    want_tracks = True
    tracks_block = ("\nAlso return the tracklist for the recording, "
                    "one track title per line, in album order, no "
                    "numbering and no surrounding quotes. Wrap the "
                    "list in a <tracks>...</tracks> tag (after any "
                    "<players> tag if present). Omit the <tracks> "
                    "tag entirely if you can't recover the tracklist "
                    "with reasonable confidence. The tracklist must be "
                    "for THIS record identity. If Title/Artist/Label/"
                    "Format/Existing notes point to a different "
                    "recording than Existing Players, do not use the "
                    "tracklist from the better-known conflicting "
                    "recording; omit <tracks> unless you can verify the "
                    "current copy's tracklist.") if want_tracks else ""

    # Always verify genre + sub-genre on Lookup. The model returns its
    # best assessment regardless of whether the DB already has values.
    # Prefer the known genre list for consistency, but Genre is free
    # text in the UI and can accept values outside the historical list.
    allowed_genres = list(VALUE_LISTS.get('recording_genre', []))
    genres_csv = ', '.join(allowed_genres)
    genre_block = (
        f"\nAlso classify the recording. Return the primary genre in a "
        f"<genre>...</genre> tag. Prefer one of these known genres when "
        f"it fits: {genres_csv}. If none fits cleanly, return a concise "
        f"music-store genre value instead. If you can't decide with "
        f"reasonable confidence, omit the <genre> tag entirely. Then "
        f"return a more specific sub-genre in a <genre_2>...</genre_2> "
        f"tag (free text — e.g. \"Bebop\", \"Hard Rock\", \"Bossa Nova\", "
        f"\"Soul-Jazz\"). Omit the <genre_2> tag if no useful "
        f"sub-classification fits."
    )
    year_block = (
        "\nAlso return the best four-digit catalog year for this recording "
        "in a <year_recorded>YYYY</year_recorded> tag. Prefer the original "
        "album/release year used by music catalogs; if that is not clear, "
        "use the original recording year. Omit the tag if you can't determine "
        "a single year with reasonable confidence."
    )
    label_block = (
        "\nAlso return the record label or imprint for this album in a "
        "<recording_label>...</recording_label> tag. Prefer the label for "
        "the original release; use the specific reissue label only when the "
        "provided format or source context clearly points to a reissue. Omit "
        "the tag if you can't determine a label with reasonable confidence."
    )
    vinyl_pressing_block = ''
    if rec_type.lower() in ('vinyl', 'lp', '45', '78', 'ep'):
        vinyl_pressing_block = (
            "\nIf this specific copy has a known vinyl pressing type, return "
            "it in a <vinyl_pressing>...</vinyl_pressing> tag. Use a compact "
            "value such as 140g, 180g, 200g, UHQR, MoFi One-Step, Half-Speed, "
            "Direct-to-Disc, Promo, or Test Pressing. Omit the tag unless "
            "source evidence clearly supports the pressing detail."
        )

    prompt = f"""You are a music critic + recording historian writing a
brief reference note for a single album / recording in a personal
collection. Use up to 4 web searches to ground facts.

Title:   {title or '(unknown)'}
Artist:  {artist or '(unknown)'}
Year:    {year or '(unknown)'}
Genre:   {genre or '(unspecified)'}
Label:   {label or '(unspecified)'}
Players: {players or '(unspecified)'}
Format:  {fmt or '(unspecified)'}
Existing notes: {existing_notes or '(none)'}

Record identity priority:
- Treat Title, Artist, Format, Label, and Existing notes as the current
  record's identity.
- Existing Players may be stale from a prior lookup. If Existing notes
  mention a conductor, ensemble, cast, label, edition, or performers
  that conflict with existing Players, use web sources to decide and
  correct Players.
- The <players> tag must identify performers for THIS record, not a
  different well-known recording mentioned in stale notes.
- The <tracks> tag, if returned, must also belong to THIS record, not a
  different recording suggested by stale Players or stale prior notes.
- Return one clean consolidated current note, not an addendum to the
  existing notes and not a near-duplicate rewrite of old bullets.

Cover whichever of these are notable for this specific recording:
- critical reception / canonical status
- recording history (studio, dates, key personnel beyond the headliner)
- standout tracks
- awards or chart performance
- the artist's career context at the time

Use the existing notes as clues for disambiguation, edition-specific
details, personnel, label, pressing, and prior context. Verify them
against web sources where possible. Do not simply repeat existing
notes unless they are important and source-supported; correct them if
sources clearly contradict them. If existing Players and existing notes
conflict, prioritize source-verified notes context over stale Players.

Style: 4–8 short bullets starting with "- ". Plain factual prose,
no headers, no fluff, no marketing copy. Under ~1400 chars total.
DO NOT include URLs anywhere in the bullet text — sources go in a
separate tag below.

Wrap the bullets in <markdown>…</markdown>. Then, immediately
after, list 2–4 source URLs (bare https://…, comma-separated) in
a <urls>…</urls> tag. No prose outside these tags, no code
fences, no JSON.{players_block}{tracks_block}{genre_block}{year_block}{label_block}{vinyl_pressing_block}"""

    client = anthropic.Anthropic(api_key=api_key)
    import time as _time
    last_err = None
    for attempt in range(3):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=2000,
                tools=[web_search],
                messages=[{'role': 'user', 'content': prompt}],
            )
            break
        except anthropic.RateLimitError as e:
            last_err = e
            wait = 10 * (attempt + 1)
            try:
                ra = e.response.headers.get('retry-after') if getattr(e, 'response', None) else None
                if ra: wait = max(wait, int(float(ra)))
            except Exception:
                pass
            _time.sleep(wait)
    else:
        raise RuntimeError(f'Rate limited after retries: {last_err}')

    text = _message_text(resp)
    text = text.strip()

    md = ''
    m = re.search(r'<markdown>(.*?)</markdown>', text, re.DOTALL | re.IGNORECASE)
    if m:
        md = m.group(1).strip()
    else:
        md = text  # last-ditch: use whatever the model returned
    if not md:
        raise RuntimeError(f'Empty response from model: {text[:200]}')

    import html as _html
    md = _html.unescape(md).strip()
    # Strip Claude web_search <cite index="...">...</cite> wrappers.
    md = re.sub(r'</?cite\b[^>]*>', '', md, flags=re.IGNORECASE)
    # Defensive: if Claude ignored the "no URLs in bullets" rule,
    # extract them out and feed into the urls list below. Strips
    # trailing punctuation that hugs URLs in prose.
    leaked_urls = re.findall(r'https?://[^\s<>"\']+', md)
    if leaked_urls:
        md = re.sub(r'https?://[^\s<>"\']+', '', md)
        md = re.sub(r'(?im)^[\s\-•*]*(sources?|references?|citations?)\s*:?\s*$\n?', '', md)
        md = re.sub(r'\n{3,}', '\n\n', md).strip()

    # <urls>...</urls> block — comma- or whitespace-separated sources.
    urls = []
    um = re.search(r'<urls>(.*?)</urls>', text, re.DOTALL | re.IGNORECASE)
    raw_urls = (um.group(1) if um else '') + '\n' + ' '.join(leaked_urls)
    raw_urls = _html.unescape(raw_urls)
    raw_urls = re.sub(r'</?cite\b[^>]*>', '', raw_urls, flags=re.IGNORECASE)
    seen = set()
    for u in re.findall(r'https?://[^\s<>"\',;]+', raw_urls):
        u = u.rstrip('),.;:!?\\]>"\'')
        if u and u not in seen:
            seen.add(u)
            urls.append(u)

    # Optional <players>...</players> block. Lookup is considered the
    # verification action, so a returned list can replace stale earlier
    # lookup output.
    new_players = ''
    pm = re.search(r'<players>(.*?)</players>', text, re.DOTALL | re.IGNORECASE)
    if pm:
        new_players = _html.unescape(pm.group(1)).strip()
        new_players = re.sub(r'</?cite\b[^>]*>', '', new_players, flags=re.IGNORECASE)
        # Collapse any internal newlines / extra whitespace in the
        # comma-separated list so it lands clean in the input.
        new_players = re.sub(r'\s+', ' ', new_players).strip(' ,')

    # Optional <tracks>...</tracks> block. One title per line; we
    # normalize to a newline-separated string so the UI can split on
    # \n to render Spotify-search pills.
    new_tracks = ''
    if want_tracks:
        tm = re.search(r'<tracks>(.*?)</tracks>', text, re.DOTALL | re.IGNORECASE)
        if tm:
            raw = _html.unescape(tm.group(1)).strip()
            raw = re.sub(r'</?cite\b[^>]*>', '', raw, flags=re.IGNORECASE)
            lines = []
            for line in raw.splitlines():
                t = line.strip()
                # Strip leading numbering ("1.", "1)", "1 -") and
                # surrounding quotes the model sometimes adds despite
                # the prompt asking it not to.
                t = re.sub(r'^[\s\-•*]*\d+[\.\)]\s*', '', t)
                t = t.strip(' "\'')
                if t:
                    lines.append(t)
            new_tracks = '\n'.join(lines)

    # Optional <genre>...</genre> + <genre_2>...</genre_2> blocks. Genre
    # prefers canonical capitalization from recording_genre when there
    # is a match, but otherwise accepts concise free text.
    new_genre = ''
    gm = re.search(r'<genre>(.*?)</genre>', text, re.DOTALL | re.IGNORECASE)
    if gm:
        cand = _html.unescape(gm.group(1)).strip()
        cand = re.sub(r'</?cite\b[^>]*>', '', cand, flags=re.IGNORECASE)
        cand = re.sub(r'\s+', ' ', cand).strip(' ,"\'')
        cand_l = cand.lower()
        for allowed in allowed_genres:
            if allowed.lower() == cand_l:
                new_genre = allowed
                break
        if not new_genre and cand and len(cand) <= 40 and not re.search(r'https?://|[<>]', cand):
            new_genre = cand
    new_genre_2 = ''
    g2m = re.search(r'<genre_2>(.*?)</genre_2>', text, re.DOTALL | re.IGNORECASE)
    if g2m:
        cand = _html.unescape(g2m.group(1)).strip()
        cand = re.sub(r'</?cite\b[^>]*>', '', cand, flags=re.IGNORECASE).strip()
        new_genre_2 = re.sub(r'\s+', ' ', cand).strip(' ,"\'')

    new_year_recorded = ''
    ym = re.search(r'<year_recorded>(.*?)</year_recorded>', text, re.DOTALL | re.IGNORECASE)
    if ym:
        cand = _html.unescape(ym.group(1)).strip()
        cand = re.sub(r'</?cite\b[^>]*>', '', cand, flags=re.IGNORECASE)
        m_year = re.search(r'\b(18|19|20)\d{2}\b', cand)
        if m_year:
            new_year_recorded = m_year.group(0)

    new_label = ''
    lm = re.search(r'<recording_label>(.*?)</recording_label>', text, re.DOTALL | re.IGNORECASE)
    if lm:
        cand = _html.unescape(lm.group(1)).strip()
        cand = re.sub(r'</?cite\b[^>]*>', '', cand, flags=re.IGNORECASE)
        new_label = _clean_recording_label(cand)

    new_vinyl_pressing = ''
    vpm = re.search(r'<vinyl_pressing>(.*?)</vinyl_pressing>', text, re.DOTALL | re.IGNORECASE)
    if vpm:
        cand = _html.unescape(vpm.group(1)).strip()
        cand = re.sub(r'</?cite\b[^>]*>', '', cand, flags=re.IGNORECASE)
        m_weight = re.search(r'\b(140|180|200)\s*(?:g|gram|grams)\b', cand, re.IGNORECASE)
        if m_weight:
            new_vinyl_pressing = f'{m_weight.group(1)}g'
        else:
            cand = re.sub(r'\s+', ' ', cand).strip(' ,"\'')
            if cand and len(cand) <= 40 and not re.search(r'https?://|[<>]', cand):
                new_vinyl_pressing = cand

    return {'markdown': md, 'players': new_players,
            'tracks': new_tracks, 'urls': urls,
            'genre': new_genre, 'genre_2': new_genre_2,
            'year_recorded': new_year_recorded,
            'label': new_label,
            'vinyl_pressing': new_vinyl_pressing}


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

LANDING_CATEGORY = (os.environ.get('STUFFAPP_LANDING_CATEGORY') or '').strip()


@app.route('/')
def index():
    allowed = g.get('allowed_cats') or set()
    if LANDING_CATEGORY in CATEGORIES and LANDING_CATEGORY in allowed:
        target = LANDING_CATEGORY
    else:
        target = next((c for c in CATEGORIES if c in allowed), 'watches')
    return redirect(url_for('list_view', category=target))


@app.route('/persons-default')
def persons_default():
    """Entry point used by the People nav tab — opens the most relevant
    person detail directly so the tab lands on a useful record instead
    of the full list. Back / search / direct list URLs still route
    through list_view normally.

    Resolution order:
      1. The current user's display_name (set in admin/users) — match
         it as a name fragment against persons.name. Lets young.sohn@…
         with display_name "Young Sohn" land on the Sohn record.
      2. Fall back to "Mark Armenante" — the historical default and
         what most users want when there's no display_name set.
    """
    db = get_db()
    row = None
    user = g.get('current_user') or {}
    display = (user.get('display_name') or '').strip()
    if display:
        # Build a fragment pattern: "Young Sohn" → "%Young%Sohn%".
        # Matches even if the persons.name has a middle name in
        # between (e.g. "Young A. Sohn").
        parts = [p for p in display.split() if p]
        if parts:
            pattern = '%' + '%'.join(parts) + '%'
            row = db.execute(
                "SELECT id FROM persons WHERE name LIKE ? "
                "ORDER BY length(name) DESC LIMIT 1",
                (pattern,)
            ).fetchone()
    if not row:
        row = db.execute(
            "SELECT id FROM persons "
            "WHERE name LIKE 'Mark%Armenante%' "
            "ORDER BY length(name) DESC LIMIT 1"
        ).fetchone()
    if row:
        return redirect(url_for('detail_view', category='persons', record_id=row['id']))
    return redirect(url_for('list_view', category='persons'))


@app.route('/<category>')
def list_view(category):
    if category not in CATEGORIES:
        abort(404)
    db = get_db()
    # Form field is named q_<category> so browser autocomplete history is
    # scoped per category; legacy ?q= links (toolbar pills, bookmarks)
    # still work.
    q   = (request.args.get(f'q_{category}')
           or request.args.get('q') or '').strip()
    dot = request.args.get('dot', '') == '1'
    raw_filter = request.args.get('filter')
    coin_filter = (raw_filter or '').strip() or None
    # Banknotes: the History pill switches the era/monetary-policy panels
    # on and off. On by default; ?history=0 hides them.
    show_history = request.args.get('history') != '0'
    # ?at=<property name> — drill in from a Property's pill row.
    at_property = (request.args.get('at') or '').strip() or None
    # Default filters apply on a fresh visit (no explicit ?filter= and no
    # search query). An active search bypasses the default so users don't
    # have to click Other / clear filter just to find a sold/loaned item.
    # An explicit empty ?filter= still clears all filters.
    if not q:
        if category == 'properties' and raw_filter is None:
            coin_filter = 'own'
        if category == 'vehicles' and raw_filter is None:
            coin_filter = 'own'
    sql, params = build_search_query(category, q, dot=dot,
                                     coin_filter=coin_filter,
                                     at_property=at_property)
    rows = db.execute(sql, params).fetchall()
    # When ?at=<name> is set, resolve the matching Property's id so
    # the list page can render a "← back to <Property>" pill that
    # jumps to its detail directly (browser back also works, this
    # is just a one-tap shortcut). Alias-aware: "Carp" or
    # "Carpinteria" both find the same property record.
    at_property_url = None
    if at_property:
        aliases = _property_alias_group(at_property)
        if aliases:
            ph = ','.join(['?' for _ in aliases])
            prop_row = db.execute(
                f"SELECT id FROM properties "
                f"WHERE LOWER(TRIM(name)) IN ({ph}) LIMIT 1",
                aliases
            ).fetchone()
            if prop_row:
                at_property_url = url_for('detail_view', category='properties',
                                          record_id=prop_row['id'])
    counts = get_counts()
    cat_info = CATEGORIES[category]
    extra_fields = LIST_EXTRA_FIELDS.get(category, [])
    # Split the compound properties filter into its two axes for the template.
    prop_status, prop_type = _split_property_filter(coin_filter) \
        if category == 'properties' else (None, None)
    # The Ordered pill only makes sense if there's at least one such
    # row (or the user is already viewing filter=ordered and wants a
    # way to toggle back off).
    has_ordered = False
    if category in ('coins', 'watches', 'banknotes'):
        table = CATEGORIES[category]['table']
        has_ordered = db.execute(
            f"SELECT EXISTS(SELECT 1 FROM {table} "
            f"WHERE LOWER(TRIM(COALESCE(status,''))) = 'ordered')"
        ).fetchone()[0] == 1
    # Same toggle-when-relevant rule for the No-longer-Owned pill so
    # an empty collection doesn't show a filter that produces nothing.
    has_no_longer_owned = False
    if category == 'watches':
        table = CATEGORIES[category]['table']
        has_no_longer_owned = db.execute(
            f"SELECT EXISTS(SELECT 1 FROM {table} "
            f"WHERE LOWER(TRIM(COALESCE(status,''))) IN ('sold','gifted','lost'))"
        ).fetchone()[0] == 1
    has_in_service = False
    if category == 'watches':
        has_in_service = db.execute(
            "SELECT EXISTS("
            "SELECT 1 FROM watch_service_events wse "
            "JOIN watches w ON w.id = wse.watch_id "
            "WHERE (wse.date_returned IS NULL OR TRIM(wse.date_returned) = '') "
            "AND LOWER(TRIM(COALESCE(w.status,''))) NOT IN ('sold','gifted','lost')"
            ")"
        ).fetchone()[0] == 1
    watch_open_service_event_ids = set()
    if category == 'watches' and rows:
        ids = [row['id'] for row in rows]
        placeholders = ','.join(['?'] * len(ids))
        watch_open_service_event_ids = {
            row['watch_id'] for row in db.execute(
                "SELECT DISTINCT watch_id FROM watch_service_events "
                f"WHERE watch_id IN ({placeholders}) "
                "AND (date_returned IS NULL OR TRIM(date_returned) = '')",
                ids,
            ).fetchall()
        }
    return render_template('list.html',
                           category=category,
                           cat_info=cat_info,
                           rows=rows,
                           counts=counts,
                           current_category=category,
                           categories=CATEGORIES,
                           q=q,
                           dot=dot,
                           coin_filter=coin_filter,
                           show_history=show_history,
                           at_property=at_property,
                           at_property_url=at_property_url,
                           prop_status=prop_status,
                           prop_type=prop_type,
                           today_iso=date.today().isoformat(),
                           result_count=len(rows),
                           has_ordered=has_ordered,
                           has_no_longer_owned=has_no_longer_owned,
                           has_in_service=has_in_service,
                           watch_open_service_event_ids=watch_open_service_event_ids,
                           extra_fields=extra_fields,
                           fields=visible_fields(category))


@app.route('/<category>/new', methods=['GET', 'POST'])
def new_record(category):
    if category not in CATEGORIES:
        abort(404)
    db = get_db()
    counts = get_counts()
    cat_info = CATEGORIES[category]
    table = cat_info['table']

    if request.method == 'POST':
        record_id = str(uuid.uuid4())
        now = datetime.utcnow().isoformat()
        data = {'id': record_id, 'created_at': now, 'updated_at': now}

        # Track originals so we can default empty *_title columns to the
        # uploaded file's basename after the row is parsed.
        file_originals = {}
        for field in visible_fields(category):
            fname = field['name']
            if field.get('readonly'):
                continue
            if field['type'] == 'file':
                f = request.files.get(fname)
                stored = save_upload(
                    f, optimize_image=_is_item_image_field(category, fname)
                )
                if stored:
                    data[fname] = stored
                    if f and f.filename:
                        file_originals[fname] = f.filename
                else:
                    data[fname] = None
            elif field['type'] == 'checkbox-group':
                checked = request.form.getlist(fname)
                data[fname] = ','.join(checked)
            else:
                val = request.form.get(fname, '').strip()
                if fname == 'price':
                    # Multi-currency: preserve "US$100,000.00" /
                    # "A$50,000.00" verbatim; fall back to legacy
                    # strip-and-parse for plain numbers.
                    val = _normalize_price_input(val)
                elif category in ('coins', 'banknotes') and fname in ('date_1', 'date_2'):
                    # Coin dates can arrive as the display value from the
                    # add form ("450 BC") before the JS submit normalizer
                    # runs. Preserve the era before generic unit stripping.
                    val = _normalize_coin_year_input(val)
                elif field['type'] == 'number' or fname in ('beat', 'reserve', 'value'):
                    val = val.replace('$', '').replace(',', '').strip()
                    # Strip trailing unit suffix ("8.50 g", "26.5 mm", "28800 hrs")
                    # in case the JS submit handler didn't run.
                    m = re.match(r'^\s*(-?\d+(?:\.\d+)?)\s*[A-Za-z%°/]*\s*$', val)
                    if m:
                        val = m.group(1)
                val = normalize_field_value(table, fname, val)
                data[fname] = val if val else None

        if category == 'watches':
            _apply_watch_order_form_fields(data, request.form)
            _graduate_watch_order_if_owned(data, data.get('status'))
            _apply_watch_actual_delivery_service_date(data)

        if category not in ('watches', 'coins', 'banknotes') and 'status' in {
            f['name'] for f in visible_fields(category)
        } and not (data.get('status') or '').strip():
            data['status'] = 'Own'

        # Auto-fill empty *_title / *_label columns with the uploaded
        # file's basename for each file field that has a paired title
        # column. Only fills when the user didn't supply a title via
        # the form — never overwrites.
        for file_field, original in file_originals.items():
            title_field = _title_field_for(category, file_field)
            if title_field and not (data.get(title_field) or '').strip():
                base = os.path.splitext(os.path.basename(original))[0].strip()
                if base:
                    data[title_field] = base

        # Owner default — applied whenever the form arrived without
        # an owner. The owner field is hidden for member users (the
        # form is gated by current_user.role == 'owner' in the
        # template), so this branch always fires for them.
        #
        # Coins always seed Mark regardless of who creates them — the
        # coin collection is his. Watches default to Mark only for
        # owner-role creators; members creating a watch get the
        # standard 'YM' default. All other categories: members get
        # 'YM', owners get DEFAULT_OWNER_BY_CATEGORY.
        if not (data.get('owner') or '').strip():
            if category in ('coins', 'banknotes'):
                data['owner'] = 'Mark'
            else:
                user = g.get('current_user') or {}
                if user.get('role') != 'owner':
                    data['owner'] = 'YM'
                else:
                    d = DEFAULT_OWNER_BY_CATEGORY.get(category)
                    if d:
                        data['owner'] = d

        # Required fields on create. Owner is needed for row-filter /
        # per-user access from the moment the record exists. Location is
        # collected by the client immediately after the first successful
        # autosave so the initial create/save can finish without blocking
        # the user's field flow.
        missing = []
        if not (data.get('owner') or '').strip():
            missing.append('Owner')
        if missing:
            err = 'Missing required field(s): ' + ', '.join(missing)
            # AJAX autosave-on-/new flow: client expects JSON.
            if request.headers.get('Accept', '').startswith('application/json') \
                    or request.headers.get('X-Requested-With') == 'fetch':
                return jsonify({'ok': False, 'error': err}), 400
            flash(err, 'error')
            # Re-render the same new-record form with the data the user
            # already entered (preserves their work) and focus the first
            # missing field. A redirect here would wipe everything.
            focus_map = {
                'Owner': 'owner',
                'Date': 'date_1' if category == 'coins' else 'date',
            }
            focus_field = focus_map.get(missing[0])
            return _render_new_form(category, data=data, focus_field=focus_field)
        if category == 'coins':
            data['coin_id'] = next_coin_id(db)
            data['cat_id'] = next_cat_id(db, data.get('property_name'), data.get('date_1'))
        elif category == 'banknotes':
            data['cat_id'] = next_serial_cat_id(db, 'banknotes', 'B')
        elif category == 'watches':
            data['cat_id'] = next_serial_cat_id(db, 'watches', 'W')
        elif category == 'art':
            data['cat_id'] = next_serial_cat_id(db, 'art', 'A')

        # Row-filter guard on creation. If the user is restricted on
        # any field for this category, the new record's value must
        # land within their allowed set — otherwise they'd create a
        # record they immediately can't see.
        cat_filt = _row_filter_for_category(g.get('current_user'), category)
        for fld, allowed in cat_filt.items():
            if not allowed:
                continue
            v = (data.get(fld) or '')
            if str(v).strip() not in allowed:
                err = (f'New record\'s {fld} must be one of: '
                       + ', '.join(allowed))
                if request.headers.get('Accept', '').startswith('application/json') \
                        or request.headers.get('X-Requested-With') == 'fetch':
                    return jsonify({'ok': False, 'error': err}), 403
                flash(err, 'error')
                return _render_new_form(category, data=data, focus_field=fld)

        if category == 'banknotes':
            canonicalize_banknote_fields(data)

        # Only write columns that physically exist — keeps the INSERT
        # resilient to dropped legacy columns that may still linger in
        # FIELDS for a category.
        real_cols = {
            r['name'] for r in db.execute(
                f"PRAGMA table_info({CATEGORIES[category]['table']})"
            ).fetchall()
        }
        data = {k: v for k, v in data.items() if k in real_cols}
        cols = ', '.join(data.keys())
        placeholders = ', '.join(['?' for _ in data])
        db.execute(f"INSERT INTO {CATEGORIES[category]['table']} ({cols}) VALUES ({placeholders})",
                   list(data.values()))
        if category == 'persons':
            created_person = db.execute(
                "SELECT * FROM persons WHERE id = ?", [record_id]
            ).fetchone()
            _replace_person_medications(
                db, record_id,
                _person_medications_from_person_row(created_person),
                sync_legacy=False, bump_person=False,
            )
        elif category == 'properties':
            created_property = db.execute(
                "SELECT * FROM properties WHERE id = ?", [record_id]
            ).fetchone()
            for spec in PROPERTY_SLOT_SPECS.values():
                _replace_property_slots(
                    db, spec, record_id,
                    _property_slots_from_property_row(spec, created_property),
                    sync_legacy=False, bump_property=False,
                )

        # Resequence Display Position for only the new coin's group
        # (Carp Ancient, Carp Modern, NY Ancient, or NY Modern).
        if category == 'coins':
            new_group = _coin_group_for(
                data.get('property_name'), data.get('date_1'))
            if new_group:
                _renumber_coin_groups(db, [new_group])
        elif category == 'banknotes':
            # The new note slots into the country/year order, pushing
            # every later note's Display Number up by one.
            _renumber_banknotes(db)
            data['banknote_id'] = db.execute(
                "SELECT banknote_id FROM banknotes WHERE id = ?",
                [record_id]).fetchone()['banknote_id']

        db.commit()

        # First note from a new country: generate its history panel in
        # the background.
        if category == 'banknotes' and data.get('country'):
            ensure_country_history(data['country'])
        detail_url = url_for('detail_view', category=category, record_id=record_id)
        save_url = url_for('save_field', category=category, record_id=record_id)
        # AJAX path (used by autosave-on-/new flow): return JSON so the
        # client can flip into save_field mode without a page reload.
        if request.headers.get('Accept', '').startswith('application/json') \
                or request.headers.get('X-Requested-With') == 'fetch':
            generated = {
                k: data.get(k) for k in ('coin_id', 'banknote_id', 'cat_id')
                if data.get(k) not in (None, '')
            }
            return jsonify({'ok': True, 'id': record_id,
                            'detail_url': detail_url, 'save_url': save_url,
                            'generated': generated})
        flash(f"Record created successfully.", 'success')
        return redirect(detail_url)

    # GET - blank form
    return _render_new_form(category)


def _render_new_form(category, data=None, focus_field=None):
    """Render the /<category>/new form. Used both for the bare GET and
    for re-rendering after a server-side validation failure on POST so
    the user's already-entered data isn't lost. Pass `data` (a dict
    keyed by field name) to repopulate inputs; pass `focus_field` to
    auto-focus a specific field on load (e.g. the missing required
    field that triggered the re-render)."""
    cat_info = CATEGORIES[category]
    return render_template('detail.html',
                           category=category,
                           cat_info=cat_info,
                           record=data,
                           counts=get_counts(),
                           current_category=category,
                           categories=CATEGORIES,
                           fields=visible_fields(category),
                           is_new=True,
                           prev_id=None,
                           next_id=None,
                           hertz=None,
                           coin_age_val=None,
                           property_topics=None,
                           camera_compatible_lenses=None,
                           lens_compatible_cameras=None,
                           property_pill_categories=None,
                           back_href=None,
                           service_overdue=None,
                           service_years=None,
                           watch_service_events=[],
                           watch_service_has_open_return=False,
                           record_documents_by_set={},
                           person_medications_by_position={},
                           today_iso=date.today().isoformat(),
                           complications_options=COMPLICATIONS_OPTIONS,
                           vlists=current_vlists(category),
                           focus_field=focus_field,
                           ta=build_typeahead(category))


@app.route('/<category>/<record_id>', methods=['GET', 'POST'])
def detail_view(category, record_id):
    if category not in CATEGORIES:
        abort(404)
    db = get_db()
    table = CATEGORIES[category]['table']
    cat_info = CATEGORIES[category]
    counts = get_counts()

    record = db.execute(f"SELECT * FROM {table} WHERE id = ?", [record_id]).fetchone()
    if record is None:
        abort(404)
    # Row-level access: a member with a filter on this category can
    # only see records whose filtered fields match. Pretend the row
    # doesn't exist (404) rather than 403 — fewer leaks about what's
    # there.
    if not _user_can_see_row(category, record):
        abort(404)

    # Prev/Next navigation. If the URL carries the same q / filter the
    # list view used (we forward both into the detail link), navigate
    # within that scoped, sorted set instead of the full table — so
    # < / > on a NY-Ancient-filtered coin walks the NY-Ancient list,
    # not the entire collection.
    nav_q = (request.args.get('q') or '').strip()
    nav_filter = (request.args.get('filter') or '').strip() or None
    nav_at = (request.args.get('at') or '').strip() or None
    nav_dot = request.args.get('dot', '') == '1'
    try:
        nav_sql, nav_params = build_search_query(
            category, nav_q, dot=nav_dot, coin_filter=nav_filter,
            at_property=nav_at)
    except Exception:
        nav_sql, nav_params = None, None
    if nav_sql:
        id_sql = re.sub(r'^SELECT \*', 'SELECT id', nav_sql, count=1)
        all_ids = [r['id'] for r in db.execute(id_sql, nav_params).fetchall()]
    else:
        nav_wheres, nav_params2 = [], []
        _apply_row_filter_clauses(category, nav_wheres, nav_params2)
        nav_where = f"WHERE {' AND '.join(nav_wheres)}" if nav_wheres else ''
        order_by = CATEGORY_ORDER_BY.get(category, 'created_at DESC')
        all_ids = [r['id'] for r in db.execute(
            f"SELECT id FROM {table} {nav_where} ORDER BY {order_by}",
            nav_params2).fetchall()]
    idx = all_ids.index(record_id) if record_id in all_ids else -1
    prev_id = all_ids[idx - 1] if idx > 0 else None
    next_id = all_ids[idx + 1] if idx < len(all_ids) - 1 else None

    if request.method == 'POST':
        now = datetime.utcnow().isoformat()
        updates = {'updated_at': now}

        for field in visible_fields(category):
            fname = field['name']
            if field.get('readonly'):
                continue
            if field['type'] == 'file':
                f = request.files.get(fname)
                if f and f.filename:
                    stored = save_upload(
                        f, optimize_image=_is_item_image_field(category, fname)
                    )
                    if stored:
                        updates[fname] = stored
                # else keep existing value (don't overwrite)
            elif field['type'] == 'checkbox-group':
                checked = request.form.getlist(fname)
                updates[fname] = ','.join(checked)
            else:
                val = request.form.get(fname, '').strip()
                # Strip currency formatting before saving numeric fields
                if fname == 'price':
                    val = _normalize_price_input(val)
                elif field['type'] == 'number' or fname in ('beat', 'reserve', 'value'):
                    val = val.replace('$', '').replace(',', '').strip()
                val = normalize_field_value(table, fname, val)
                updates[fname] = val if val else None

        if category == 'watches':
            _apply_watch_order_form_fields(updates, request.form)
            _graduate_watch_order_if_owned(updates, updates.get('status'))
            _apply_watch_actual_delivery_service_date(
                updates, record['actual_delivery_date'])

        if category == 'banknotes':
            canonicalize_banknote_fields(updates, existing=record)

        # A note that changed country/town/issuer/year moves in the
        # order, so every Display Number after it shifts.
        resequence_banknotes = (
            category == 'banknotes'
            and any(f in updates and updates[f] != record[f]
                    for f in BANKNOTE_SORT_FIELDS)
        )

        # If a coin moved groups, resequence both the old group (to
        # close the gap) and the new group (to place the coin).
        groups_to_resequence = []
        if category == 'coins':
            new_prop = updates.get('property_name', record['property_name'])
            new_date = updates.get('date_1', record['date_1'])
            old_group = _coin_group_for(record['property_name'], record['date_1'])
            new_group = _coin_group_for(new_prop, new_date)
            if old_group != new_group:
                if old_group: groups_to_resequence.append(old_group)
                if new_group: groups_to_resequence.append(new_group)

        # Skip any column that no longer exists (e.g. a dropped legacy
        # doc slot still present in FIELDS) so the UPDATE can't fail.
        real_cols = {
            r['name'] for r in db.execute(
                f"PRAGMA table_info({table})"
            ).fetchall()
        }
        updates = {k: v for k, v in updates.items() if k in real_cols}
        set_clause = ', '.join([f"{k} = ?" for k in updates.keys()])
        db.execute(f"UPDATE {table} SET {set_clause} WHERE id = ?",
                   list(updates.values()) + [record_id])
        if category == 'persons':
            updated_person = db.execute(
                "SELECT * FROM persons WHERE id = ?", [record_id]
            ).fetchone()
            _replace_person_medications(
                db, record_id,
                _person_medications_from_person_row(updated_person),
                now=now, sync_legacy=False, bump_person=False,
            )
        elif category == 'properties':
            updated_property = db.execute(
                "SELECT * FROM properties WHERE id = ?", [record_id]
            ).fetchone()
            for spec in PROPERTY_SLOT_SPECS.values():
                _replace_property_slots(
                    db, spec, record_id,
                    _property_slots_from_property_row(spec, updated_property),
                    now=now, sync_legacy=False, bump_property=False,
                )
        if groups_to_resequence:
            _renumber_coin_groups(db, groups_to_resequence)
        if resequence_banknotes:
            _renumber_banknotes(db)
        db.commit()
        flash("Record saved.", 'success')
        return redirect(url_for('detail_view', category=category, record_id=record_id))

    # GET
    hertz = None
    if category == 'watches' and record['beat']:
        hertz = watch_hertz(record['beat'])

    coin_age_val = None
    if category in ('coins', 'banknotes') and record['date_1'] is not None:
        coin_age_val = coin_age(record['date_1'])

    property_topics = None
    if category == 'properties':
        property_topics = db.execute(
            'SELECT id, subject, body, image FROM topics '
            'WHERE property_id = ? ORDER BY created_at',
            [record_id]
        ).fetchall()

    # Lens detail opened from a camera detail: Back should return to
    # the camera rather than the lenses list.
    back_href = None
    if category == 'lenses':
        from_camera = request.args.get('from_camera')
        if from_camera:
            cam = db.execute(
                "SELECT id FROM cameras WHERE id = ?", [from_camera]
            ).fetchone()
            if cam:
                back_href = url_for('detail_view',
                                    category='cameras',
                                    record_id=cam['id'])

    # Report pages pass their current path here so Detail's Back button
    # returns to the report instead of falling through to the category list.
    report_back = (request.args.get('report_back') or '').strip()
    if back_href is None and report_back.startswith('/') and not report_back.startswith('//'):
        back_href = report_back

    # Preserve the list's search/filter when returning via Back, so
    # "search Gela → click coin → Back" lands on the same filtered list
    # scrolled to the same record.
    if back_href is None:
        back_q = (request.args.get('q') or '').strip() or None
        back_filter = (request.args.get('filter') or '').strip() or None
        back_at = (request.args.get('at') or '').strip() or None
        back_dot = request.args.get('dot') or None
        if back_q or back_filter or back_at or back_dot:
            back_href = url_for('list_view', category=category,
                                q=back_q, filter=back_filter, at=back_at,
                                dot=back_dot) \
                        + f'#item-{record_id}'

    # Camera detail: list every lens with the same mount and property,
    # so the user can see the full kit available at that location.
    # Lenses whose make matches the mount brand (e.g. Leica make on a
    # Leica M mount) sort to the top; other brands fall underneath.
    camera_compatible_lenses = None
    if category == 'cameras' and record['lens_mount'] and record['property']:
        mount_brand = record['lens_mount'].split()[0] if record['lens_mount'] else ''
        camera_compatible_lenses = db.execute(
            "SELECT id, make, model, aperture, length, image FROM lenses "
            "WHERE LOWER(TRIM(COALESCE(mount,''))) = LOWER(TRIM(?)) "
            "  AND LOWER(TRIM(COALESCE(property,''))) = LOWER(TRIM(?)) "
            "ORDER BY CASE WHEN LOWER(COALESCE(make,'')) LIKE LOWER(?) || '%' "
            "              THEN 0 ELSE 1 END, "
            "         LOWER(COALESCE(make,'')), "
            "         CAST(COALESCE(length,0) AS REAL)",
            [record['lens_mount'], record['property'], mount_brand],
        ).fetchall()

    # Lens detail: list every camera with the same mount and property,
    # so the user can see which bodies the lens pairs with at that
    # location. Same sort logic as compatible_lenses — same-make
    # bodies (e.g. a Canon body for a Canon lens) sort to the top.
    lens_compatible_cameras = None
    if category == 'lenses' and record['mount'] and record['property']:
        mount_brand = record['mount'].split()[0] if record['mount'] else ''
        lens_compatible_cameras = db.execute(
            "SELECT id, make, model, digital_film, film_size, megapixels, image "
            "FROM cameras "
            "WHERE LOWER(TRIM(COALESCE(lens_mount,''))) = LOWER(TRIM(?)) "
            "  AND LOWER(TRIM(COALESCE(property,''))) = LOWER(TRIM(?)) "
            "ORDER BY CASE WHEN LOWER(COALESCE(make,'')) LIKE LOWER(?) || '%' "
            "              THEN 0 ELSE 1 END, "
            "         LOWER(COALESCE(make,'')), "
            "         LOWER(COALESCE(model,''))",
            [record['mount'], record['property'], mount_brand],
        ).fetchall()

    # Property detail: row of pills linking to "<Items> at this
    # property" lists. Each pill is a category the user is allowed
    # to see AND that has a property field per CATEGORY_PROPERTY_FIELD.
    # Coins is excluded — they're navigated by era and the Coins map
    # already covers location. Watches is included so users with
    # watch access can drill into watches at this property.
    PROPERTY_PILL_EXCLUDE = {'coins'}
    property_pill_categories = []
    if category == 'properties' and record and record['name']:
        allowed = g.get('allowed_cats') or set(CATEGORIES.keys())
        prop_name = record['name']
        # Owners see every accessible category as a pill (green when
        # populated, red when zero — useful at-a-glance "what's
        # missing from this property"). Members only see pills with
        # at least one item they can actually access; the row-filter
        # is applied to the count so categories with all-restricted
        # rows drop off entirely instead of showing a misleading red.
        viewer = g.get('current_user') or {}
        is_member_view = viewer.get('role') != 'owner'
        # Match the alias group so a pill for "Carpinteria" counts items
        # still tagged with the legacy short form "Carp" — same lookup
        # the /<cat>?at=<name> filter uses, so the pill count never
        # disagrees with the list it links to.
        aliases = _property_alias_group(prop_name) or [prop_name.strip().lower()]
        for slug in CATEGORY_PROPERTY_FIELD:
            if slug not in allowed or slug in PROPERTY_PILL_EXCLUDE:
                continue
            # Tenant scope — when a deployment restricts what the owner
            # sees, broader-access viewers (e.g. cross-tenant admins)
            # still get only the tenant's slice of pills.
            if TENANT_CATEGORIES is not None and slug not in TENANT_CATEGORIES:
                continue
            prop_field = CATEGORY_PROPERTY_FIELD[slug]
            table = CATEGORIES[slug]['table']
            ph = ','.join(['?'] * len(aliases))
            wheres = [f"LOWER(TRIM(COALESCE({prop_field}, ''))) IN ({ph})"]
            params = list(aliases)
            _apply_row_filter_clauses(slug, wheres, params)
            try:
                cnt = db.execute(
                    f"SELECT COUNT(*) AS c FROM {table} "
                    f"WHERE {' AND '.join(wheres)}",
                    params
                ).fetchone()['c']
            except sqlite3.OperationalError:
                cnt = 0
            if is_member_view and cnt == 0:
                continue
            property_pill_categories.append(
                (slug, CATEGORIES[slug]['name'], cnt))

    service_overdue = False
    service_years = None
    if category == 'watches' and record['service_date']:
        try:
            from datetime import date as _date
            num_comp = len([c for c in (record['complications'] or '').split(',') if c.strip()])
            threshold = 10 if num_comp > 5 else 15
            svc = datetime.strptime(record['service_date'], '%Y-%m-%d').date()
            years = (_date.today() - svc).days / 365.25
            service_years = int(years)  # floor
            service_overdue = years > threshold
        except Exception:
            pass
    watch_service_events = []
    watch_service_has_open_return = False
    if category == 'watches':
        watch_service_events = _watch_service_events(db, record_id)
        watch_service_has_open_return = any(
            not (ev.get('date_returned') or '').strip()
            for ev in watch_service_events
        )
    record_documents_by_set = {}
    if category in DOCUMENTS_CATEGORIES:
        for doc_set, col in DOC_SETS_BY_CATEGORY.get(category, {}).items():
            record_documents_by_set[doc_set] = (
                _docs_load(db, table, record_id, col) or []
            )
    person_medications_by_position = {}
    if category == 'persons':
        person_medications_by_position = _person_medications_by_position(
            db, record_id,
        )

    return render_template('detail.html',
                           category=category,
                           cat_info=cat_info,
                           record=record,
                           counts=counts,
                           current_category=category,
                           categories=CATEGORIES,
                           fields=visible_fields(category),
                           is_new=False,
                           prev_id=prev_id,
                           next_id=next_id,
                           hertz=hertz,
                           coin_age_val=coin_age_val,
                           property_topics=property_topics,
                           camera_compatible_lenses=camera_compatible_lenses,
                           property_pill_categories=property_pill_categories,
                           lens_compatible_cameras=lens_compatible_cameras,
                           back_href=back_href,
                           service_overdue=service_overdue,
                           service_years=service_years,
                           watch_service_events=watch_service_events,
                           watch_service_has_open_return=watch_service_has_open_return,
                           record_documents_by_set=record_documents_by_set,
                           person_medications_by_position=person_medications_by_position,
                           today_iso=None,
                           complications_options=COMPLICATIONS_OPTIONS,
                           vlists=current_vlists(category),
                           ta=build_typeahead(category))


@app.route('/watches/<record_id>/service-events', methods=['POST'])
def watch_service_event_create(record_id):
    db = get_db()
    _require_watch_for_service_event(db, record_id)
    payload = _watch_service_payload(request.get_json(silent=True) or {})
    if not payload['date_sent']:
        payload['date_sent'] = date.today().isoformat()
    event_id = str(uuid.uuid4())
    now = datetime.utcnow().isoformat()
    db.execute(
        "INSERT INTO watch_service_events "
        "(id, watch_id, date_sent, vendor, reason, cost, date_returned, created_at, updated_at) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
        [
            event_id,
            record_id,
            payload['date_sent'],
            payload['vendor'],
            payload['reason'],
            payload['cost'],
            payload['date_returned'],
            now,
            now,
        ],
    )
    service_date = _sync_watch_service_date_from_events(db, record_id)
    db.commit()
    row = db.execute(
        "SELECT * FROM watch_service_events WHERE id = ?",
        [event_id],
    ).fetchone()
    return jsonify({'ok': True, 'event': _service_event_dict(row),
                    'service_date': service_date})


