def _coin_row_value(coin, field):
    try:
        return coin[field]
    except (KeyError, IndexError, TypeError):
        if hasattr(coin, 'get'):
            return coin.get(field)
    return None


def _coin_first_measurement(text, unit_re, min_value, max_value):
    text = str(text or '')
    # Accept a comma decimal too — European dealers write "16,8 g" / "32,5 mm".
    pattern = rf'(?<![\w.,])(\d{{1,3}}(?:[.,]\d+)?)\s*(?:{unit_re})\b'
    for match in re.finditer(pattern, text, re.IGNORECASE):
        try:
            value = float(match.group(1).replace(',', '.'))
        except ValueError:
            continue
        if min_value <= value <= max_value:
            return value
    return None


def _coin_description_measurements(coin):
    description = _coin_row_value(coin, 'description') or ''
    return {
        'size': _coin_first_measurement(description, 'mm', 5, 80),
        'weight': _coin_first_measurement(description, 'g|gm|gram|grams', 0.01, 1000),
    }


# OpenNumismat / Krause-catalogue style descriptions store one labelled
# field per line ("COUNTRY  Eritrea", "RULER NAME  Umberto I", "YEAR 1891",
# "COMPOSITION  Silver", ...). Each label maps to a coin column. These come
# from the collector's own record, so they are canonical — they fill blanks
# and override a web/LLM guess, exactly like an explicit "16.85 g" does for
# weight. Labels are kept specific to avoid matching free-prose descriptions
# of ancient coins (which carry no leading label and fall through untouched).
_COIN_DESC_LABEL_FIELDS = {
    'country': 'region',
    'region': 'region',
    'ruler name': 'authority',
    'ruler': 'authority',
    'issuer': 'authority',
    'emperor': 'authority',
    'denomination': 'denomination',
    'mint name': 'mint',
    'composition': 'metal',
    'material': 'metal',
    'diameter': 'size',
    'weight (g)': 'weight',
    'weight': 'weight',
    'year': 'date_1',
    'km': 'coin_references',
    'km#': 'coin_references',
    'km number': 'coin_references',
    'krause': 'coin_references',
}

# composition word -> metal value-list code (see VALUE_LISTS['metal_coin']).
_COIN_METAL_WORDS = (
    ('aluminum', 'AL Aluminium'), ('aluminium', 'AL Aluminium'),
    ('billon', 'BL Billon'), ('electrum', 'EL Electrum'),
    ('silver', 'AR Silver'), ('gold', 'AV Gold'),
    ('bronze', 'AE Bronze'), ('copper', 'AE Copper'),
    ('nickel', 'NI Nickel'),
)


def _coin_metal_from_word(text):
    low = str(text or '').strip().lower()
    for word, code in _COIN_METAL_WORDS:
        if word in low:
            return code
    return None


def _coin_year_from_label(text):
    """Pull signed issue years out of a YEAR label value.

    '1891' -> (1891, None); '1890-1891' -> (1890, 1891); '450 BC' -> (-450,
    None). date_2 is returned only for an explicit range.
    """
    s = str(text or '')
    is_bc = bool(re.search(r'\bB\.?\s*C\.?E?\b', s, re.IGNORECASE))
    years = re.findall(r'\d{1,4}', s)
    if not years:
        return None, None
    nums = [(-int(y) if is_bc else int(y)) for y in years[:2]]
    return nums[0], (nums[1] if len(nums) > 1 else None)


# Match "<label><separator><value>" where the label is one we recognise.
# Longest labels first so "weight (g)" wins over "weight"; the separator is a
# colon, tab, or run of spaces (these blocks are column-aligned).
_COIN_DESC_LINE_RE = re.compile(
    r'^\s*(' + '|'.join(
        re.escape(lbl) for lbl in sorted(
            _COIN_DESC_LABEL_FIELDS, key=len, reverse=True)
    ) + r')\s*(?::|\t| +)\s*(.+?)\s*$',
    re.IGNORECASE,
)


def _coin_description_fields(coin):
    """Read identifying fields out of a structured catalogue-style description.

    Returns a dict of coin columns the block spells out, coerced to the form
    the lookup route expects (metal as a value-list code, date as an int,
    size/weight as numeric strings). Free-prose descriptions yield {}.
    """
    description = str(_coin_row_value(coin, 'description') or '')
    if not description.strip():
        return {}

    pairs = {}
    for line in description.splitlines():
        m = _COIN_DESC_LINE_RE.match(line)
        if not m:
            continue
        field = _COIN_DESC_LABEL_FIELDS[re.sub(r'\s+', ' ', m.group(1).strip().lower())]
        value = m.group(2).strip()
        if value and field not in pairs:
            pairs[field] = value

    out = {}
    for field, value in pairs.items():
        if field == 'metal':
            code = _coin_metal_from_word(value)
            if code:
                out['metal'] = code
        elif field == 'date_1':
            d1, d2 = _coin_year_from_label(value)
            if d1 is not None:
                out['date_1'] = d1
            if d2 is not None:
                out['date_2'] = d2
        elif field in ('size', 'weight'):
            num = re.search(r'-?\d+(?:\.\d+)?', value)
            if num:
                out[field] = num.group(0)
        elif field == 'coin_references':
            out['coin_references'] = value if value.lower().startswith('km') else f'KM# {value}'
        else:
            out[field] = value
    return out


# Italian (and Italian-colonial: Eritrea, Somalia, Libya) mint-mark letters.
# A lone control letter next to the date or called out on the reverse ("R
# below") is the mint city. Only applied when the coin's own text is clearly
# Italian, so a stray "R" in some other legend is never misread as Rome.
_ITALIAN_MINT_MARKS = {
    'R': 'Rome', 'M': 'Milan', 'B': 'Bologna', 'N': 'Naples',
    'V': 'Venice', 'T': 'Turin', 'F': 'Florence',
}
_ITALIAN_CONTEXT_RE = re.compile(
    r'\b(ITALIA|ITALICUM|ITALIAN|LIRE|LIRA|TALLERO|ERYTHR|ERITREA|SOMAL|'
    r'LIBIA|VITTORIO\s+EMANUELE|UMBERTO|REGNO|REGNUM)\b', re.IGNORECASE)


def _coin_year_from_prose(text):
    """First plausible coin date in free text: an 'N BC' token (ancient prose)
    or a Gregorian year 1500-2099. Skips catalogue refs like 'KM 1916'."""
    s = str(text or '')
    # "480-440 BC" → take the earlier year (-480) as date_1.
    bc_range = re.search(r'\b(\d{1,4})\s*[-–]\s*\d{1,4}\s*B\.?\s*C\.?E?\b', s, re.IGNORECASE)
    if bc_range:
        return -int(bc_range.group(1))
    bc = re.search(r'\b(\d{1,4})\s*B\.?\s*C\.?E?\b', s, re.IGNORECASE)
    if bc:
        return -int(bc.group(1))
    for m in re.finditer(r'(?<![\w#./-])(1[5-9]\d{2}|20\d{2})(?![\w./-])', s):
        before = s[max(0, m.start() - 6):m.start()].lower()
        if any(tok in before for tok in ('km', '#', 'no.', 'p.', 'pg', 'lot')):
            continue
        return int(m.group(1))
    return None


def _coin_mintmark_city(text):
    """Expand a lone Italian control-letter mint-mark to its city, but only
    when the text is unmistakably Italian / Italian-colonial."""
    s = str(text or '')
    if not _ITALIAN_CONTEXT_RE.search(s):
        return None
    patterns = (
        r'\b1[5-9]\d{2}\s+([A-Z])\b',          # "1918 R"
        r'\b20\d{2}\s+([A-Z])\b',
        r'mint[\s-]*mark[:\s]+([A-Z])\b',
        r'\b([A-Z])\s+below\b',                # "R below"
        r'\b([A-Z])\s+on\s+(?:the\s+)?reverse\b',
    )
    for pat in patterns:
        m = re.search(pat, s)
        if m:
            city = _ITALIAN_MINT_MARKS.get(m.group(1).upper())
            if city:
                return city
    return None


def _coin_text_inferences(coin):
    """Deterministic reads from the coin's own free-prose text (obv/rev one-
    liner + description) for fields a labelled block doesn't spell out —
    chiefly the issue year and an Italian mint-mark. Used only to fill blanks,
    never to override a labelled value or a confident lookup."""
    text = '\n'.join(
        p for p in (
            str(_coin_row_value(coin, 'obv_rev') or ''),
            str(_coin_row_value(coin, 'description') or ''),
        ) if p.strip()
    )
    out = {}
    year = _coin_year_from_prose(text)
    if year is not None:
        out['date_1'] = year
    city = _coin_mintmark_city(text)
    if city:
        out['mint'] = city
    return out


def fetch_coin_specs(coin, provider='anthropic'):
    """Fill missing identifying fields on a coin through the selected provider.

    Returns a dict like ``{field: value, ...}`` containing ONLY fields the
    model is confident about. Existing non-empty fields are sent as
    context but never overwritten by the caller.
    """
    provider = (provider or 'anthropic').strip().lower()
    if provider not in {'anthropic', 'perplexity'}:
        raise RuntimeError(f'Unsupported coin spec lookup provider: {provider}')

    known = {}
    for f in COIN_SPEC_FILLABLE:
        v = coin[f]
        if v not in (None, ''):
            known[f] = v
    if not known:
        raise RuntimeError(
            'Need at least one of region / authority / denomination / metal '
            '/ date to look up the rest.')

    metals = ', '.join(VALUE_LISTS['metal_coin'])
    grades = ', '.join(VALUE_LISTS['coin_grade'])
    obv_rev = (coin['obv_rev'] or '').strip()
    description = (coin['description'] or '').strip()
    mint = (coin['mint'] or '').strip()
    pedigree = (coin['coin_references'] or '').strip()
    grade_notes = (coin['notes'] or '').strip()
    condition = (coin['condition'] or '').strip()

    known_lines = '\n'.join(f'- {k}: {v}' for k, v in known.items()) or '(none entered)'
    dealer_blocks = []
    if description: dealer_blocks.append(f'DESCRIPTION:\n{description[:4000]}')
    if pedigree:    dealer_blocks.append(f'REFERENCES / PEDIGREE:\n{pedigree[:2000]}')
    if grade_notes: dealer_blocks.append(f'GRADE / CONDITIONS NOTES:\n{grade_notes[:2000]}')
    if condition:   dealer_blocks.append(f'HISTORICAL / OTHER NOTES:\n{condition[:1500]}')
    if obv_rev:     dealer_blocks.append(f'OBVERSE / REVERSE: {obv_rev}')
    if mint:        dealer_blocks.append(f'MINT (as entered): {mint}')
    dealer_text = '\n\n'.join(dealer_blocks) if dealer_blocks else '(no dealer text on file)'

    prompt = f"""You are extracting structured catalogue fields for one specific coin.

PRIMARY SOURCE — the selling numismatist's own text for THIS coin. It is authoritative: extract every field you can DIRECTLY from it.
{dealer_text}

Structured fields the user has already transcribed from the dealer:
{known_lines}

Rules:
1. The dealer's text above is the source of truth. For each target field, FIRST take the value the dealer's text states (description, references/pedigree, condition note).
2. Only when the dealer's text does NOT mention a field may you use up to 3 web searches (CoinArchives, ACSearch, Wildwinds, NGC, British Museum, ANS, vCoins, CNG, Roma) to fill it. NEVER override a value the dealer's text states with a web/period guess.
3. The grading-slab fields (grading_authority, slab_number, strike, surface, sheldon), the dates, and the grade must come ONLY from the dealer's text — do not web-search or estimate them. Return null if the text does not state them.
4. The user wants fills (blank fields) and corrections of transcription errors toward the dealer's text. Return null whenever a value is not supported by the text (or, for web-allowed fields, by a reputable source).
5. If the dealer's text or description quotes the coin's actual inscription / legend (Latin, Greek, Cyrillic, Arabic, etc.), transliterate and translate it — the ruler, titles, mint, denomination and frequently the year are spelled out on the coin (e.g. "VMBERTO I RE D'ITALIA · 1891" → authority "Umberto I", date_1 1891; "ΒΑΣΙΛΕΩΣ ΛΥΣΙΜΑΧΟΥ" → authority "Lysimachos"). Numerals in the legend or exergue (Western, Roman, regnal, or era dates) are direct evidence for date_1. A translated legend counts as the dealer's text, not a web guess.

Target fields:
- region: short geographic / cultural region (e.g. "Thessaly", "Roman Republic", "United States").
- mint: issuing mint / city. Use the city as stated (e.g. "Skotussa", "Byzantion"), but ALSO expand a control-letter mint-mark to its city using standard catalogue conventions — for Italian / Italian-colonial coins R = Rome, M = Milan, B = Bologna, N = Naples, V = Venice, T = Turin, F = Florence. A lone letter right after the date or called out on the reverse is the mint-mark (e.g. "1918 R" or "R below" → Rome).
- authority: ruler, polity, or issuing authority (e.g. "Augustus", "United States Mint").
- official: named individual + role as "Name, role" — e.g. "Straton, magistrate", "John Reich, engraver". Look in the description FIRST, including abbreviated/initialed magistrate signatures (e.g. "ΔA, magistrate", "CT, magistrate") — capture verbatim; a partial/two-letter signature IS the die signature. Preserve "unsigned / attributed / style of" nuance; do not promote a stylistic attribution to a confirmed signature. Null if none.
- denomination: the denomination (e.g. "Drachm", "Tetradrachm", "Dollar"). NOT a metal — "AE", "AR", "AV", "Æ", "bronze", "silver", "gold" are metals, never denominations.
- metal: EXACTLY one of [{metals}]. Use the two-letter prefix codes shown.
- date_1: integer year, NEGATIVE for BC (e.g. -440 for 440 BC), positive for AD/CE. Use the year the DEALER'S TEXT gives — including a year stated inline in the description or legend (e.g. "5 Lire 1918 R" → 1918); do not substitute a different period or round it.
- date_2: integer year ending a range, same sign convention; null if not a range.
- weight: grams (float). If the text has an explicit "X.XX g / gm / grams", return exactly that.
- size: diameter mm (float). If the text has "XX mm" / "XX.X mm", return exactly that; do NOT round ("14.5 mm" → 14.5).
- die_axis: integer 0-12 from the clock-position token in "(mm, g, NNh)" — e.g. "12h" → 12, "6 h" → 6. Null if absent.
- grade: map the dealer's stated condition grade to EXACTLY one of [{grades}] (c = choice, a = about, g = good; Mint State / Unc / MS-65 → MS; XF / Extremely Fine → EF; Good VF → gVF; Choice VF → cVF; About VF → aVF; PR / Proof → PF). Null if outside the list.
- strike: the NGC/PCGS strike sub-grade as a number if the text states it (e.g. "5/5" → 5); else null.
- surface: the NGC/PCGS surface sub-grade as a number if the text states it (e.g. "4/5" → 4); else null.
- sheldon: the Sheldon numeric grade as written, usually with a prefix (e.g. "MS-65", "PR-70", "AU-58"), if the text states it; else null.
- grading_authority: the grading company if the coin is or was ever slabbed/graded and the text names it — e.g. "NGC", "PCGS", "ANACS", "ICG", "PMG", "NGC Ancients". It normally sits right before "slab", "ticket", "cert", "graded", or "holder". The coin is often removed from the holder, so a FORMER grading still counts: "formerly in NGC slab", "ex NGC", "was PCGS graded", "NGC ticket", "out of an NGC slab", "previously NGC Ch AU" all → capture the company. Normalize an obvious typo (e.g. "NCG" -> "NGC"). Else null.
- slab_number: the grading certification / slab / ticket number if the text states one — capture it verbatim. It usually follows a cue word and is a digit code, often with a hyphen, e.g. "NGC ticket 9829888-003", "NGC cert 9829888-003", "NCG: 9829888-003", "cert #1234567", "PCGS 12345678", "slab 9829888-003" → return "9829888-003" / "1234567" / "12345678". The coin may have been removed from the slab, so it can appear in the description, pedigree, or grade notes. Else null.
- grade_condition: surface-condition qualifier(s) the dealer or grading service notes alongside the grade — e.g. "brushed", "cleaned", "tooled", "smoothed", "scratched", "porosity", "pitting", "graffiti", "holed", "mounted", "test cut", "edge filing", "deposits", "scratches". Return the qualifier(s) the text states (comma-separated if several, lowercase); else null. Do NOT include the grade itself or the ★/+ designation here.
- grade_modifier: the NGC/PCGS grade-designation symbol(s) attached to the grade, if any. Return "★" when the text shows a star or the word "Star" (e.g. "XF★", "MS 65 Star", "AU★"), "+" when the grade carries a plus (e.g. "MS65+", "AU58+", "EF+"), or "★+" if both. The designation attaches to the grade itself (XF★) and is distinct from the 5/5 strike & surface sub-grades. Else null.

Reply with ONLY a JSON object, no prose, no code fences. Use null when a value is not supported:
{{
  "region": null, "mint": null, "authority": null, "official": null,
  "denomination": null, "metal": null, "date_1": null, "date_2": null,
  "weight": null, "size": null, "die_axis": null, "grade": null,
  "strike": null, "surface": null, "sheldon": null,
  "grading_authority": null, "slab_number": null, "grade_condition": null, "grade_modifier": null,
  "sources": "one-line note of where each value came from (dealer text vs which web source)"
}}
"""

    if provider == 'perplexity':
        api_key = os.environ.get('PERPLEXITY_API_KEY')
        if not api_key:
            raise RuntimeError('PERPLEXITY_API_KEY not configured')
        api_data, text = perplexity_chat_completion(
            api_key,
            prompt,
            env_names='PERPLEXITY_COIN_SPEC_LOOKUP_MODEL',
            default_model='sonar-pro',
            max_tokens=2048,
            response_schema=COIN_SPECS_RESPONSE_SCHEMA,
            schema_name='coinSpecs',
            search_context_env_names='PERPLEXITY_COIN_SPEC_LOOKUP_CONTEXT',
            default_search_context='high',
        )
        parsed = parse_model_json_object(text)
        citations = api_data.get('citations') or []
        if citations and isinstance(parsed, dict):
            existing = (parsed.get('sources') or '').strip()
            cite_list = '; '.join(citations[:6])
            parsed['sources'] = (f'{existing} | citations: {cite_list}'
                                 if existing else f'citations: {cite_list}')
        return parsed

    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed.")

    client = anthropic.Anthropic(api_key=api_key, timeout=240.0)
    lookup_model = anthropic_lookup_model(api_key, 'ANTHROPIC_COIN_LOOKUP_MODEL')
    web_search = anthropic_web_search_tool(4)
    import time as _time
    last_err = None
    transient_errs = _anthropic_transient_errs(anthropic)
    resp = None
    for attempt in range(3):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=1024,
                tools=[web_search],
                messages=[{'role': 'user', 'content': prompt}],
            )
            break
        except transient_errs as e:
            last_err = e
            wait = 10 * (attempt + 1)
            try:
                ra = e.response.headers.get('retry-after') if getattr(e, 'response', None) else None
                if ra:
                    wait = max(wait, int(float(ra)))
            except Exception:
                pass
            if attempt == 2:
                raise RuntimeError(_friendly_lookup_error('Coin spec lookup', last_err))
            _time.sleep(wait)
    if resp is None:
        raise RuntimeError('Coin spec lookup returned no response')

    text = _message_text(resp)
    text = text.strip()
    # Strip code fences if the model added them anyway
    text = re.sub(r'^```(?:json)?\s*', '', text)
    text = re.sub(r'\s*```$', '', text)
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        m = re.search(r'\{[\s\S]*\}', text)
        if m:
            return json.loads(m.group(0))
        raise RuntimeError('Could not parse Claude response as JSON')


@app.route('/coins/<record_id>/lookup-specs', methods=['POST'])
def coin_lookup_specs(record_id):
    """Fill blank region/authority/denomination/metal/date fields from web."""
    db = get_db()
    coin = db.execute("SELECT * FROM coins WHERE id = ?", (record_id,)).fetchone()
    if not coin:
        return jsonify({'error': 'Coin not found'}), 404
    provider = (
        'perplexity'
        if request.args.get('provider') == 'perplexity'
        else 'anthropic'
    )
    # The coin's own description — a structured catalogue block and/or
    # explicit measurements — is canonical and needs no network. Read it
    # first so a missing API key or a flaky web lookup can never stop the
    # Check from filling fields the record already spells out.
    suggestions = {}
    lookup_error = None
    lookup_status = 503
    try:
        suggestions = fetch_coin_specs(coin, provider=provider)
    except RuntimeError as e:
        lookup_error = str(e)
    except Exception as e:
        import traceback
        print(traceback.format_exc(), flush=True)
        lookup_error = f'Lookup failed: {e or e.__class__.__name__}'
        lookup_status = 500

    if not isinstance(suggestions, dict):
        suggestions = {}
    for field, value in _coin_description_measurements(coin).items():
        if value is not None:
            suggestions[field] = value
    for field, value in _coin_description_fields(coin).items():
        if value not in (None, ''):
            suggestions[field] = value
    # Free-prose reads (year, Italian mint-mark) only fill what nothing else
    # supplied — never override a labelled value or a confident lookup.
    for field, value in _coin_text_inferences(coin).items():
        if value not in (None, '') and suggestions.get(field) in (None, ''):
            suggestions[field] = value

    # Only surface a lookup failure if the description gave us nothing to
    # offer either — otherwise apply the canonical fields silently.
    if lookup_error and not any(
        suggestions.get(f) not in (None, '') for f in COIN_SPEC_FILLABLE
    ):
        return jsonify({'error': lookup_error}), lookup_status

    metal_allowed = {m.lower(): m for m in VALUE_LISTS['metal_coin']}

    def _coerce(field, raw):
        if raw is None:
            return None
        if field == 'metal':
            if not isinstance(raw, str):
                return None
            return metal_allowed.get(raw.strip().lower())
        if field in ('date_1', 'date_2'):
            try:
                return int(raw)
            except (TypeError, ValueError):
                return None
        if field in ('weight', 'size'):
            # Accept "16.85", "16.85 g", "30 mm", and a comma decimal
            # ("16,8 g" / "32,5 mm") from European dealers — strip the unit.
            if isinstance(raw, str):
                m = re.match(r'^\s*(-?\d+(?:[.,]\d+)?)', raw)
                if not m:
                    return None
                try:
                    return float(m.group(1).replace(',', '.'))
                except ValueError:
                    return None
            try:
                return float(raw)
            except (TypeError, ValueError):
                return None
        if field == 'die_axis':
            # Accept "12", "12h", "12 h", "12hr". Clamp to 0-12; the
            # column stores it as text to match the existing select.
            if isinstance(raw, str):
                m = re.match(r'^\s*(\d+)', raw)
                if not m:
                    return None
                n = int(m.group(1))
            else:
                try:
                    n = int(raw)
                except (TypeError, ValueError):
                    return None
            if n < 0 or n > 12:
                return None
            return str(n)
        if field == 'grade':
            return coin_grade_value_list_match(raw)
        if field == 'denomination':
            if not isinstance(raw, str):
                return None
            cleaned = raw.strip()
            # Metal codes/names are not denominations — Æ/AE = bronze, AR = silver, AV = gold,
            # EL = electrum, BI = billon. The lookup sometimes returns the metal here; reject it so it
            # never overwrites a real denomination (e.g. "Drachm" -> "AE").
            if re.fullmatch(r'(?:ae|æ|ar|av|el|bi|billon|bronze|copper|silver|gold|electrum|orichalcum)\.?',
                            cleaned, re.IGNORECASE):
                return None
            v = normalize_field_value('coins', field, cleaned)
            return v or None
        if field in ('strike', 'surface'):
            if isinstance(raw, str):
                m = re.match(r'^\s*(-?\d+(?:\.\d+)?)', raw)
                if not m:
                    return None
                try:
                    return float(m.group(1))
                except ValueError:
                    return None
            try:
                return float(raw)
            except (TypeError, ValueError):
                return None
        if field == 'grading_authority':
            return normalize_grading_authority(raw)
        if field == 'grade_modifier':
            return normalize_grade_modifier(raw)
        if field in ('sheldon', 'slab_number', 'mint', 'grade_condition'):
            # Preserve as written (cert numbers, grade strings like MS-65, mint / firm names).
            v = (raw if isinstance(raw, str) else str(raw)).strip()
            return v or None
        if isinstance(raw, str):
            v = normalize_field_value('coins', field, raw.strip())
            return v or None
        return raw

    def _equivalent(field, current, suggested):
        if field in ('date_1', 'date_2'):
            try:
                return int(current) == int(suggested)
            except (TypeError, ValueError):
                return False
        if field in ('weight', 'size', 'strike', 'surface'):
            # Tolerance: don't propose a "change" for a sub-0.05
            # difference (rounding noise / source-to-source jitter, or 5 vs 5.0).
            try:
                return abs(float(current) - float(suggested)) < 0.05
            except (TypeError, ValueError):
                return False
        if field == 'die_axis':
            try:
                return int(current) == int(suggested)
            except (TypeError, ValueError):
                return str(current or '').strip() == str(suggested or '').strip()
        return str(current or '').strip().lower() == str(suggested or '').strip().lower()

    # Fields transcribed from the selling numismatist are authoritative. The external lookup may only
    # change them when the dealer's own description/pedigree/condition text backs the value — this blocks
    # the lookup from replacing the dealer's attribution with its own period guess (e.g. -356 -> -440),
    # while still catching a transcription error (entered 345, description says 354 -> suggest 354) and
    # filling a value the description states but the field omits.
    NUMISMATIST_FIELDS = {'date_1', 'date_2', 'grade', 'slab_number', 'sheldon', 'grade_condition', 'grade_modifier'}
    dealer_text = ' '.join(
        str(_coin_row_value(coin, c) or '')
        for c in ('description', 'coin_references', 'condition', 'notes')
    )
    _dealer_text_key = re.sub(r'[^a-z0-9]', '', dealer_text.lower())
    _dealer_years = set()
    for _m in re.finditer(r'(\d{1,4})\s*(?:-\s*\d{1,4}\s*)?(?:BCE|BC|B\.C\.|CE|AD|A\.D\.)\b', dealer_text, re.IGNORECASE):
        for _y in re.findall(r'\d{1,4}', _m.group(0)):
            _dealer_years.add(int(_y))
    # Modern issue years are usually stated plainly with no era marker ("YEAR 1891",
    # "5 Lire 1918 R"), so the BC/AD pass above never sees them — leaving a description-
    # sourced date ungrounded and wrongly dropped. Add bare Gregorian years (1500-2099)
    # too, skipping catalogue refs (KM 1916, #, lot) the same way _coin_year_from_prose does.
    for _m in re.finditer(r'(?<![\w#./-])(1[5-9]\d{2}|20\d{2})(?![\w./-])', dealer_text):
        _before = dealer_text[max(0, _m.start() - 6):_m.start()].lower()
        if any(_tok in _before for _tok in ('km', '#', 'no.', 'p.', 'pg', 'lot')):
            continue
        _dealer_years.add(int(_m.group(1)))

    def _grounded_in_description(field, value):
        if field in ('date_1', 'date_2'):
            try:
                return abs(int(value)) in _dealer_years
            except (TypeError, ValueError):
                return False
        if field == 'grade':
            token = str(value).strip()
            return bool(token) and re.search(r'\b' + re.escape(token) + r'\b', dealer_text, re.IGNORECASE) is not None
        if field in ('slab_number', 'sheldon'):
            key = re.sub(r'[^a-z0-9]', '', str(value).lower())
            return len(key) >= 2 and key in _dealer_text_key
        if field == 'grade_condition':
            # Each qualifier word must actually appear in the dealer's text (no invented conditions).
            words = re.findall(r'[a-z]{3,}', str(value).lower())
            return bool(words) and all(w in _dealer_text_key for w in words)
        if field == 'grade_modifier':
            # The ★ must be backed by a star in the dealer's text; the + by a plus. No invented bumps.
            ok = True
            if '★' in str(value) and not ('★' in dealer_text or 'star' in dealer_text.lower()):
                ok = False
            if '+' in str(value) and '+' not in dealer_text:
                ok = False
            return ok
        return True

    # Build proposals (no longer auto-apply fills — every change now
    # flows through the review modal client-side, matching the watch
    # lookup behaviour).
    filled = {}
    overwritten = {}
    for f in COIN_SPEC_FILLABLE:
        v = _coerce(f, suggestions.get(f))
        if v in (None, ''):
            continue
        # Numismatist-authoritative fields only change when the dealer's own text backs the value;
        # otherwise the lookup's external guess is ignored for these fields.
        if f in NUMISMATIST_FIELDS and not _grounded_in_description(f, v):
            continue
        cur = coin[f]
        if cur in (None, ''):
            filled[f] = v
        elif not _equivalent(f, cur, v):
            overwritten[f] = {'current': cur, 'new': v}

    # Stamp that the identifying-field lookup ran successfully.
    # Only stamp a fully successful run: a partial (description-only)
    # result keeps the Check button un-done so a retry isn't skipped.
    now = None
    if not lookup_error:
        now = datetime.utcnow().isoformat()
        db.execute("UPDATE coins SET specs_searched_at = ? WHERE id = ?",
                   (now, record_id))
        db.commit()

    return jsonify({
        'filled': filled,
        'overwritten': overwritten,
        'sources': suggestions.get('sources', ''),
        'specs_searched_at': now,
        'lookup_error': lookup_error,
    })


@app.route('/coins/<record_id>/apply-lookup-specs', methods=['POST'])
def coin_apply_lookup_specs(record_id):
    """Apply a user-selected subset of coin spec lookup suggestions.

    Body: ``{"updates": {"<field>": <value>, ...}}``
    Only fields in COIN_SPEC_FILLABLE are accepted. Handles the
    cat_id assignment + group resequencing if date_1 changes — the
    same housekeeping the old lookup endpoint did inline.
    """
    db = get_db()
    coin = db.execute("SELECT * FROM coins WHERE id = ?",
                      (record_id,)).fetchone()
    if not coin:
        return jsonify({'error': 'Coin not found'}), 404
    data = request.get_json(force=True) or {}
    raw = data.get('updates') or {}
    if not isinstance(raw, dict):
        return jsonify({'error': 'updates must be an object'}), 400

    metal_allowed = {m.lower(): m for m in VALUE_LISTS['metal_coin']}

    def _coerce(field, raw_v):
        if raw_v is None:
            return None
        if field == 'metal':
            if not isinstance(raw_v, str):
                return None
            return metal_allowed.get(raw_v.strip().lower())
        if field in ('date_1', 'date_2'):
            try:
                return int(raw_v)
            except (TypeError, ValueError):
                return None
        if field in ('weight', 'size'):
            if isinstance(raw_v, str):
                # Accept a comma decimal ("16,8" / "32,5") from European dealers.
                m = re.match(r'^\s*(-?\d+(?:[.,]\d+)?)', raw_v)
                if not m:
                    return None
                try:
                    return float(m.group(1).replace(',', '.'))
                except ValueError:
                    return None
            try:
                return float(raw_v)
            except (TypeError, ValueError):
                return None
        if field == 'grade':
            return coin_grade_value_list_match(raw_v)
        if field in ('strike', 'surface'):
            if isinstance(raw_v, str):
                m = re.match(r'^\s*(-?\d+(?:\.\d+)?)', raw_v)
                if not m:
                    return None
                try:
                    return float(m.group(1))
                except ValueError:
                    return None
            try:
                return float(raw_v)
            except (TypeError, ValueError):
                return None
        if field == 'grading_authority':
            return normalize_grading_authority(raw_v)
        if field == 'grade_modifier':
            return normalize_grade_modifier(raw_v)
        if field in ('sheldon', 'slab_number', 'mint', 'grade_condition'):
            v = (raw_v if isinstance(raw_v, str) else str(raw_v)).strip()
            return v or None
        if isinstance(raw_v, str):
            return normalize_field_value('coins', field, raw_v.strip()) or None
        return raw_v

    updates = {}
    for k, v in raw.items():
        if k not in COIN_SPEC_FILLABLE:
            continue
        coerced = _coerce(k, v)
        if coerced in (None, ''):
            continue
        updates[k] = coerced
    if not updates:
        return jsonify({'updated': 0, 'fields': []})

    # The detail template prefers date_1_text / date_2_text for
    # display when present. If we update the integer date columns
    # without also rewriting the text columns, the old text value
    # shadows the new integer and the field appears unchanged on
    # reload. Sync both whenever a date integer is updated.
    def _date_text(n):
        try:
            n = int(n)
        except (TypeError, ValueError):
            return ''
        return f'{abs(n)} BC' if n < 0 else str(n)

    if 'date_1' in updates:
        updates['date_1_text'] = _date_text(updates['date_1'])
    if 'date_2' in updates:
        updates['date_2_text'] = _date_text(updates['date_2'])

    set_clause = ', '.join(f'{k} = ?' for k in updates.keys())
    now = datetime.utcnow().isoformat()
    params = list(updates.values()) + [now, record_id]
    db.execute(
        f"UPDATE coins SET {set_clause}, updated_at = ? WHERE id = ?",
        params,
    )

    # date_1 housekeeping — same as the old lookup endpoint did
    # inline. If the coin now falls into a numbered group (Carp/NY ×
    # Ancient/Modern), resequence Display Position; if cat_id was
    # blank, mint a fresh one for the new group.
    if 'date_1' in updates:
        group = _coin_group_for(coin['property_name'], updates['date_1'])
        if group:
            _renumber_coin_groups(db, [group])
        if not coin['cat_id']:
            new_cat = next_cat_id(db, coin['property_name'], updates['date_1'])
            if new_cat:
                db.execute("UPDATE coins SET cat_id = ? WHERE id = ?",
                           (new_cat, record_id))
                updates['cat_id'] = new_cat
    db.commit()
    return jsonify({
        'updated': len(updates),
        'fields': list(updates.keys()),
        'values': updates,
    })


# ---------------------------------------------------------------------------
# Banknote spec lookup: same Check contract as coins (lookup-specs +
# apply-lookup-specs feeding the shared review modal), with paper-money
# fields. The dealer's description stays authoritative — grading and
# date fields only change when the dealer's own text backs the value.
# ---------------------------------------------------------------------------

BANKNOTE_SPEC_FILLABLE = (
    'country', 'municipality', 'issue_type', 'issuer', 'official',
    'denomination', 'series',
    'pick_number', 'printer', 'signatures',
    'serial_number', 'watermark',
    'material', 'date_1', 'size_width', 'size_height',
    'grade', 'grade_numeric', 'grading_authority', 'slab_number',
    'grade_condition', 'grade_modifier',
    'lettering', 'lettering_translation',
    'vendor', 'price', 'purchase_date', 'obv_rev',
)

BANKNOTE_SPECS_RESPONSE_SCHEMA = {
    'type': 'object',
    'additionalProperties': False,
    'properties': {
        **{f: _JSON_NULLABLE_STRING for f in (
            'country', 'municipality', 'issue_type', 'issuer', 'official',
            'denomination', 'series',
            'pick_number', 'printer', 'signatures',
            'serial_number',
            'watermark', 'material', 'grade', 'grading_authority',
            'slab_number', 'grade_condition', 'grade_modifier',
            'sheet_position',
            'lettering', 'lettering_translation', 'history_context',
            'vendor', 'price', 'purchase_date', 'obv_rev',
        )},
        'date_1': _JSON_NULLABLE_INTEGER,
        'grade_numeric': _JSON_NULLABLE_NUMBER,
        'size_width': _JSON_NULLABLE_NUMBER,
        'size_height': _JSON_NULLABLE_NUMBER,
        'sources': {'type': 'string'},
    },
    'required': list(BANKNOTE_SPEC_FILLABLE) + ['sources'],
}


# Gregorian-year token for banknote dealer text. Trailing period allowed
# (sentence-final "... 1961. P-38a") unless it starts a decimal; still
# rejects catalogue-ish neighbours like "1961-62", "1961a", "#1961".
_BANKNOTE_YEAR_RE = r'(?<![\w#./-])(1[6-9]\d{2}|20\d{2})(?![\w/-])(?!\.\d)'


# Bare lines in a pasted dealer table that carry no data (section
# headers, empty collector fields) -- dropped during compaction.
_DESC_NOISE_LINES = {
    'item details', "collector's info", 'collectors info', 'comment',
    'tags', 'inventory key', 'expected listing price', 'headquarters',
    'provenance', 'notes',
}


def compact_banknote_description(text):
    """Compact a pasted label/value dealer listing (one pair per line,
    tab- or wide-space-separated -- the Stack's Bowers / PMG inventory
    dump shape) into one linear 'Label: value; ...' paragraph. Prose
    descriptions are left untouched: returns None when the text does
    not look like a table or is already compact."""
    if not text or not text.strip() or '\n' not in text.strip():
        return None
    pairs = []
    bare = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        m = re.match(r'^([^\t]{1,40}?)(?:\t+|\s{3,})(.+)$', line)
        if m:
            label, value = m.group(1).strip(), m.group(2).strip()
            if label.isupper():
                label = ' '.join(
                    w.capitalize() if w.isalpha() and len(w) > 1 else w
                    for w in label.split()
                )
            pairs.append(f'{label}: {value}')
        else:
            if line.lower().strip(': ') in _DESC_NOISE_LINES:
                continue
            # Label-only rows ("Inventory Key") vs real content
            # ("Stack's Bowers logo", a stray prose sentence).
            if len(line.split()) <= 2 and not any(ch.isdigit() for ch in line):
                continue
            bare.append(line)
    if len(pairs) < 3:
        return None
    compacted = '; '.join(pairs + bare)
    return compacted if compacted != text.strip() else None


def _format_purchase_price(raw):
    """Normalize a matched dollar amount to the app's manual-entry style
    ("$2,000", "$175", "$449.50"). Returns None when unparseable."""
    digits = re.sub(r'[^\d.]', '', str(raw or ''))
    if not digits or digits == '.':
        return None
    try:
        n = float(digits)
    except ValueError:
        return None
    if n <= 0 or n >= 10_000_000:
        return None
    if n == int(n):
        return f'${int(n):,}'
    return f'${n:,.2f}'


def _parse_purchase_date(raw):
    """Parse a dealer-text purchase date ("July 11th, 2026", "2026-07-11",
    "7/11/2026") to ISO YYYY-MM-DD. Returns None when unparseable."""
    text = re.sub(r'(\d{1,2})(?:st|nd|rd|th)\b', r'\1', str(raw or '').strip())
    text = re.sub(r'\s+', ' ', text).strip(' ,')
    for fmt in ('%Y-%m-%d', '%B %d, %Y', '%B %d %Y', '%b %d, %Y', '%b %d %Y',
                '%m/%d/%Y', '%m/%d/%y'):
        try:
            d = datetime.strptime(text, fmt)
        except ValueError:
            continue
        if 1900 <= d.year <= 2100:
            return d.strftime('%Y-%m-%d')
    return None


def _banknote_description_fields(note):
    """Read paper-money fields the dealer's own description states.

    Pure text parsing, no network — mirrors _coin_description_fields so
    a missing API key can never stop Check from filling what the record
    already spells out."""
    description = str(_coin_row_value(note, 'description') or '')
    # Purchase facts may sit in the pedigree/notes fields rather than the
    # description proper — parse those from the combined dealer text.
    purchase_text = '\n'.join(
        t for t in (
            description,
            str(_coin_row_value(note, 'note_references') or ''),
            str(_coin_row_value(note, 'notes') or ''),
        ) if t.strip()
    )
    out = {}

    # Purchase facts the pasted listing/invoice states. Dealer-inventory
    # dumps label the paid price "My Cost" (Stack's Bowers collector
    # pages), invoices say "purchase price" / "paid"; prose says
    # "purchased ... for $450". Only labelled or purchase-verb-tied
    # amounts count — a bare $ figure could be a catalog value.
    m = re.search(
        r'\b(?:my\s+cost|purchase\s+price|price\s+paid|total\s+paid|paid)\b'
        r'[:\s]*\$?\s*([\d][\d,]*(?:\.\d{1,2})?)',
        purchase_text, re.IGNORECASE)
    if not m:
        m = re.search(
            r'\b(?:purchased|bought|acquired)\b[^.;\n]{0,60}?'
            r'\bfor\s+\$\s*([\d][\d,]*(?:\.\d{1,2})?)',
            purchase_text, re.IGNORECASE)
    if m:
        price = _format_purchase_price(m.group(1))
        if price:
            out['price'] = price

    # Vendor: only an explicit label or purchase verb — dealer branding
    # ("Stack's Bowers Galleries" letterhead) is left to the model, which
    # can judge whether a name is the seller or just a mention.
    m = re.search(
        r'\b(?:purchased|bought|acquired)\s+from\s+([^.;,\n\t(]{3,60})',
        purchase_text, re.IGNORECASE)
    if not m:
        m = re.search(r'\b(?:vendor|dealer|seller|sold\s+by)\b[:\s]+([^.;,\n\t(]{3,60})',
                      purchase_text, re.IGNORECASE)
    if m:
        vendor = re.sub(r'\s+(?:on|in|at|for)\s+.*$', '', m.group(1)).strip(' -')
        if len(vendor) >= 3:
            out['vendor'] = vendor

    # Purchase date: "PURCHASE DATE  July 11th, 2026", "purchased on
    # 7/11/2026", "bought from X on March 3, 2024".
    _date_alts = (r'([A-Za-z]+\s+\d{1,2}(?:st|nd|rd|th)?,?\s+\d{4}'
                  r'|\d{4}-\d{2}-\d{2}'
                  r'|\d{1,2}/\d{1,2}/\d{2,4})')
    m = re.search(r'\bpurchase[d]?\s*(?:date|on)?\b[:\s]*' + _date_alts,
                  purchase_text, re.IGNORECASE)
    if not m:
        m = re.search(
            r'\b(?:purchased|bought|acquired)\b[^.;\n]{0,60}?\bon\s+' + _date_alts,
            purchase_text, re.IGNORECASE)
    if m:
        parsed = _parse_purchase_date(m.group(1))
        if parsed:
            out['purchase_date'] = parsed

    if not description.strip():
        return out

    # Pick catalogue number: "Pick-67", "P-67b", "Pick 102a", "P#67".
    m = re.search(r'\b(?:pick|p)\s*[-#]?\s*(\d{1,4}[a-z]?)\b',
                  description, re.IGNORECASE)
    if m:
        out['pick_number'] = f'P-{m.group(1)}'

    # Grading service + numeric grade: "PMG-64", "PMG 66 EPQ",
    # "PCGS Banknote 58".
    m = re.search(r'\b(PMG|PCGS(?:\s+Banknote)?|CGA|Legacy)\s*[-#]?\s*(\d{1,2})\b',
                  description, re.IGNORECASE)
    if m:
        out['grading_authority'] = normalize_grading_authority(m.group(1).split()[0])
        try:
            n = float(m.group(2))
            if 1 <= n <= 70:
                out['grade_numeric'] = n
        except ValueError:
            pass

    # EPQ / Star designation rides with the grade.
    if re.search(r'\bEPQ\b', description):
        out['grade_modifier'] = 'EPQ'
    if '★' in description or re.search(r'\bstar\b', description, re.IGNORECASE):
        star = '★'
        out['grade_modifier'] = (out.get('grade_modifier') or '') + star

    # Adjectival grade phrases ("Super Gem UNC", "Crisp Uncirculated",
    # "Extremely Fine") — only match explicit grade wording, then fold
    # through the canonical value-list matcher.
    m = re.search(
        r'\b((?:superb?\s+)?gem\s+(?:crisp\s+)?unc\w*'
        r'|choice\s+(?:crisp\s+)?unc\w*'
        r'|crisp\s+uncirculated|uncirculated'
        r'|(?:about|almost)\s+unc\w*'
        r'|extremely\s+fine|very\s+fine|very\s+good)\b',
        description, re.IGNORECASE)
    if m:
        grade = banknote_grade_value_list_match(m.group(1))
        if grade:
            out['grade'] = grade

    # Printer: "Printed by British Company Harrison", "printer: TDLR".
    # Captures stop at the next comma/period — dealer descriptions are
    # comma-chained clauses, so running past the comma grabs the next
    # unrelated clause (multi-name combos lose their tail; acceptable).
    m = re.search(r'\bprint(?:ed)?\s+by[:\s]+([^.;,\n]{3,80})', description,
                  re.IGNORECASE)
    if m:
        out['printer'] = m.group(1).strip()

    # Signatures: "Signature Nasser-Emami", "signatures: X / Y".
    m = re.search(r'\bsignatures?\b[:\s]+([^.;,\n]{3,80})', description,
                  re.IGNORECASE)
    if m:
        out['signatures'] = m.group(1).strip()

    # Watermark: "Watermark: Shah portrait".
    m = re.search(r'\bwatermarks?\b[:\s]+([^.;,\n]{3,80})', description,
                  re.IGNORECASE)
    if m:
        out['watermark'] = m.group(1).strip()

    # Serial number when explicitly labelled. World-note serials are often
    # a prefix block plus a number separated by spaces ("A/1 129677",
    # "X92 911221") — continue across spaces, but only into chunks that
    # contain a digit so trailing prose is never swallowed.
    m = re.search(
        r'\bserial\s*(?:no\.?|number|#)[:\s]*'
        r'([A-Z0-9][A-Z0-9/\-]*(?:[ ](?=[A-Z0-9/\-]*\d)[A-Z0-9/\-]+){0,3})',
        description, re.IGNORECASE)
    if m:
        serial = m.group(1).strip()
        if 3 <= len(serial) <= 30:
            out['serial_number'] = serial

    # Size: "130 x 67 mm" / "130×67mm".
    m = re.search(r'\b(\d{2,3}(?:[.,]\d+)?)\s*[x×]\s*(\d{2,3}(?:[.,]\d+)?)\s*mm\b',
                  description, re.IGNORECASE)
    if m:
        try:
            out['size_width'] = float(m.group(1).replace(',', '.'))
            out['size_height'] = float(m.group(2).replace(',', '.'))
        except ValueError:
            pass

    # Issue year: a bare Gregorian year, preferring one in parentheses
    # after a local-era date ("SH 1333 (1954)"). Skip catalogue-ref
    # neighbourhoods the same way the coin prose reader does, and skip
    # calendar dates ("July 10th, 2026" is a purchase date, not the
    # issue year). Sentence-final years ("... 1961. P-38a") must match,
    # so a trailing period is allowed unless it starts a decimal.
    year = None
    m = re.search(r'\(\s*(1[6-9]\d{2}|20\d{2})\s*\)', description)
    if m:
        year = int(m.group(1))
    else:
        for m in re.finditer(_BANKNOTE_YEAR_RE, description):
            before = description[max(0, m.start() - 14):m.start()].lower()
            if any(tok in before for tok in ('pick', 'p-', '#', 'no.', 'lot')):
                continue
            if re.search(r'[a-z]{2,9}\.?\s+\d{1,2}(?:st|nd|rd|th)?\s*,?\s*$',
                         before):
                continue
            year = int(m.group(1))
            break
    if year:
        out['date_1'] = year
    return out


def fetch_banknote_specs(note):
    """Fill missing identifying fields on a banknote via Claude vision +
    web search. Same contract as fetch_coin_specs: returns {field: value}
    with ONLY confident values; the dealer's text is authoritative.

    The note's own front/back images are attached, so the model can scan
    the note directly — read and translate the lettering, and use text
    printed on the note (town, dates, denomination, serial) as evidence."""
    known = {}
    for f in BANKNOTE_SPEC_FILLABLE:
        v = _coin_row_value(note, f)
        if v not in (None, ''):
            known[f] = v

    grades = ', '.join(VALUE_LISTS['banknote_grade'])
    materials = ', '.join(VALUE_LISTS['banknote_material'])
    issue_types = ', '.join(VALUE_LISTS['banknote_issue_type'])
    description = (_coin_row_value(note, 'description') or '').strip()
    pedigree = (_coin_row_value(note, 'note_references') or '').strip()
    grade_notes = (_coin_row_value(note, 'notes') or '').strip()
    condition = (_coin_row_value(note, 'condition') or '').strip()

    # Scan the note itself: front/back images are attached ahead of the
    # prompt so the model reads the lettering and printed details
    # directly. Missing/unreadable files degrade to a text-only lookup.
    images = _load_vision_images((
        (_coin_row_value(note, 'image_1'), 'front'),
        (_coin_row_value(note, 'image_2'), 'back'),
    ))

    # Images or a pasted dealer description are enough to identify a
    # note — the images-first flow (drop photos, hit Check) must work
    # on a brand-new record with no structured fields typed yet.
    if not known and not description and not pedigree and not images:
        raise RuntimeError(
            'Add the note images, the dealer description, or at least '
            'one identifying field (country / denomination / Pick #) '
            'before running Check.')

    known_lines = '\n'.join(f'- {k}: {v}' for k, v in known.items()) or '(none entered)'
    dealer_blocks = []
    if description: dealer_blocks.append(f'DESCRIPTION:\n{description[:4000]}')
    if pedigree:    dealer_blocks.append(f'REFERENCES / PEDIGREE:\n{pedigree[:2000]}')
    if grade_notes: dealer_blocks.append(f'GRADE / CONDITIONS NOTES:\n{grade_notes[:2000]}')
    if condition:   dealer_blocks.append(f'HISTORICAL / OTHER NOTES:\n{condition[:1500]}')
    dealer_text = '\n\n'.join(dealer_blocks) if dealer_blocks else '(no dealer text on file)'

    prompt = f"""You are extracting structured catalogue fields for one specific banknote (paper money).

PRIMARY SOURCES for THIS note, in order of authority:
1. The note's own images above (front/back, when attached) — direct evidence for everything printed ON the note: lettering, issuing town, dates, denomination, serial number, signatures. When the note sits in a grading-service holder (PMG / PCGS Banknote), the holder's printed label is equally direct evidence: read the denomination, series year, catalog attribution (Fr# / Pick#), signature combination, serial number, grade line, and certification number straight off it.
2. The selling dealer's own text below — authoritative for grading, attribution, and anything the images don't show.
{dealer_text}

Structured fields the user has already transcribed from the dealer:
{known_lines}

Rules:
1. For each target field, FIRST take what the note's images and the dealer's text state.
2. Only when neither states a field may you use up to 3 web searches (Standard Catalog of World Paper Money / Pick numbers, Grabowski-Mehl and other notgeld catalogs, PMG population reports, Numista, Banknote World, Heritage Auctions, Stack's Bowers) to fill it. NEVER override a value the images or dealer's text state with a web guess.
3. The grading fields (grading_authority, grade_numeric, slab_number, grade_modifier) and the grade must come ONLY from the dealer's text or from a grading-service label readable in the attached images — do not web-search or estimate them. Return null if neither states them.
4. The purchase fields (vendor, price, purchase_date) must come ONLY from the text and images on file — an invoice line, "My Cost", "purchased from", or the listing's own branding. NEVER web-search them, and NEVER report a catalog value, price guide figure, auction estimate, or another sale's realized price as the price paid. Return null if the material on file does not state them.
5. Return null whenever a value is not supported by the images, the text, or (for web-allowed fields) a reputable source.

Target fields:
- country: issuing country as commonly catalogued (e.g. "Iran", "Germany").
- municipality: the issuing town / locality for notgeld, emergency, or municipal issues (e.g. "Bielefeld") — usually printed prominently on the note itself. Null for national issues.
- issue_type: EXACTLY one of [{issue_types}]. German/Austrian emergency money is "Notgeld"; state or central-bank issues are "National". Null if unclear.
- issuer: the issuing bank or authority (e.g. "Bank Melli Iran (National Bank)", "Stadt Bielefeld").
- official: the person portrayed or the ruler under whom the note was issued, as "Name" or "Name, role" (e.g. "Muhammad Reza Shah Pahlavi"). Null if none.
- denomination: face value with currency (e.g. "100 Rials", "50 Pfennig").
- series: the series / set name or year designation if catalogued — notgeld was often issued in themed sets (e.g. "Series 1928", "Leinen-Ausgabe"). Null if not stated.
- pick_number: ALL catalogue references for this note in one comma-separated list, verbatim as cited — the Pick number formatted "P-<number><letter>" (e.g. "P-67", "P-102a"); for United States federal issues the Friedberg number ("Fr#248" — a grading label's attribution goes here verbatim); plus TBB and specialist catalogues (Grabowski/Mehl, Rosenberg, Lamb, Funck, Menzel, Tieste — e.g. "Grabowski Bi.7.5"). Null if none.
- printer: the printing firm (e.g. "Harrison & Sons", "Thomas De La Rue"; notgeld was often locally printed).
- signatures: signature combination as stated or visible (e.g. "Nasser-Emami").
- serial_number: THIS note's serial number, from the images or the text; else null.
- watermark: watermark description if stated or catalogued (e.g. "Young Shah portrait").
- material: EXACTLY one of [{materials}]; null if unknown.
- date_1: integer Gregorian year of issue (e.g. 1954, 1921). A date printed on the note counts as direct evidence. If the note is dated in a local era (SH/AH/BE), convert to the Gregorian year the dealer gives; do not compute your own conversion unless the dealer states it.
- size_width: printed note width in mm (float); size_height: height in mm (float).
- grade: map the dealer's stated grade to EXACTLY one of [{grades}] (c = choice, a = about; "Super Gem UNC" → "Superb Gem UNC"; XF → EF). Null if outside the list.
- grade_numeric: the numeric grade 1-70 if a grading service number is stated (e.g. "PMG-64" → 64); else null.
- grading_authority: the grading company if the note is or was slabbed and the text names it — "PMG", "PCGS Banknote", "CGA", "Legacy". Else null.
- slab_number: the certification number if stated, verbatim; else null.
- grade_condition: condition qualifier(s) noted alongside the grade — e.g. "minor rust", "pinholes", "annotation", "small tear". Comma-separated, lowercase; else null.
- grade_modifier: "EPQ" when the text shows EPQ (Exceptional Paper Quality), "★" for a star designation, "EPQ★" for both, "+" for a plus grade. Else null.
- sheet_position: THIS note's position on the printing sheet, when identifiable from the images or the dealer's text — an uncut/partial-sheet position stated like "2 of 4", or the plate-position letter/number printed in the note's margin or corner (e.g. "A", "D12", "Position 7"). Direct evidence only — never inferred from a catalogue. Null when not shown or stated.
- lettering: the significant text printed ON the note, read from the images (and the dealer's text where it quotes the note). Original script/language, one inscription per line, prefixed "Front:" / "Back:". Cover the issuer line, denomination line, date line, and any slogan/verse/decree; skip serial numbers and plate letters. Null only if no images and no quoted text. EXCEPTION — when the note's text is already ENGLISH: no translation is needed, so the two fields become the two sides instead: put ONLY the FRONT inscriptions here (lines prefixed "Front:"), matching the front image on the left.
- lettering_translation: English translation of each lettering line, same order and same Front:/Back: prefixes. Transliterate non-Latin scripts in parentheses where helpful. EXCEPTION — when the note's text is already ENGLISH: put ONLY the BACK inscriptions here (lines prefixed "Back:"), matching the back image on the right, with the front inscriptions in lettering. Null only when there is nothing to report.
- history_context: a VERY SHORT historical-context narrative — 2-3 sentences, under 70 words. Why this note existed: who issued it, what was happening then and there (hyperinflation, war, occupation, nationalization, currency reform), and anything notable about this type. Plain prose, no headings, no citations inline. Web searches allowed. Null if you cannot say anything reliable.
- vendor: the dealer or auction house THIS note was purchased from, only when the material on file identifies it — an explicit "purchased from X" / vendor / seller line, an invoice, or the pasted listing's own branding or letterhead (a Stack's Bowers inventory page means vendor "Stack's Bowers"; a Heritage lot page means "Heritage Auctions"). A firm merely mentioned in the pedigree ("ex Spink sale") is prior provenance, not the vendor — when in doubt, null.
- price: the price PAID for this note, only when the material on file states it ("My Cost", "purchase price", "paid", an invoice total, "purchased for $X"). Format "$1,234" or "$1,234.56". This is never a catalog value, estimate, or price guide figure.
- purchase_date: the date THIS note was purchased, as "YYYY-MM-DD", only when the material on file states it ("Purchase Date July 11th, 2026" → "2026-07-11"). Null otherwise.
- obv_rev: one very short line naming the main obverse and reverse designs, format "Obv: ... / Rev: ..." (e.g. "Obv: young Shah portrait / Rev: Abadan Refinery"), under 90 characters, from the note images or the dealer text. Null if you cannot tell.

Reply with ONLY a JSON object, no prose, no code fences. Use null when a value is not supported:
{{
  "country": null, "municipality": null, "issue_type": null,
  "issuer": null, "official": null, "denomination": null,
  "series": null, "pick_number": null,
  "printer": null, "signatures": null,
  "serial_number": null, "watermark": null, "material": null,
  "date_1": null, "size_width": null, "size_height": null,
  "grade": null, "grade_numeric": null, "grading_authority": null,
  "slab_number": null, "grade_condition": null, "grade_modifier": null,
  "sheet_position": null,
  "lettering": null, "lettering_translation": null, "history_context": null,
  "vendor": null, "price": null, "purchase_date": null, "obv_rev": null,
  "sources": "one-line note of where each value came from (note images vs dealer text vs which web source)"
}}
"""

    api_key = _require_anthropic_key()
    try:
        import anthropic
    except ImportError:
        raise RuntimeError("anthropic package not installed.")

    client = anthropic.Anthropic(api_key=api_key, timeout=240.0)
    lookup_model = anthropic_lookup_model(api_key, 'ANTHROPIC_COIN_LOOKUP_MODEL')
    web_search = anthropic_web_search_tool(4)

    content = []
    for img in images:
        content.append({'type': 'text', 'text': f'{img["label"].capitalize()} of the note:'})
        content.append({'type': 'image', 'source': {
            'type': 'base64',
            'media_type': img['media_type'],
            'data': img['data'],
        }})
    content.append({'type': 'text', 'text': prompt})

    import time as _time
    transient_errs = _anthropic_transient_errs(anthropic)
    resp = None
    last_err = None
    # 2048 tokens was silently truncating full banknote responses
    # (lettering + translation + history + short desc easily pass it),
    # which surfaced as a JSON parse failure and a description-only
    # fallback. 8192 leaves ample headroom; the stop_reason check below
    # catches any remaining truncation instead of failing cryptically.
    for attempt in range(3):
        try:
            resp = client.messages.create(
                model=lookup_model,
                max_tokens=8192,
                tools=[web_search],
                messages=[{'role': 'user', 'content': content}],
            )
            break
        except transient_errs as e:
            last_err = e
            if attempt == 2:
                raise RuntimeError(_friendly_lookup_error('Banknote spec lookup', last_err))
            _time.sleep(10 * (attempt + 1))
    if resp is None:
        raise RuntimeError('Banknote spec lookup returned no response')
    if getattr(resp, 'stop_reason', None) == 'max_tokens':
        raise RuntimeError('Banknote spec lookup response hit the length limit — try again.')

    text = _message_text(resp)
    text = re.sub(r'^```(?:json)?\s*', '', text.strip())
    text = re.sub(r'\s*```$', '', text)
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        m = re.search(r'\{[\s\S]*\}', text)
        if m:
            return json.loads(m.group(0))
        raise RuntimeError('Could not parse Claude response as JSON')


def _coerce_banknote_spec(field, raw):
    """Coerce one suggested banknote field to its storable form (or None)."""
    if raw is None:
        return None
    if field == 'material':
        if not isinstance(raw, str):
            return None
        allowed = {m.lower(): m for m in VALUE_LISTS['banknote_material']}
        return allowed.get(raw.strip().lower())
    if field == 'issue_type':
        if not isinstance(raw, str):
            return None
        allowed = {t.lower(): t for t in VALUE_LISTS['banknote_issue_type']}
        v = raw.strip().lower()
        # Common shorthand → canonical axis values.
        v = {'emergency': 'notgeld', 'military': 'military / occupation',
             'occupation': 'military / occupation', 'scrip': 'private / scrip',
             'private': 'private / scrip'}.get(v, v)
        return allowed.get(v)
    if field in ('date_1', 'date_2'):
        try:
            return int(raw)
        except (TypeError, ValueError):
            return None
    if field in ('size_width', 'size_height', 'grade_numeric'):
        if isinstance(raw, str):
            m = re.match(r'^\s*(-?\d+(?:[.,]\d+)?)', raw)
            if not m:
                return None
            try:
                raw = float(m.group(1).replace(',', '.'))
            except ValueError:
                return None
        try:
            v = float(raw)
        except (TypeError, ValueError):
            return None
        if field == 'grade_numeric' and not (1 <= v <= 70):
            return None
        return v
    if field == 'grade':
        return banknote_grade_value_list_match(raw)
    if field == 'grading_authority':
        return normalize_grading_authority(raw)
    if field == 'grade_modifier':
        # Keep EPQ verbatim; fold star/plus like coins.
        v = (raw if isinstance(raw, str) else str(raw)).strip()
        if not v:
            return None
        if 'epq' in v.lower():
            return 'EPQ★' if ('★' in v or 'star' in v.lower()) else 'EPQ'
        return normalize_grade_modifier(v)
    if field == 'price':
        return _format_purchase_price(raw)
    if field == 'purchase_date':
        return _parse_purchase_date(raw)
    if field in ('pick_number', 'slab_number', 'serial_number',
                 'grade_condition', 'printer', 'signatures', 'watermark',
                 'series', 'vendor'):
        v = (raw if isinstance(raw, str) else str(raw)).strip()
        return v or None
    if isinstance(raw, str):
        return normalize_field_value('banknotes', field, raw.strip()) or None
    return raw


@app.route('/banknotes/<record_id>/lookup-specs', methods=['POST'])
def banknote_lookup_specs(record_id):
    """Fill blank banknote fields — description first, then web lookup."""
    db = get_db()
    note = db.execute("SELECT * FROM banknotes WHERE id = ?",
                      (record_id,)).fetchone()
    if not note:
        return jsonify({'error': 'Banknote not found'}), 404

    suggestions = {}
    lookup_error = None
    lookup_status = 503
    try:
        suggestions = fetch_banknote_specs(note)
    except RuntimeError as e:
        lookup_error = str(e)
    except Exception as e:
        import traceback
        print(traceback.format_exc(), flush=True)
        lookup_error = f'Lookup failed: {e or e.__class__.__name__}'
        lookup_status = 500

    if not isinstance(suggestions, dict):
        suggestions = {}
    # The dealer's own description is canonical and needs no network —
    # overlay it last so it always wins.
    for field, value in _banknote_description_fields(note).items():
        if value not in (None, ''):
            suggestions[field] = value

    if lookup_error and not any(
        suggestions.get(f) not in (None, '') for f in BANKNOTE_SPEC_FILLABLE
    ):
        return jsonify({'error': lookup_error}), lookup_status

    # Grading + date + purchase fields are dealer-authoritative: only
    # propose a value the dealer's own text backs (same principle as
    # coins). Purchase facts especially must never be model guesses.
    DEALER_FIELDS = {'date_1', 'grade', 'grade_numeric',
                     'grading_authority', 'slab_number', 'grade_condition',
                     'grade_modifier', 'pick_number', 'serial_number',
                     'vendor', 'price', 'purchase_date'}
    dealer_text = ' '.join(
        str(_coin_row_value(note, c) or '')
        for c in ('description', 'note_references', 'condition', 'notes')
    )
    _dealer_text_key = re.sub(r'[^a-z0-9]', '', dealer_text.lower())
    _dealer_years = {
        int(m.group(1))
        for m in re.finditer(_BANKNOTE_YEAR_RE, dealer_text)
    }

    _has_images = bool(
        _coin_row_value(note, 'image_1') or _coin_row_value(note, 'image_2')
    )
    # Fields a grading-service holder label states outright. With images
    # attached AND the model naming a grading authority (i.e. it saw a
    # slab label), these are image-read facts — dealer-text grounding
    # would reject exactly what the label shows.
    _SLAB_LABEL_FIELDS = {'grade', 'grade_numeric', 'grading_authority',
                          'slab_number', 'grade_condition', 'grade_modifier',
                          'pick_number'}

    def _grounded(field, value):
        if field in ('date_1', 'date_2'):
            try:
                year = int(value)
            except (TypeError, ValueError):
                return False
            if year in _dealer_years:
                return True
            # No dealer text to ground against: the series year is
            # printed on the note (and its slab label) — trust the
            # image read, same rationale as the serial below.
            return _has_images and not _dealer_years
        if field == 'serial_number' and _has_images:
            # The serial is printed ON the note: with images attached the
            # model reads it directly, so dealer-text grounding would
            # reject exactly the image-read serials Check exists to find.
            return True
        if field in _SLAB_LABEL_FIELDS and _has_images and \
                suggestions.get('grading_authority'):
            return True
        if field in ('slab_number', 'serial_number', 'pick_number'):
            key = re.sub(r'[^a-z0-9]', '', str(value).lower()).lstrip('p')
            return len(key) >= 1 and key in _dealer_text_key
        if field == 'grade_numeric':
            return re.sub(r'\.0$', '', str(value)) in dealer_text
        if field == 'grade':
            return banknote_grade_value_list_match(dealer_text) == value or \
                str(value).lower() in dealer_text.lower()
        if field == 'grade_condition':
            words = re.findall(r'[a-z]{3,}', str(value).lower())
            return bool(words) and all(w in _dealer_text_key for w in words)
        if field == 'grade_modifier':
            v = str(value)
            if 'EPQ' in v and 'epq' not in dealer_text.lower():
                return False
            if '★' in v and not ('★' in dealer_text or 'star' in dealer_text.lower()):
                return False
            if '+' in v and '+' not in dealer_text:
                return False
            return True
        if field == 'price':
            # The paid amount must appear in the dealer text ("$2,000",
            # "2000", "2,000.00") — a plausible-looking price the model
            # produced from a catalog value is rejected here.
            digits = re.sub(r'[^\d.]', '', str(value))
            try:
                n = float(digits) if digits else None
            except ValueError:
                n = None
            if n is None:
                return False
            forms = {f'{int(n):,}', str(int(n))}
            if n != int(n):
                forms |= {f'{n:,.2f}', f'{n:.2f}'}
            return any(f in dealer_text for f in forms)
        if field == 'vendor':
            # The named firm must actually appear in the dealer text:
            # first token always, and at least half the tokens overall.
            tokens = re.findall(r'[a-z0-9]{3,}', str(value).lower())
            if not tokens:
                return False
            hits = sum(1 for t in tokens if t in _dealer_text_key)
            return tokens[0] in _dealer_text_key and hits * 2 >= len(tokens)
        if field == 'purchase_date':
            try:
                year = int(str(value)[:4])
            except (TypeError, ValueError):
                return False
            lowered = dealer_text.lower()
            return year in _dealer_years and any(
                k in lowered for k in ('purchas', 'bought', 'acquired', 'invoice')
            )
        return True

    filled = {}
    overwritten = {}
    # Short historical narrative → the "Historical Context, Notes" field
    # (the `condition` column, coins convention). Fill-only: an existing
    # note is the user's own and is never proposed for overwrite.
    hc = suggestions.get('history_context')
    if isinstance(hc, str) and hc.strip() and not (
        _coin_row_value(note, 'condition') or ''
    ).strip():
        filled['condition'] = hc.strip()
    for f in BANKNOTE_SPEC_FILLABLE:
        v = _coerce_banknote_spec(f, suggestions.get(f))
        if v in (None, ''):
            continue
        if f in DEALER_FIELDS and not _grounded(f, v):
            continue
        cur = note[f]
        if cur in (None, ''):
            filled[f] = v
        elif f in ('date_1', 'date_2'):
            try:
                same = int(cur) == int(v)
            except (TypeError, ValueError):
                same = False
            if not same:
                overwritten[f] = {'current': cur, 'new': v}
        elif f in ('size_width', 'size_height', 'grade_numeric'):
            try:
                same = abs(float(cur) - float(v)) < 0.05
            except (TypeError, ValueError):
                same = False
            if not same:
                overwritten[f] = {'current': cur, 'new': v}
        elif str(cur or '').strip().lower() != str(v or '').strip().lower():
            overwritten[f] = {'current': cur, 'new': v}

    # Sheet / plate position ("2 of 4", "A") → appended to the
    # "Grade, Conditions" notes field, no column of its own. Image reads
    # count as direct evidence (the position is printed on the note);
    # otherwise it must appear in the dealer's text.
    sp = suggestions.get('sheet_position')
    if isinstance(sp, str) and sp.strip():
        sp = sp.strip()
        sp_grounded = _has_images or \
            re.sub(r'[^a-z0-9]', '', sp.lower()) in _dealer_text_key
        cur_notes = (_coin_row_value(note, 'notes') or '').strip()
        sp_line = sp if re.search(r'(?i)sheet|plate|position', sp) \
            else f'Sheet position {sp}'
        if sp_grounded and sp.lower() not in cur_notes.lower():
            if cur_notes:
                overwritten['notes'] = {'current': cur_notes,
                                        'new': f'{cur_notes}\n{sp_line}'}
            else:
                filled['notes'] = sp_line

    # Pasted dealer tables hog vertical space: propose the linear
    # 'Label: value; ...' rewrite of the description for approval.
    current_description = str(_coin_row_value(note, 'description') or '')
    compacted = compact_banknote_description(current_description)
    if compacted:
        overwritten['description'] = {'current': current_description,
                                      'new': compacted}

    # Only stamp a fully successful run: a partial (description-only)
    # result keeps the Check button un-done so a retry isn't skipped.
    now = None
    if not lookup_error:
        now = datetime.utcnow().isoformat()
        db.execute("UPDATE banknotes SET specs_searched_at = ? WHERE id = ?",
                   (now, record_id))
        db.commit()

    # Slab photos have now served their purpose (the lookup above read
    # the holder label off them) — trim each stored image down to just
    # the note, levelled. Only after a full run: a failed scan keeps the
    # labels intact so a retry can still read them. The untrimmed
    # original stays on disk (orphan-uploads can sweep it later).
    images_updated = {}
    if not lookup_error:
        for field in ('image_1', 'image_2'):
            fname = _coin_row_value(note, field)
            if not fname or not is_image_filter(fname):
                continue
            try:
                with open(os.path.join(UPLOAD_FOLDER, fname), 'rb') as fh:
                    raw = fh.read()
                trimmed = _trim_slabbed_note_image(raw)
            except Exception as e:
                app.logger.warning('banknote %s: trim of %s (%s) failed: %s',
                                   record_id, field, fname, e)
                continue
            if not trimmed:
                continue
            new_name = f"{uuid.uuid4().hex}.jpg"
            with open(os.path.join(UPLOAD_FOLDER, new_name), 'wb') as fh:
                fh.write(trimmed)
            db.execute(
                f"UPDATE banknotes SET {field} = ?, updated_at = ? WHERE id = ?",
                (new_name, datetime.utcnow().isoformat(), record_id))
            images_updated[field] = url_for('uploaded_file', filename=new_name)
        if images_updated:
            db.commit()

    return jsonify({
        'filled': filled,
        'overwritten': overwritten,
        'images': images_updated,
        'sources': suggestions.get('sources', ''),
        'specs_searched_at': now,
        # The image/web lookup failed but the dealer-description parser
        # still produced fields — tell the user the scan was partial so
        # a rerun isn't skipped ("it already ran") by mistake.
        'lookup_error': lookup_error,
    })


@app.route('/banknotes/<record_id>/apply-lookup-specs', methods=['POST'])
def banknote_apply_lookup_specs(record_id):
    """Apply a user-selected subset of banknote lookup suggestions.

    Body: ``{"updates": {"<field>": <value>, ...}}`` — only fields in
    BANKNOTE_SPEC_FILLABLE are accepted."""
    db = get_db()
    note = db.execute("SELECT * FROM banknotes WHERE id = ?",
                      (record_id,)).fetchone()
    if not note:
        return jsonify({'error': 'Banknote not found'}), 404
    data = request.get_json(force=True) or {}
    raw = data.get('updates') or {}
    if not isinstance(raw, dict):
        return jsonify({'error': 'updates must be an object'}), 400

    updates = {}
    for k, v in raw.items():
        # `condition` carries the Check-generated historical narrative;
        # `description` carries the compacted-listing rewrite; `notes`
        # carries the sheet-position append to Grade, Conditions.
        if k not in BANKNOTE_SPEC_FILLABLE and k not in ('condition', 'description', 'notes'):
            continue
        coerced = _coerce_banknote_spec(k, v)
        if coerced in (None, ''):
            continue
        updates[k] = coerced
    if not updates:
        return jsonify({'updated': 0, 'fields': []})

    # Keep the display text columns in sync with the integer dates —
    # same shadowing rule as coins.
    def _date_text(n):
        try:
            return str(int(n))
        except (TypeError, ValueError):
            return ''

    if 'date_1' in updates and not (note['date_1_text'] or '').strip():
        updates['date_1_text'] = _date_text(updates['date_1'])

    # Lookup-extracted fields get the same intake canonicalization as
    # the forms — the model returns 'United States', the collection
    # spells it 'United States of America'.
    canonicalize_banknote_fields(updates, existing=note)

    set_clause = ', '.join(f'{k} = ?' for k in updates.keys())
    now = datetime.utcnow().isoformat()
    db.execute(
        f"UPDATE banknotes SET {set_clause}, updated_at = ? WHERE id = ?",
        list(updates.values()) + [now, record_id],
    )
    if not note['cat_id']:
        new_cat = next_serial_cat_id(db, 'banknotes', 'B')
        db.execute("UPDATE banknotes SET cat_id = ? WHERE id = ?",
                   (new_cat, record_id))
        updates['cat_id'] = new_cat
    db.commit()
    if updates.get('country'):
        ensure_country_history(updates['country'])
    return jsonify({
        'updated': len(updates),
        'fields': list(updates.keys()),
        'values': updates,
    })


@app.route('/<category>/<record_id>/upload-image', methods=['POST'])
def upload_image(category, record_id):
    """AJAX endpoint: drop an image on a list row to set its primary image."""
    if category not in CATEGORIES:
        return jsonify({'error': 'Unknown category'}), 400
    f = request.files.get('image')
    if not f or not f.filename:
        return jsonify({'error': 'No file'}), 400
    if not allowed_file(f.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Allow specifying which image field to update (for coins with image_1/image_2 etc.)
    image_field = request.form.get('field') or CATEGORIES[category]['image_field']
    table       = CATEGORIES[category]['table']
    db = get_db()
    valid = {f['name']: f for f in visible_fields(category)}
    if image_field not in valid or valid[image_field].get('type') != 'file':
        return jsonify({'error': 'Invalid file field'}), 400
    cols = [row['name'] for row in db.execute(f"PRAGMA table_info({table})").fetchall()]
    if image_field not in cols:
        return jsonify({'error': 'Invalid field'}), 400
    existing = db.execute(
        f"SELECT * FROM {table} WHERE id = ?", [record_id]
    ).fetchone()
    if not existing:
        return jsonify({'error': 'Record not found'}), 404
    if not _user_can_see_row(category, existing):
        return jsonify({'error': 'Forbidden'}), 403

    stored = save_upload(f, optimize_image=_is_item_image_field(category, image_field))
    if not stored:
        return jsonify({'error': 'Upload failed'}), 500

    db.execute(f"UPDATE {table} SET {image_field} = ?, updated_at = ? WHERE id = ?",
               [stored, datetime.utcnow().isoformat(), record_id])
    _autofill_title_from_filename(db, table, record_id, category,
                                  image_field, f.filename)
    db.commit()

    return jsonify({
        'url': url_for('uploaded_file', filename=stored),
        'thumb_url': url_for('file_thumb', filename=stored),
    })


# File-typed columns whose underlying file we INTENTIONALLY keep on disk
# after a UI delete. These four power record-specific lookups (license OCR,
# health-card auto-fill) and may be re-attached after a mistaken delete; the
# orphan-uploads admin can still sweep them later if truly abandoned.
_PRESERVE_FILE_FIELDS = frozenset({
    'license_obverse', 'license_reverse',
    'health_card_obv', 'health_card_rev',
})


def _unlink_upload(filename):
    """Best-effort delete of an uploaded file (and its cached thumbnail)
    from UPLOAD_FOLDER. Filename must be the bare basename written by
    save_upload (uuid.ext); anything with a path separator or leading
    dot is rejected to prevent traversal or hitting the .thumbs cache."""
    name = (filename or '').strip()
    if not name or '/' in name or '\\' in name or name.startswith('.'):
        return
    try:
        os.unlink(os.path.join(UPLOAD_FOLDER, name))
    except OSError:
        pass
    try:
        os.unlink(os.path.join(_FILE_THUMB_DIR, name + '.jpg'))
    except OSError:
        pass


@app.route('/<category>/<record_id>/delete-file', methods=['POST'])
def delete_file_field(category, record_id):
    """Clear a single file column on a record (NULL it out) and delete the
    underlying file from disk, EXCEPT for the four ID/health card fields
    in _PRESERVE_FILE_FIELDS — those keep the file so the special OCR /
    auto-fill flows can still reach it. Validated against FIELDS so only
    declared file fields can be cleared."""
    if category not in CATEGORIES:
        return jsonify({'error': 'Unknown category'}), 400
    payload = request.get_json(silent=True) or {}
    field_name = (payload.get('field') or '').strip()
    valid = {f['name']: f for f in visible_fields(category)}
    if field_name not in valid or valid[field_name].get('type') != 'file':
        return jsonify({'error': 'Invalid file field'}), 400
    db = get_db()
    table = CATEGORIES[category]['table']
    cols = [row['name'] for row in db.execute(f"PRAGMA table_info({table})").fetchall()]
    if field_name not in cols:
        return jsonify({'error': 'Column not in table'}), 400
    existing = db.execute(
        f"SELECT * FROM {table} WHERE id = ?", [record_id]
    ).fetchone()
    if not existing:
        return jsonify({'error': 'Record not found'}), 404
    if not _user_can_see_row(category, existing):
        return jsonify({'error': 'Forbidden'}), 403
    old_filename = existing[field_name] if existing else None
    # Clear the paired title/label column too so the tile doesn't keep
    # showing a leftover auto-fill from a since-removed file.
    title_field = _title_field_for(category, field_name)
    cleared_title = title_field if title_field and title_field in cols else None
    # Compute the export-shaped label for the tombstone before we NULL
    # the title column. Prefer the user-supplied title; fall back to
    # the default label from EXPORT_LAYOUT.
    tombstone_label = ''
    if existing and old_filename:
        plan = EXPORT_LAYOUT.get(category, {})
        for spec in plan.get('files', []):
            f, default_label, t_field = spec
            if f == field_name:
                if t_field and t_field in cols and existing[t_field]:
                    tombstone_label = (existing[t_field] or '').strip()
                if not tombstone_label:
                    tombstone_label = default_label or ''
                break
    sets = [f"{field_name} = NULL"]
    if cleared_title:
        sets.append(f"{cleared_title} = NULL")
    sets.append("updated_at = ?")
    db.execute(
        f"UPDATE {table} SET {', '.join(sets)} WHERE id = ?",
        [datetime.utcnow().isoformat(), record_id],
    )
    if old_filename and field_name not in _PRESERVE_FILE_FIELDS:
        _record_tombstone(db, category, existing, tombstone_label, old_filename)
    db.commit()
    if old_filename and field_name not in _PRESERVE_FILE_FIELDS:
        _unlink_upload(old_filename)
    return jsonify({'ok': True, 'cleared_title': cleared_title})


# ---------------------------------------------------------------------------
# Template filters
# ---------------------------------------------------------------------------

# Currency prefixes the JS formatter writes on blur. Anything starting
# with one of these is treated as already-formatted and round-trips
# verbatim through save / display. Besides the symbol majors, the JS
# writes any Frankfurter-supported ISO code as "CAD 140 / $102" — so a
# generic 3-letter-code prefix counts as pre-formatted too.
_CURRENCY_PREFIX_RE = re.compile(
    r'^\s*(A\$|US\$|\$|€|£|¥|[A-Za-z]{3}(?=[\s\d]|$))',
    re.IGNORECASE)


def _format_us_phone(value):
    raw = str(value or '').strip()
    if not raw:
        return ''
    ext_match = re.search(
        r'\s*(?:ext\.?|extension|x)\s*(\d{1,8})\s*$',
        raw,
        re.IGNORECASE,
    )
    ext = ext_match.group(1) if ext_match else ''
    main = raw[:ext_match.start()].strip() if ext_match else raw
    compact_main = re.sub(r'[^\d+]', '', main)
    if compact_main.startswith('+') and not compact_main.startswith('+1'):
        return raw
    digits = re.sub(r'\D', '', main)
    has_country_code = len(digits) == 11 and digits.startswith('1')
    phone = digits[1:] if has_country_code else digits
    if len(phone) != 10:
        return raw
    formatted = (
        f"{'+1 ' if has_country_code else ''}"
        f"({phone[:3]}) {phone[3:6]}-{phone[6:]}"
    )
    return f"{formatted} x{ext}" if ext else formatted


@app.template_filter('us_phone')
def us_phone_filter(value):
    return _format_us_phone(value)


@app.route('/fx-rate')
def fx_rate():
    """Lookup-only: return a cached USD-conversion rate from the
    fx_rates table, or 404 if not cached. The browser blur handler
    tries this first; on a 404 it falls back to a direct fetch from
    api.frankfurter.dev and POSTs the result to /fx-rate/save so
    future hits are served from this cache. Outbound HTTP doesn't
    happen on this path — Railway's flaky egress is bypassed
    entirely."""
    currency = (request.args.get('currency') or '').strip().upper()
    date_str = (request.args.get('date') or '').strip()
    if not currency or not date_str:
        return jsonify({'ok': False, 'error': 'currency + date required'}), 400
    if currency == 'USD':
        return jsonify({'ok': True, 'rate': 1.0, 'cached': True})
    db = get_db()
    row = db.execute(
        'SELECT usd_rate FROM fx_rates WHERE currency = ? AND date = ?',
        [currency, date_str]
    ).fetchone()
    if row is None:
        return jsonify({'ok': False, 'error': 'not cached'}), 404
    return jsonify({'ok': True, 'rate': float(row['usd_rate']), 'cached': True})


@app.route('/fx-rate/save', methods=['POST'])
def fx_rate_save():
    """Client posts a (currency, date, rate) triple here after a
    successful direct fetch from the FX provider. Idempotent —
    PRIMARY KEY (currency, date) means re-saves are no-ops."""
    payload = request.get_json(silent=True) or {}
    currency = (payload.get('currency') or '').strip().upper()
    date_str = (payload.get('date') or '').strip()
    try:
        rate = float(payload.get('rate'))
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'error': 'rate must be a number'}), 400
    if not currency or not date_str or rate <= 0:
        return jsonify({'ok': False, 'error': 'currency + date + rate required'}), 400
    db = get_db()
    db.execute(
        'INSERT OR REPLACE INTO fx_rates '
        '(currency, date, usd_rate, fetched_at) VALUES (?, ?, ?, ?)',
        [currency, date_str, rate, datetime.utcnow().isoformat()]
    )
    db.commit()
    return jsonify({'ok': True})


def _normalize_price_input(val):
    """Price-input normaliser. Pre-formatted strings with a currency
    prefix ($/A$/€/£/¥ or any 3-letter ISO code) round-trip verbatim
    — the JS blur formatter is the source of truth for those.
    Anything else falls back to the legacy strip-symbols-and-parse
    behaviour so existing plain-number entries keep working."""
    s = (val or '').strip()
    if not s:
        return s
    if _CURRENCY_PREFIX_RE.match(s):
        return s
    s = s.replace('$', '').replace(',', '').strip()
    m = re.match(r'^\s*(-?\d+(?:\.\d+)?)\s*[A-Za-z%°/]*\s*$', s)
    return m.group(1) if m else s


def _parse_order_money(value):
    if isinstance(value, (int, float)):
        return float(value)
    s = (value or '').strip()
    if not s:
        return None
    usd_tail = re.search(r'/\s*\$([\d,]+(?:\.\d+)?)', s)
    if usd_tail:
        try:
            return float(usd_tail.group(1).replace(',', ''))
        except (TypeError, ValueError):
            return None
    s = re.sub(r'\([^)]*\)', '', s)
    cleaned = re.sub(r'[^0-9.\-]', '', s)
    if cleaned in ('', '-', '.', '-.'):
        return None
    try:
        return float(cleaned)
    except (TypeError, ValueError):
        return None


def _order_money_components(value):
    """Return the leading currency amount plus USD tail for strings like
    "£315,250 / $434,635". Plain USD/numeric values return only usd."""
    if value is None or value == '':
        return None
    if isinstance(value, (int, float)):
        return {'prefix': '$', 'native': None, 'usd': float(value)}
    s = str(value).strip()
    if not s:
        return None
    usd = None
    usd_tail = re.search(r'/\s*\$([\d,]+(?:\.\d+)?)', s)
    if usd_tail:
        try:
            usd = float(usd_tail.group(1).replace(',', ''))
        except (TypeError, ValueError):
            usd = None
    leading = re.sub(r'\([^)]*\)', '', s)
    leading = re.sub(r'\s*/\s*\$[\d,]+(?:\.\d+)?\s*$', '', leading).strip()
    m = re.match(
        r'^(?P<prefix>A\$|US\$|\$|€|£|¥|CHF\s*|EUR\s+|USD\s+|AUD\s+|AUS\s+|GBP\s+|JPY\s+|YEN\s+)'
        r'\s*(?P<num>-?[\d,]+(?:\.\d+)?)',
        leading,
        re.IGNORECASE,
    )
    native = None
    prefix = '$'
    if m:
        raw_prefix = m.group('prefix').strip()
        prefix_map = {
            'A$': 'A$', 'AUD': 'A$', 'AUS': 'A$',
            '€': '€', 'EUR': '€',
            '£': '£', 'GBP': '£',
            '¥': '¥', 'JPY': '¥', 'YEN': '¥',
            'CHF': 'CHF ',
            'US$': '$', 'USD': '$', '$': '$',
        }
        prefix = prefix_map.get(raw_prefix.upper(), raw_prefix)
        try:
            native = float(m.group('num').replace(',', ''))
        except (TypeError, ValueError):
            native = None
    elif usd is None:
        usd = _parse_order_money(value)
    if usd is None and prefix == '$':
        usd = native
    return {'prefix': prefix, 'native': native, 'usd': usd}


def _format_prefixed_money(prefix, amount):
    if amount is None:
        return ''
    try:
        n = float(amount)
    except (TypeError, ValueError):
        return ''
    sign = '-' if n < 0 else ''
    return f"{sign}{prefix}{abs(round(n)):,.0f}"


def _watch_order_balance_display(record):
    price_raw = _row_get(record, 'price')
    purchase_parts = _order_money_components(price_raw)
    deposit_raw = _row_get(record, 'order_deposit')
    deposit_parts = _order_money_components(deposit_raw)
    deposit2_raw = _row_get(record, 'order_deposit_2')
    deposit2_parts = _order_money_components(deposit2_raw)

    purchase = purchase_parts['usd'] if purchase_parts else _watch_order_purchase_amount(record)
    deposit_value, pct = _watch_order_deposit_values(record)
    deposit = (deposit_parts['usd'] if deposit_parts and deposit_parts.get('usd') is not None
               else _parse_order_money(deposit_value))
    if pct not in (None, '') and purchase is not None:
        try:
            deposit = purchase * float(pct) / 100.0
        except (TypeError, ValueError):
            pass
    deposit2 = (deposit2_parts['usd'] if deposit2_parts and deposit2_parts.get('usd') is not None
                else _watch_order_deposit_2_amount(record))
    usd_balance = _watch_order_balance(purchase, deposit, deposit2)

    if (purchase_parts and purchase_parts.get('native') is not None
            and purchase_parts.get('prefix') != '$'
            and purchase_parts.get('usd') is not None):
        native_deposit = None
        if pct not in (None, ''):
            try:
                native_deposit = purchase_parts['native'] * float(pct) / 100.0
            except (TypeError, ValueError):
                native_deposit = None
        elif (deposit_parts and deposit_parts.get('prefix') == purchase_parts.get('prefix')
              and deposit_parts.get('native') is not None):
            native_deposit = deposit_parts['native']
        native_deposit = native_deposit or 0

        native_deposit2 = 0
        if (deposit2_parts and deposit2_parts.get('prefix') == purchase_parts.get('prefix')
                and deposit2_parts.get('native') is not None):
            native_deposit2 = deposit2_parts['native']

        native_balance = purchase_parts['native'] - native_deposit - native_deposit2
        native_text = _format_prefixed_money(purchase_parts['prefix'], native_balance)
        usd_text = _format_prefixed_money('$', usd_balance)
        if native_text and usd_text:
            return f"{native_text} / {usd_text}"

    return currency_filter(usd_balance)


def _parse_watch_order_deposit(value, purchase_price):
    s = (value or '').strip()
    m = re.fullmatch(r'\s*(-?\d+(?:\.\d+)?)\s*%\s*', s)
    if m and purchase_price is not None:
        try:
            pct = float(m.group(1))
            return purchase_price * pct / 100.0, pct
        except (TypeError, ValueError):
            return None, None
    pct = None
    pct_match = re.search(r'\((-?\d+(?:\.\d+)?)\s*%\)', s)
    if pct_match:
        try:
            pct = float(pct_match.group(1))
        except (TypeError, ValueError):
            pct = None
    deposit = _parse_order_money(s)
    if pct is not None and purchase_price is not None:
        deposit = purchase_price * pct / 100.0
    return deposit, pct


def _format_order_deposit_store(raw_value, pct, price_value, deposit_usd):
    """The string to persist for a deposit, preserving the native
    currency the user entered — the same dual "<native> / $<usd>" shape
    the price field stores. Percentage deposits are expanded into that
    pair from the price's native amount; explicit amounts keep whatever
    currency string the client already formatted on blur."""
    if isinstance(raw_value, (int, float)):
        return raw_value
    if pct is not None:
        price_parts = _order_money_components(price_value)
        if (price_parts and price_parts.get('native') is not None
                and price_parts.get('prefix') not in (None, '$')):
            native = price_parts['native'] * float(pct) / 100.0
            native_text = _format_prefixed_money(price_parts['prefix'], native)
            usd_text = _format_prefixed_money('$', deposit_usd)
            if native_text and usd_text:
                return f"{native_text} / {usd_text}"
        if deposit_usd is not None:
            return _format_prefixed_money('$', deposit_usd)
    s = ('' if raw_value is None else str(raw_value)).strip()
    return s or None


def _row_get(record, name):
    if not record:
        return None
    if hasattr(record, 'keys'):
        return record[name] if name in record.keys() else None
    return record.get(name)


def _watch_order_purchase_amount(record):
    price = _parse_order_money(_row_get(record, 'price'))
    if price is not None:
        return price
    order_purchase = _row_get(record, 'order_purchase_price')
    if order_purchase not in (None, ''):
        return order_purchase
    return None


def _infer_watch_order_deposit_percent(record):
    notes = _row_get(record, 'notes') or ''
    m = re.search(r'(\d+(?:\.\d+)?)\s*%\s*(?:down|deposit|paid)', notes, re.IGNORECASE)
    if not m:
        m = re.search(r'(?:down|deposit|paid)[^\d]{0,20}(\d+(?:\.\d+)?)\s*%', notes, re.IGNORECASE)
    if not m:
        return None
    try:
        return float(m.group(1))
    except (TypeError, ValueError):
        return None


def _watch_order_deposit_values(record):
    deposit = _row_get(record, 'order_deposit')
    pct = _row_get(record, 'order_deposit_percent')
    if deposit not in (None, ''):
        return deposit, pct
    purchase = _watch_order_purchase_amount(record)
    pct = pct if pct not in (None, '') else _infer_watch_order_deposit_percent(record)
    if pct is not None and purchase is not None:
        return float(purchase) * float(pct) / 100.0, pct
    return None, pct


def _watch_order_deposit_2_amount(record):
    return _parse_order_money(_row_get(record, 'order_deposit_2'))


def _watch_order_balance(purchase_price, deposit, deposit_2=None):
    if purchase_price is None:
        return None
    return purchase_price - (deposit or 0) - (deposit_2 or 0)


def _watch_order_lateness(expected, actual=None):
    if not expected:
        return ''
    try:
        expected_date = datetime.strptime(str(expected)[:10], '%Y-%m-%d').date()
    except (TypeError, ValueError):
        return ''
    actual_date = None
    if actual:
        try:
            actual_date = datetime.strptime(str(actual)[:10], '%Y-%m-%d').date()
        except (TypeError, ValueError):
            actual_date = None
    compare_date = actual_date or date.today()
    if compare_date <= expected_date:
        return 'On time'
    months = (
        (compare_date.year - expected_date.year) * 12
        + compare_date.month - expected_date.month
    )
    if compare_date.day < expected_date.day:
        months -= 1
    months = max(months, 0)
    if months == 0:
        days = (compare_date - expected_date).days
        return f"{days} day{'s' if days != 1 else ''} late"
    years, rem_months = divmod(months, 12)
    parts = []
    if years:
        parts.append(f"{years} yr{'s' if years != 1 else ''}")
    if rem_months:
        parts.append(f"{rem_months} mo")
    return ' '.join(parts) + ' late'


def _clean_service_date(value):
    raw = str(value or '').strip()
    if len(raw) >= 10 and re.match(r'^\d{4}-\d{2}-\d{2}$', raw[:10]):
        return raw[:10]
    return None


def _clean_service_text(value, max_len=None):
    text = str(value or '').strip()
    if max_len and len(text) > max_len:
        text = text[:max_len]
    return text or None


def _service_event_dict(row):
    if not row:
        return None
    return {
        'id': row['id'],
        'watch_id': row['watch_id'],
        'date_sent': row['date_sent'],
        'vendor': row['vendor'],
        'reason': row['reason'],
        'cost': row['cost'],
        'date_returned': row['date_returned'],
        'created_at': row['created_at'],
        'updated_at': row['updated_at'],
    }


def _watch_service_events(db, watch_id):
    rows = db.execute(
        "SELECT * FROM watch_service_events WHERE watch_id = ? "
        "ORDER BY COALESCE(NULLIF(date_sent, ''), NULLIF(date_returned, ''), created_at) DESC, "
        "created_at DESC",
        [watch_id],
    ).fetchall()
    return [_service_event_dict(row) for row in rows]


def _watch_service_payload(data):
    if not isinstance(data, dict):
        data = {}
    return {
        'date_sent': _clean_service_date(data.get('date_sent')),
        'vendor': _clean_service_text(data.get('vendor'), 200),
        'reason': _clean_service_text(data.get('reason'), 1000),
        'cost': _clean_service_text(data.get('cost'), 100),
        'date_returned': _clean_service_date(data.get('date_returned')),
    }


def _require_watch_for_service_event(db, record_id):
    row = db.execute("SELECT * FROM watches WHERE id = ?", [record_id]).fetchone()
    if row is None or not _user_can_see_row('watches', row):
        abort(404)
    return row


def _sync_watch_service_date_from_events(db, watch_id):
    row = db.execute(
        "SELECT MAX(date_returned) AS latest FROM watch_service_events "
        "WHERE watch_id = ? AND date_returned IS NOT NULL AND TRIM(date_returned) != ''",
        [watch_id],
    ).fetchone()
    latest = row['latest'] if row else None
    now = datetime.utcnow().isoformat()
    if latest:
        db.execute(
            "UPDATE watches SET service_date = ?, updated_at = ? WHERE id = ?",
            [latest, now, watch_id],
        )
    else:
        db.execute("UPDATE watches SET updated_at = ? WHERE id = ?",
                   [now, watch_id])
    return latest


def _apply_watch_order_form_fields(target, form):
    price_value = form.get('price') or form.get('order_purchase_price')
    purchase = _parse_order_money(price_value)
    raw_deposit = form.get('order_deposit')
    deposit_num, pct = _parse_watch_order_deposit(raw_deposit, purchase)
    # Persist the native-currency string (like price) so the deposit can
    # render as "€8,500 / $9,808" instead of collapsing to USD.
    target['order_deposit'] = _format_order_deposit_store(
        raw_deposit, pct, price_value, deposit_num)
    raw_deposit_2 = form.get('order_deposit_2')
    target['order_deposit_2'] = (
        (str(raw_deposit_2).strip() or None)
        if raw_deposit_2 not in (None, '') else None)
    target['order_deposit_percent'] = pct
    if pct is not None and purchase is not None:
        deposit_num = purchase * float(pct) / 100.0
    target['order_balance'] = _watch_order_balance(
        purchase, deposit_num, _parse_order_money(target['order_deposit_2']))


def _has_watch_order_data(record):
    def _field_value(name):
        return _row_get(record, name)

    return any(
        _field_value(k) not in (None, '')
        for k in ('order_purchase_price', 'order_deposit', 'order_deposit_2',
                  'expected_delivery_date')
    )


def _graduate_watch_order_if_owned(target, status_value):
    if str(status_value or '').strip().lower() != 'own':
        return
    if _has_watch_order_data(target) and not target.get('actual_delivery_date'):
        target['actual_delivery_date'] = date.today().isoformat()


def _apply_watch_actual_delivery_service_date(target, previous_actual=None):
    actual = _clean_service_date(_row_get(target, 'actual_delivery_date'))
    if not actual:
        return None
    if previous_actual is not None and actual == _clean_service_date(previous_actual):
        return None
    target['actual_delivery_date'] = actual
    target['service_date'] = actual
    return actual


def _update_watch_order_field(db, record_id, field_name, raw_value):
    row = db.execute(
        "SELECT price, order_purchase_price, order_deposit, order_deposit_2, "
        "order_deposit_percent "
        "FROM watches WHERE id = ?",
        [record_id],
    ).fetchone()
    if not row:
        return False
    purchase = _watch_order_purchase_amount(row)
    price_value = row['price']
    # Persisted strings preserve the native currency (like price); start
    # from whatever is already stored and only rewrite the field that
    # changed.
    deposit_store = row['order_deposit']
    deposit2_store = row['order_deposit_2']
    pct = row['order_deposit_percent']
    if field_name == 'order_purchase_price':
        purchase = _parse_order_money(raw_value)
        if pct is not None and purchase is not None:
            # Re-expand a percentage deposit against the new price.
            deposit_store = _format_order_deposit_store(
                None, pct, price_value, purchase * float(pct) / 100.0)
    elif field_name == 'order_deposit':
        deposit_num, pct = _parse_watch_order_deposit(raw_value, purchase)
        deposit_store = _format_order_deposit_store(
            raw_value, pct, price_value, deposit_num)
    elif field_name == 'order_deposit_2':
        deposit2_store = (
            (str(raw_value).strip() or None)
            if raw_value not in (None, '') else None)
    else:
        return False
    deposit_num = _parse_order_money(deposit_store)
    if pct is not None and purchase is not None:
        deposit_num = purchase * float(pct) / 100.0
    balance = _watch_order_balance(
        purchase, deposit_num, _parse_order_money(deposit2_store))
    now = datetime.utcnow().isoformat()
    db.execute(
        "UPDATE watches SET order_deposit = ?, order_deposit_2 = ?, "
        "order_deposit_percent = ?, order_balance = ?, updated_at = ? "
        "WHERE id = ?",
        [deposit_store, deposit2_store, pct, balance, now, record_id],
    )
    return True


def _refresh_watch_order_balance(db, record_id):
    row = db.execute(
        "SELECT price, order_purchase_price, order_deposit, order_deposit_2, "
        "order_deposit_percent "
        "FROM watches WHERE id = ?",
        [record_id],
    ).fetchone()
    if not row:
        return
    purchase = _watch_order_purchase_amount(row)
    pct = row['order_deposit_percent']
    deposit_store = row['order_deposit']
    if pct is not None and purchase is not None:
        # Percentage deposit re-expands against the (possibly new) price;
        # keep its native-currency string in step.
        deposit_num = purchase * float(pct) / 100.0
        deposit_store = _format_order_deposit_store(
            None, pct, row['price'], deposit_num)
    else:
        # Explicit-amount deposit: leave the stored native string intact,
        # only the balance needs recomputing.
        deposit_num = _parse_order_money(deposit_store)
    balance = _watch_order_balance(
        purchase,
        deposit_num,
        _parse_order_money(row['order_deposit_2']),
    )
    db.execute(
        "UPDATE watches SET order_deposit = ?, order_balance = ?, "
        "updated_at = ? WHERE id = ?",
        [deposit_store, balance, datetime.utcnow().isoformat(), record_id],
    )


def _graduate_watch_order_status(db, record_id):
    row = db.execute(
        "SELECT price, order_purchase_price, order_deposit, order_deposit_2, "
        "expected_delivery_date, actual_delivery_date "
        "FROM watches WHERE id = ?",
        [record_id],
    ).fetchone()
    if not row:
        return
    updates = []
    params = []
    stamped_actual = None
    if _has_watch_order_data(row) and not row['actual_delivery_date']:
        stamped_actual = date.today().isoformat()
        updates.append('actual_delivery_date = ?')
        params.append(stamped_actual)
        updates.append('service_date = ?')
        params.append(stamped_actual)
    if updates:
        updates.append('updated_at = ?')
        params.append(datetime.utcnow().isoformat())
        params.append(record_id)
        db.execute(f"UPDATE watches SET {', '.join(updates)} WHERE id = ?", params)
    return stamped_actual


@app.template_filter('currency')
def currency_filter(value):
    """Format as $1,234 by default. Already-formatted strings carrying
    a currency prefix round-trip unchanged so the user's chosen
    currency stays put. Empty -> empty, garbage -> str."""
    if value is None or value == '':
        return ''
    s = str(value).strip()
    # Round-trip already-formatted strings (the JS formatter writes
    # these on blur). Recognised by a currency prefix.
    if _CURRENCY_PREFIX_RE.match(s):
        return s
    try:
        return f"${float(s.replace(',', '').replace('$', '')):,.0f}"
    except (ValueError, TypeError):
        return s


@app.template_filter('card_number')
def card_number_filter(value):
    if value is None:
        return ''
    raw = str(value).strip()
    digits = re.sub(r'\D', '', raw)
    if not digits:
        return raw
    if len(digits) == 15 and digits.startswith(('34', '37')):
        return f"{digits[:4]} {digits[4:10]} {digits[10:]}"
    if len(digits) == 16:
        return ' '.join(digits[i:i + 4] for i in range(0, 16, 4))
    return raw


@app.template_filter('order_deposit')
def order_deposit_filter(value, percent=None):
    base = currency_filter(value)
    if percent in (None, ''):
        return base
    try:
        pct = float(percent)
    except (TypeError, ValueError):
        return base
    pct_text = f"{pct:g}%"
    return f"{base} ({pct_text})" if base else pct_text


@app.template_filter('watch_order_purchase')
def watch_order_purchase_filter(record):
    return currency_filter(_watch_order_purchase_amount(record))


@app.template_filter('watch_order_deposit')
def watch_order_deposit_filter(record):
    deposit, pct = _watch_order_deposit_values(record)
    return order_deposit_filter(deposit, pct)


@app.template_filter('watch_order_balance')
def watch_order_balance_filter(record):
    return _watch_order_balance_display(record)


@app.template_filter('delivery_lateness')
def delivery_lateness_filter(expected, actual=None):
    return _watch_order_lateness(expected, actual)


@app.template_filter('date_plus_years')
def date_plus_years_filter(value, years):
    try:
        d = datetime.strptime(str(value)[:10], '%Y-%m-%d').date()
        try:
            return d.replace(year=d.year + int(years)).isoformat()
        except ValueError:
            return d.replace(year=d.year + int(years), day=28).isoformat()
    except (TypeError, ValueError, AttributeError):
        return ''


@app.template_filter('lug_fmt')
def lug_fmt_filter(value):
    """Convert stored lug value to display string.
    >= 1000  →  '20/16'  (front/back in mm)
    < 1000   →  '20'     (single measurement)
    Already text like '20/16' → pass through.
    """
    if value is None or value == '' or value == '0' or value == 0:
        return ''
    # Already formatted (contains '/')
    if isinstance(value, str) and '/' in value:
        return value
    try:
        f = float(value)
        if f == 0:
            return ''
        if f >= 1000:
            int_part = int(f)
            dec_part = round(f - int_part, 6)
            s = str(int_part)
            front = s[:2]
            back_int = int(s[2:])
            back = f"{back_int + dec_part:g}" if dec_part else str(back_int)
            return f"{front}/{back}"
        else:
            return f"{f:g}"          # strips trailing zeros (17.5, 20, 14)
    except (ValueError, TypeError):
        return str(value)


@app.template_filter('fmt_int')
def fmt_int_filter(value):
    """Display a number as a plain integer with no decimals."""
    if value is None or value == '':
        return ''
    try:
        return f"{int(float(value)):,}"
    except (ValueError, TypeError):
        return str(value)


@app.template_filter('short_date')
def short_date_filter(value):
    """Render an ISO datetime or YYYY-MM-DD string as 'MMM D, YYYY'."""
    if not value:
        return ''
    s = str(value)
    try:
        # datetime.fromisoformat handles both 'YYYY-MM-DD' and full ISO.
        dt = datetime.fromisoformat(s.replace('Z', ''))
    except ValueError:
        return s
    return dt.strftime('%b %-d, %Y')


@app.template_filter('format_results')
def format_results_filter(value):
    """Turn the AI-generated Results markdown into clean HTML.

    - Lines starting with -, * or • become <li> items.
    - URLs become clickable <a target=_blank> links.
    - Dollar amounts like $1,234 or $12,345.67 are wrapped in <strong>.
    """
    if not value:
        return ''
    import html as _html
    from markupsafe import Markup

    # Decode any stray HTML entities the AI may have embedded (&#39; etc.)
    # before we re-escape during rendering.
    raw = _strip_markdown_wrappers(_html.unescape(str(value))).strip()
    # Claude's web_search tool injects <cite index="...">...</cite> markers
    # around quoted text. Strip the tags but keep the inner content.
    raw = re.sub(r'</?cite\b[^>]*>', '', raw, flags=re.IGNORECASE)
    lines = raw.split('\n')
    out = []
    in_list = False
    url_re = re.compile(r'https?://[^\s<>()]+')
    money_re = re.compile(r'(\$[0-9][0-9,]*(?:\.\d+)?)')
    # Trim stray punctuation the model tends to attach to URLs
    _url_trail = '.,;:)]}"\''

    def _short(url):
        u = url.rstrip(_url_trail)
        try:
            from urllib.parse import unquote, urlparse
            parsed = urlparse(u)
            host = parsed.hostname or u
            if host.startswith('www.'):
                host = host[4:]
            host_label = {
                'en.wikipedia.org': 'Wikipedia',
                'coinweek.com': 'CoinWeek',
                'ancientcoins.market': 'Ancient Coins Market',
                'thearchaeologist.org': 'The Archaeologist',
                'academia.edu': 'Academia',
            }.get(host, host)
            page = ''
            parts = [p for p in (parsed.path or '').split('/') if p]
            if parts:
                page = unquote(parts[-1])
                page = re.sub(r'\.[a-z0-9]{2,5}\Z', '', page, flags=re.I)
                page = re.sub(r'[-_]+', ' ', page)
                page = re.sub(r'\s+', ' ', page).strip().title()
            label = f'{host_label}: {page}' if page else host_label
            return label[:83].rstrip() + '...' if len(label) > 86 else label
        except Exception:
            return 'link'

    def _inline(text):
        # Replace URLs first (on raw text) with a placeholder that survives
        # HTML-escape, then substitute the final anchor markup.
        anchors = []
        def _cap(m):
            url = m.group(0).rstrip(_url_trail)
            anchors.append(url)
            return f'\x00A{len(anchors) - 1}\x00'
        text = url_re.sub(_cap, text)
        text = _html.escape(text)
        # Drop any em/en-dash + whitespace immediately before the placeholder —
        # the model tends to write "... : $X,XXX — <url>" which now reads
        # "... : $X,XXX" with a trailing pill.
        text = re.sub(r'\s*[\u2014\u2013-]\s*(\x00A\d+\x00)', r' \1', text)
        for i, url in enumerate(anchors):
            pill = (f'<a class="result-src" href="{_html.escape(url, quote=True)}" '
                    f'target="_blank" rel="noopener">{_html.escape(_short(url))}</a>')
            text = text.replace(f'\x00A{i}\x00', pill)
        # Markdown **bold** → <strong>, and *italic* → <em>. Run bold first
        # so its ** markers aren't eaten by the single-asterisk italic rule.
        text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
        # Tolerate the AI's lopsided bold attempts: `*Heading**` and
        # `**Heading*` show up periodically (especially as bullet headings)
        # and would otherwise render with a stray asterisk on each side.
        text = re.sub(r'(?<!\*)\*([^*\n]+?)\*\*(?!\*)', r'<strong>\1</strong>', text)
        text = re.sub(r'(?<!\*)\*\*([^*\n]+?)\*(?!\*)', r'<strong>\1</strong>', text)
        text = re.sub(r'(?<![\w*])\*(?!\s)([^*\n]+?)(?<!\s)\*(?![\w*])', r'<em>\1</em>', text)
        text = money_re.sub(r'<strong>\1</strong>', text)
        return text

    for raw in lines:
        line = raw.strip()
        if not line:
            if in_list:
                out.append('</ul>')
                in_list = False
            continue
        # A bullet is '-', '•', or '*' followed by whitespace. Bare
        # '*' at line start belongs to **bold** and must NOT be treated
        # as a bullet marker (otherwise the first asterisk gets eaten
        # and `**Style**` renders as `*Style**`).
        bullet = False
        content = line
        if len(line) >= 2 and line[0] in ('-', '•', '*') and line[1] in ' \t':
            bullet = True
            content = line[2:].strip()
        if bullet:
            if not in_list:
                out.append('<ul class="results-list">')
                in_list = True
            out.append(f'<li>{_inline(content)}</li>')
        else:
            if in_list:
                out.append('</ul>')
                in_list = False
            out.append(f'<p>{_inline(line)}</p>')
    if in_list:
        out.append('</ul>')
    return Markup(''.join(out))


@app.template_filter('from_json')
def from_json_filter(value):
    """Parse a JSON string in templates. Returns [] on null / invalid
    input so callers can iterate without guarding."""
    if not value:
        return []
    try:
        parsed = json.loads(value)
    except (TypeError, ValueError):
        return []
    return parsed if isinstance(parsed, list) else []


# ---------------------------------------------------------------------------
# Documents table helpers + endpoints
# ---------------------------------------------------------------------------
# Per-category map of doc-set name → legacy JSON cache column name. The
# set name appears in the route URL so categories with multiple
# independent doc-rows (persons: ids + health) can route through the same
# handlers. The normalized record_documents table is the source of truth.
# Categories with a single row use 'main' → 'documents' by convention.
DOC_SETS_BY_CATEGORY = {
    'properties': {'main': 'documents'},
    'watches':    {'main': 'documents'},
    'coins':      {'main': 'documents'},
    'banknotes':  {'main': 'documents'},
    'art':        {'main': 'documents'},
    'items':      {'main': 'documents'},
    'vehicles':   {'main': 'documents'},
    'pens':       {'main': 'documents'},
    'recordings': {'main': 'documents'},
    'rifles':     {'main': 'documents'},
    'audio':      {'main': 'documents'},
    'cameras':    {'main': 'documents'},
    'lenses':     {'main': 'documents'},
    'persons':    {'ids': 'id_documents', 'health': 'health_documents'},
}
DOCUMENTS_CATEGORIES = set(DOC_SETS_BY_CATEGORY.keys())


def _docs_col(category, doc_set):
    """Return the legacy JSON cache column for (category, doc_set), or
    None if the pair isn't enabled."""
    return DOC_SETS_BY_CATEGORY.get(category, {}).get(doc_set)


def _docs_cols_for(category):
    """All JSON columns this category uses for documents (zero or more)."""
    return list(DOC_SETS_BY_CATEGORY.get(category, {}).values())


def _category_for_table(table):
    return next(
        (cat for cat, info in CATEGORIES.items()
         if info.get('table') == table),
        None,
    )


def _docs_set_for_col(category, col):
    for doc_set, json_col in DOC_SETS_BY_CATEGORY.get(category, {}).items():
        if json_col == col:
            return doc_set
    return None


def _docs_parse_json(raw):
    try:
        docs = json.loads(raw or '[]')
    except (TypeError, ValueError):
        docs = []
    if not isinstance(docs, list):
        docs = []
    return _docs_normalize(docs)


def _docs_normalize(docs):
    out = []
    for entry in docs or []:
        if not isinstance(entry, dict):
            continue
        title = (entry.get('title') or '').strip()
        filename = (entry.get('filename') or '').strip()
        if not (title or filename):
            continue
        out.append({'title': title, 'filename': filename})
    return out


def _record_documents_for(db, category, record_id, doc_set):
    try:
        rows = db.execute(
            "SELECT title, filename FROM record_documents "
            "WHERE category = ? AND record_id = ? AND doc_set = ? "
            "ORDER BY position, created_at, id",
            [category, record_id, doc_set],
        ).fetchall()
    except sqlite3.OperationalError:
        return []
    return _docs_normalize([
        {'title': row['title'], 'filename': row['filename']}
        for row in rows
    ])


def _write_record_documents_table(db, category, record_id, doc_set, docs,
                                  now=None):
    clean = _docs_normalize(docs)
    now = now or datetime.utcnow().isoformat()
    try:
        db.execute(
            "DELETE FROM record_documents "
            "WHERE category = ? AND record_id = ? AND doc_set = ?",
            [category, record_id, doc_set],
        )
        for position, entry in enumerate(clean):
            db.execute(
                "INSERT INTO record_documents "
                "(id, category, record_id, doc_set, position, title, filename, "
                "created_at, updated_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    str(uuid.uuid4()), category, record_id, doc_set, position,
                    entry.get('title') or None,
                    entry.get('filename') or None,
                    now, now,
                ],
            )
    except sqlite3.OperationalError:
        pass
    return clean


def _backfill_record_documents_table(db):
    try:
        db.execute("SELECT 1 FROM record_documents LIMIT 1").fetchone()
    except sqlite3.OperationalError:
        return
    for category, sets in DOC_SETS_BY_CATEGORY.items():
        table = CATEGORIES[category]['table']
        try:
            cols = {
                r['name']
                for r in db.execute(f"PRAGMA table_info({table})").fetchall()
            }
        except sqlite3.OperationalError:
            continue
        present_sets = {
            doc_set: col for doc_set, col in sets.items() if col in cols
        }
        if not present_sets:
            continue
        select_cols = ', '.join(['id'] + list(present_sets.values()))
        rows = db.execute(f"SELECT {select_cols} FROM {table}").fetchall()
        for row in rows:
            for doc_set, col in present_sets.items():
                has_rows = db.execute(
                    "SELECT 1 FROM record_documents "
                    "WHERE category = ? AND record_id = ? AND doc_set = ? "
                    "LIMIT 1",
                    [category, row['id'], doc_set],
                ).fetchone()
                if has_rows:
                    continue
                docs = _docs_parse_json(row[col])
                if docs:
                    _write_record_documents_table(
                        db, category, row['id'], doc_set, docs,
                    )
    db.commit()


# Title keywords used to route a Sweep upload to the right doc-set on
# multi-set categories (persons). Match is whole-token (case-insensitive)
# — the label is split on whitespace + punctuation and a keyword has to
# equal one of the resulting tokens. Substring matching was too loose:
# 'id' was a substring of 'covid', so a vaccination card got routed to
# the IDs tab. Multi-word phrases need to be expressed as their
# component tokens (e.g. 'global entry' → 'global', 'entry').
SWEEP_DOC_SET_HINTS = {
    'persons': [
        ('health_documents', ('health', 'medic', 'medical', 'rx',
                              'prescription', 'doctor', 'eye', 'dental',
                              'insurance', 'covid', 'vaccine',
                              'vaccinated', 'vaccination', 'vax',
                              'fever')),
        ('id_documents',     ('id', 'license', 'passport', 'visa',
                              'global', 'entry', 'birth', 'social')),
    ],
}


_LABEL_TOKEN_RE = re.compile(r"[a-z0-9]+")


def _route_sweep_doc_set(category, label):
    """Pick the JSON column for a sweep-uploaded file. Single-set
    categories always return their lone column; multi-set ones run
    SWEEP_DOC_SET_HINTS against the file's parsed label (tokenized) and
    fall back to the first declared set if nothing matches."""
    cols = _docs_cols_for(category)
    if not cols:
        return 'documents'
    if len(cols) == 1:
        return cols[0]
    tokens = set(_LABEL_TOKEN_RE.findall((label or '').lower()))
    for col, keywords in SWEEP_DOC_SET_HINTS.get(category, []):
        if col not in cols:
            continue
        if any(k in tokens for k in keywords):
            return col
    return cols[0]


def _docs_load(db, table, record_id, col='documents'):
    """Read document entries for a record.

    The normalized record_documents table is the source of truth. The
    legacy JSON column remains as a compatibility cache and as a fallback
    for databases that have not been backfilled yet.
    """
    try:
        row = db.execute(
            f"SELECT {col} FROM {table} WHERE id = ?", [record_id]
        ).fetchone()
    except sqlite3.OperationalError:
        row = None
    if not row:
        return None
    category = _category_for_table(table)
    doc_set = _docs_set_for_col(category, col) if category else None
    if category and doc_set:
        table_docs = _record_documents_for(db, category, record_id, doc_set)
        if table_docs:
            return table_docs
    json_docs = _docs_parse_json(row[col])
    if category and doc_set and json_docs:
        _write_record_documents_table(db, category, record_id, doc_set,
                                      json_docs)
    return json_docs


def _docs_save(db, table, record_id, docs, col='documents'):
    _docs_update(db, table, record_id, docs, col)
    db.commit()


def _docs_update(db, table, record_id, docs, col='documents', now=None):
    """Update documents without committing.

    record_documents is the sole stored representation. The legacy JSON
    columns are no longer written; we still bump the parent row's
    updated_at so incremental sync/export notices the change. Used when
    multiple document sets must change atomically; callers commit once
    after every set update succeeds.
    """
    now = now or datetime.utcnow().isoformat()
    category = _category_for_table(table)
    doc_set = _docs_set_for_col(category, col) if category else None
    clean = _docs_normalize(docs)
    if category and doc_set:
        clean = _write_record_documents_table(
            get_db() if db is None else db, category, record_id, doc_set,
            clean, now=now,
        )
        db.execute(
            f"UPDATE {table} SET updated_at = ? WHERE id = ?",
            [now, record_id],
        )
    else:
        # Unknown doc_set has no normalized home — keep the JSON column
        # so nothing is silently dropped. (No current caller hits this.)
        db.execute(
            f"UPDATE {table} SET {col} = ?, updated_at = ? WHERE id = ?",
            [json.dumps(clean), now, record_id],
        )


def _auto_title_from_basename(category, record_id, basename):
    """Compute a sensible default title for a doc tile from its
    uploaded filename. Drops the extension, then strips a leading
    '<record-ident> — ' prefix when it matches the record's
    EXPORT_LAYOUT ident — that prefix duplicates information already
    attached to the record (e.g. a 'Rec Center — Image.jpg' dropped
    on the Rec Center property becomes 'Image', not the full
    redundant string). Falls back to the bare basename if the
    EXPORT_LAYOUT lookup fails for any reason."""
    base = os.path.splitext(os.path.basename(basename or ''))[0].strip()
    if not base:
        return ''
    plan = (globals().get('EXPORT_LAYOUT') or {}).get(category) or {}
    ident_fn = plan.get('ident')
    if not ident_fn:
        return base
    try:
        db = get_db()
        row = db.execute(
            f"SELECT * FROM {CATEGORIES[category]['table']} WHERE id = ?",
            [record_id]
        ).fetchone()
        if not row:
            return base
        ident = (ident_fn(row) or '').strip()
        if ident:
            prefix = f'{ident} — '
            if base.startswith(prefix):
                base = base[len(prefix):].strip() or base
    except Exception:
        pass
    return base


def _docs_guard(category, record_id, doc_set):
    """Common pre-flight. Returns (err_response, col): on error
    err_response is a Flask error tuple and col is None; on success
    err_response is None and col is the JSON column to operate on."""
    col = _docs_col(category, doc_set)
    if not col:
        return (jsonify({'error': 'Unknown documents set'}), 400), None
    table = CATEGORIES[category]['table']
    db = get_db()
    row = db.execute(
        f"SELECT * FROM {table} WHERE id = ?", [record_id]
    ).fetchone()
    if not row:
        return (jsonify({'error': 'Record not found'}), 404), None
    if not _user_can_see_row(category, row):
        return (jsonify({'error': 'Forbidden'}), 403), None
    return None, col


@app.route('/<category>/<record_id>/documents/<doc_set>/append', methods=['POST'])
def documents_append(category, record_id, doc_set):
    """Append a new document. Accepts multipart with optional `file`
    and optional `title`. At least one must be present."""
    err, col = _docs_guard(category, record_id, doc_set)
    if err: return err
    db = get_db()
    table = CATEGORIES[category]['table']
    docs = _docs_load(db, table, record_id, col) or []
    title = (request.form.get('title') or '').strip()
    upload = request.files.get('file') or request.files.get('image')
    filename = ''
    original_basename = ''
    if upload and upload.filename:
        if not allowed_file(upload.filename):
            return jsonify({'error': 'File type not allowed'}), 400
        original_basename = upload.filename
        filename = save_upload(upload) or ''
        if not filename:
            return jsonify({'error': 'Upload failed'}), 500
    if not title and not filename:
        return jsonify({'error': 'title or file required'}), 400
    # Default title to the dropped file's basename (sans extension) so
    # newly-added tiles render with something readable instead of just
    # the file preview. _auto_title_from_basename also strips a
    # redundant '<record-ident> — ' prefix when the dropped file came
    # from a Files export of this same record. The user can rename
    # via the title input.
    if not title and original_basename:
        title = _auto_title_from_basename(category, record_id, original_basename)
    docs.append({'title': title, 'filename': filename})
    _docs_save(db, table, record_id, docs, col)
    return jsonify({
        'ok': True, 'idx': len(docs) - 1,
        'title': title, 'filename': filename,
        'url': url_for('uploaded_file', filename=filename) if filename else '',
    })


@app.route('/<category>/<record_id>/documents/<doc_set>/<int:idx>/title', methods=['POST'])
def documents_set_title(category, record_id, doc_set, idx):
    err, col = _docs_guard(category, record_id, doc_set)
    if err: return err
    db = get_db()
    table = CATEGORIES[category]['table']
    docs = _docs_load(db, table, record_id, col) or []
    if idx < 0 or idx >= len(docs):
        return jsonify({'error': 'Index out of range'}), 400
    payload = request.get_json(silent=True) or {}
    docs[idx]['title'] = (payload.get('title') or '').strip()
    _docs_save(db, table, record_id, docs, col)
    return jsonify({'ok': True})


@app.route('/<category>/<record_id>/documents/<doc_set>/<int:idx>/file', methods=['POST'])
def documents_set_file(category, record_id, doc_set, idx):
    """Replace the file on an existing document tile."""
    err, col = _docs_guard(category, record_id, doc_set)
    if err: return err
    db = get_db()
    table = CATEGORIES[category]['table']
    docs = _docs_load(db, table, record_id, col) or []
    if idx < 0 or idx >= len(docs):
        return jsonify({'error': 'Index out of range'}), 400
    upload = request.files.get('file') or request.files.get('image')
    if not upload or not upload.filename:
        return jsonify({'error': 'No file'}), 400
    if not allowed_file(upload.filename):
        return jsonify({'error': 'File type not allowed'}), 400
    original_basename = upload.filename
    filename = save_upload(upload)
    if not filename:
        return jsonify({'error': 'Upload failed'}), 500
    docs[idx]['filename'] = filename
    # Backfill title from the new file's basename only if this tile is
    # currently untitled — leave deliberate user titles alone. Strips
    # the redundant '<record-ident> — ' prefix the same way as append.
    if not (docs[idx].get('title') or '').strip() and original_basename:
        docs[idx]['title'] = _auto_title_from_basename(category, record_id, original_basename)
    _docs_save(db, table, record_id, docs, col)
    return jsonify({
        'ok': True, 'filename': filename, 'title': docs[idx].get('title', ''),
        'url': url_for('uploaded_file', filename=filename),
    })


@app.route('/<category>/<record_id>/documents/<doc_set>/<int:idx>/delete', methods=['POST'])
def documents_delete(category, record_id, doc_set, idx):
    """Remove a document tile and the underlying file. The row's
    always-present trailing '+ Add document' slot is the empty drop
    zone; we don't preserve a bin in the deleted slot's place. (Special
    license/health-card cells live in dedicated columns handled by
    delete_file_field.)"""
    err, col = _docs_guard(category, record_id, doc_set)
    if err: return err
    db = get_db()
    table = CATEGORIES[category]['table']
    docs = _docs_load(db, table, record_id, col) or []
    if idx < 0 or idx >= len(docs):
        return jsonify({'error': 'Index out of range'}), 400
    removed = docs.pop(idx)
    # Tombstone the deleted file so the next incremental syncDown can
    # mirror the deletion locally. Read the row before the save so we
    # can compute the export-shaped path.
    if isinstance(removed, dict):
        rm_filename = (removed.get('filename') or '').strip()
        rm_title = (removed.get('title') or '').strip()
        if rm_filename:
            row = db.execute(
                f"SELECT * FROM {table} WHERE id = ?", [record_id]
            ).fetchone()
            if row:
                _record_tombstone(db, category, row, rm_title, rm_filename)
    _docs_save(db, table, record_id, docs, col)
    if isinstance(removed, dict):
        _unlink_upload(removed.get('filename') or '')
    return jsonify({'ok': True, 'count': len(docs)})


@app.route('/<category>/<record_id>/documents/<doc_set>/<int:idx>/move-to/<dst_set>', methods=['POST'])
def documents_move(category, record_id, doc_set, idx, dst_set):
    """Move a document entry from one doc-set to another within the
    same record. Used by the UI when the user drags a tile from one
    persons row (e.g. ids) onto the other (e.g. health). The entry is
    appended to the end of the destination set so it lands in a
    visible position; the source set is reindexed by the natural pop.
    Returns counts for both sets so the caller can refresh.

    Single-set categories never invoke this — DOC_SETS_BY_CATEGORY
    only declares one column for them, and _docs_guard rejects
    unknown set names. Same-set moves are also rejected (use the
    /reorder endpoint instead)."""
    err, src_col = _docs_guard(category, record_id, doc_set)
    if err: return err
    dst_col = _docs_col(category, dst_set)
    if not dst_col:
        return jsonify({'error': 'Unknown destination set'}), 400
    if dst_col == src_col:
        return jsonify({'error': 'Use reorder for same-set moves'}), 400
    db = get_db()
    table = CATEGORIES[category]['table']
    src_docs = _docs_load(db, table, record_id, src_col) or []
    if idx < 0 or idx >= len(src_docs):
        return jsonify({'error': 'Index out of range'}), 400
    dst_docs = _docs_load(db, table, record_id, dst_col) or []
    entry = src_docs.pop(idx)
    dst_docs.append(entry)
    now = datetime.utcnow().isoformat()
    _docs_update(db, table, record_id, src_docs, src_col, now)
    _docs_update(db, table, record_id, dst_docs, dst_col, now)
    db.commit()
    return jsonify({
        'ok': True,
        'src_count': len(src_docs),
        'dst_count': len(dst_docs),
    })


@app.route('/<category>/<record_id>/documents/<doc_set>/reorder', methods=['POST'])
def documents_reorder(category, record_id, doc_set):
    """Reorder the documents JSON array. Body: {"order": [old_idx, ...]}
    must be a permutation of 0..N-1; the new array is built by reading
    the old one in the order given."""
    err, col = _docs_guard(category, record_id, doc_set)
    if err: return err
    db = get_db()
    table = CATEGORIES[category]['table']
    docs = _docs_load(db, table, record_id, col) or []
    payload = request.get_json(silent=True) or {}
    order = payload.get('order')
    if (not isinstance(order, list)
            or len(order) != len(docs)
            or sorted(order) != list(range(len(docs)))):
        return jsonify({'error': 'order must be a permutation of 0..N-1'}), 400
    docs = [docs[i] for i in order]
    _docs_save(db, table, record_id, docs, col)
    return jsonify({'ok': True, 'count': len(docs)})


@app.template_filter('is_image')
def is_image_filter(filename):
    if not filename:
        return False
    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    return ext in ('png', 'jpg', 'jpeg', 'gif', 'webp', 'tif', 'tiff')


def _asset_v(rel_path):
    """Cache-bust token for a static asset — its mtime as an int. Lets
    base.html hand `?v=…` to <script>/<link> URLs so a fresh deploy
    invalidates the browser's 12-hour static-asset cache the moment
    the underlying file changes (and stays stable across requests
    when nothing has)."""
    try:
        return int(os.path.getmtime(
            os.path.join(app.static_folder or 'static', rel_path)
        ))
    except OSError:
        return 0


@app.context_processor
def inject_globals():
    return {
        'CATEGORIES': CATEGORIES,
        'now': datetime.utcnow(),
        'current_user': g.get('current_user'),
        'allowed_cats': g.get('allowed_cats', set()),
        'asset_v': _asset_v,
        'is_hidden_field': lambda cat, field: field in HIDE_FIELDS.get(cat, set()),
        'count_visible': lambda cat, names: sum(
            1 for n in names if n not in HIDE_FIELDS.get(cat, set())),
        'is_tenant': TENANT_CATEGORIES is not None,
        'person_medication_slots': PERSON_MEDICATION_SLOTS,
    }


# ---------------------------------------------------------------------------
# Multi-user authorization
#
# Cloudflare Access authenticates the visitor at the edge and forwards
# their verified email in `Cf-Access-Authenticated-User-Email`. The app
# trusts that header (production-only — locally we fall back to an env
# var so dev still works).
#
# The `users` table maps each email to a set of allowed category slugs.
# Owner role gets categories='*' which expands to every category. Anyone
# whose email isn't in the table gets 403.
# ---------------------------------------------------------------------------

OWNER_EMAIL = (os.environ.get('STUFFAPP_OWNER_EMAIL') or
               'MarkArmenante@gmail.com').lower()
OWNER_DISPLAY_NAME = (os.environ.get('STUFFAPP_OWNER_DISPLAY_NAME') or
                      'Mark Armenante')
OWNER_CATEGORIES = os.environ.get('STUFFAPP_OWNER_CATEGORIES') or '*'

# Tenant scope — when a deployment restricts the owner's categories,
# this is the canonical "what does this tenant deal with" set. Used to
# constrain UI surfaces (e.g. property pills) so visiting users with
# broader access still see only the tenant's slice.
TENANT_CATEGORIES = (
    None if OWNER_CATEGORIES.strip() in ('*', '')
    else {c.strip() for c in OWNER_CATEGORIES.split(',') if c.strip()}
)


def _merge_banknote_catalog_numbers(db):
    """All catalogue references live in one field: fold the legacy
    other_catalog column into pick_number ("P-11a, TBB B301") and blank
    the source. Idempotent — a merged row has an empty other_catalog.
    Skips the append when the pick field already contains the other
    text (Check historically wrote overlapping values)."""
    try:
        rows = db.execute(
            "SELECT id, pick_number, other_catalog FROM banknotes "
            "WHERE other_catalog IS NOT NULL AND TRIM(other_catalog) != ''"
        ).fetchall()
    except sqlite3.OperationalError:
        return
    now = datetime.utcnow().isoformat()
    for row in rows:
        pick = (row['pick_number'] or '').strip()
        other = (row['other_catalog'] or '').strip()
        if not pick:
            merged = other
        elif other.lower() in pick.lower():
            merged = pick
        else:
            merged = f'{pick}, {other}'
        db.execute(
            "UPDATE banknotes SET pick_number = ?, other_catalog = '', "
            "updated_at = ? WHERE id = ?", (merged, now, row['id']))


def _ensure_owner_user(db):
    """Idempotent: make sure the owner email exists. On a fresh DB,
    seed the configured display_name and categories. On an existing
    DB, only re-assert role='owner' so an admin's manual edits to
    display_name or categories aren't clobbered on every boot."""
    db.execute(
        "INSERT INTO users (id, email, display_name, role, categories) "
        "VALUES (?, ?, ?, 'owner', ?) "
        "ON CONFLICT(email) DO UPDATE SET role='owner'",
        [str(uuid.uuid4()), OWNER_EMAIL, OWNER_DISPLAY_NAME, OWNER_CATEGORIES]
    )


def _resolve_user_email():
    """Email of the currently authenticated visitor. CF Access on prod;
    STUFFAPP_DEV_USER env var locally so per-user testing still works."""
    e = (request.headers.get('Cf-Access-Authenticated-User-Email') or
         os.environ.get('STUFFAPP_DEV_USER') or OWNER_EMAIL)
    return (e or '').strip().lower()


def _expand_categories(raw, role):
    """Resolve a user's category list. '*' (or empty for owner role)
    means all categories; otherwise the explicit comma-separated
    list. Owner role no longer auto-bypasses an explicit list — that
    way a third-party deployment can be owner-role-but-restricted
    without forking the visibility model."""
    s = (raw or '').strip()
    if s == '*' or (role == 'owner' and not s):
        return set(CATEGORIES.keys())
    return {c.strip() for c in s.split(',') if c.strip() in CATEGORIES}


# Property name aliases — different ways the same physical property
# is recorded across categories (Carp / Carpinteria, Truckee / Martis
# Camp / Martis). Filtering by any one form matches all of them.
# Keys + values are lowercase. Adding a new alias here is the only
# change needed to make the at-property filter and the back-pill
# lookup recognise it.
PROPERTY_ALIASES = {
    'carpinteria': ['carpinteria', 'carp', 'montecito'],
    'carp':        ['carpinteria', 'carp', 'montecito'],
    'truckee':     ['truckee', 'martis camp', 'martis'],
    'martis camp': ['truckee', 'martis camp', 'martis'],
    'martis':      ['truckee', 'martis camp', 'martis'],
    # 42 Hotaling absorbed the old "SF" / "San Francisco" tag set after
    # the 3450 Washington property was retired (kept as Sold record).
    '42 hotaling':   ['42 hotaling', 'sf', 'san francisco'],
    # Ghent campus — strip the legacy "Ghent: " prefix from each
    # building. Bidirectional so a stray "Ghent: Pond House" item still
    # surfaces under the Pond House pill until the boot migration
    # rewrites it.
    'pond house':    ['pond house', 'ghent: pond house'],
    'glass house':   ['glass house', 'ghent: glass house'],
    'harlemville':   ['harlemville', 'ghent: harlemville'],
    'party barn':    ['party barn', 'ghent: party barn'],
    'rec center':    ['rec center', 'ghent: rec center',
                      'ghent: rec center/arena', 'rec center/arena'],
    'rigor hill':    ['rigor hill', 'ghent: rigor hill'],
    '223 rigor':     ['223 rigor', 'ghent: 223 rigor'],
    # NYC: prefix strip
    '1 white st':       ['1 white st', 'nyc: 1 white st'],
    '357 w broadway':   ['357 w broadway', 'nyc: 357 w broadway'],
    '67 engert':        ['67 engert', 'nyc: 67 engert'],
    # The "NYC" property record was previously named "56 Leonard"
    'nyc':           ['nyc', '56 leonard', 'nyc: 56 leonard'],
    # SF: prefix strip
    '432 jackson':   ['432 jackson', 'sf: 432 jackson'],
    # Address typo correction
    '3956 fifth':    ['3956 fifth', '4956 fifth'],
}


def _property_alias_group(name):
    """Return every equivalent form for a property name (lowercased,
    trimmed). Falls back to a single-element list with the input
    when the name has no known aliases."""
    n = (name or '').strip().lower()
    if not n:
        return []
    return PROPERTY_ALIASES.get(n, [n])


# Per-category mapping of which column stores the owning Property's
# name. Categories not listed here can't be filtered "at <property>"
# (e.g. credit cards, persons). Used by the Property detail's pill
# row and by /<cat>?at=<name> list filtering.
CATEGORY_PROPERTY_FIELD = {
    'watches':    'property',
    'coins':      'property_name',
    'cameras':    'property',
    'lenses':     'property',
    'pens':       'property',
    'art':        'property',
    'items':      'property',
    'vehicles':   'property',
    'recordings': 'property',
    'audio':      'property',
    'rifles':     'property',
}


# Row-level filtering. Per category, which fields can a member be
# restricted on, and where does the value list for each field come
# from in VALUE_LISTS. Add an entry here to enable filtering on a
# new field — UI + enforcement pick it up automatically.
ROW_FILTER_FIELDS = {
    'watches':      ['owner'],
    'coins':        ['owner'],
    'cameras':      ['owner'],
    'lenses':       ['owner'],
    'pens':         ['owner'],
    'art':          ['owner'],
    'items':        ['owner'],
    'vehicles':     ['owner'],
    'recordings':   ['owner'],
    'audio':        ['owner'],
    'rifles':       ['owner'],
    'credit_cards': ['owner'],
    'properties':   ['owner'],
    'persons':      ['owner'],
}
# field name → VALUE_LISTS key for picking allowed values in the UI.
ROW_FILTER_VALUE_LISTS = {
    'owner': 'owner',
}


def _parse_row_filters_json(raw):
    """Decode a users.row_filters JSON blob; tolerant of NULL / bad
    input (returns {})."""
    if not raw:
        return {}
    try:
        d = json.loads(raw) if isinstance(raw, str) else raw
        return d if isinstance(d, dict) else {}
    except (ValueError, TypeError):
        return {}


def _user_row_filters(user):
    """Effective per-category row filters for a user dict. Owners have
    no row restrictions; everyone else gets whatever JSON they have."""
    if not user or user.get('role') == 'owner':
        return {}
    return _parse_row_filters_json(user.get('row_filters'))


def _row_filter_for_category(user, category):
    """Return {field: [allowed_values, …]} for one category, or {}."""
    f = _user_row_filters(user).get(category)
    return f if isinstance(f, dict) else {}


def _user_can_see_row(category, row):
    """Does the current user pass the row filter for this record? True
    when there's no filter or the row's filtered fields are all in the
    allowed lists."""
    user = g.get('current_user')
    filt = _row_filter_for_category(user, category)
    if not filt:
        return True
    for field, allowed in filt.items():
        if not allowed:
            continue
        try:
            v = row[field] if hasattr(row, 'keys') and field in row.keys() else None
        except (KeyError, IndexError):
            v = None
        if v not in allowed:
            return False
    return True


def _apply_row_filter_clauses(category, wheres, params):
    """Mutate a build_search_query-style (wheres, params) pair to
    add `(<field> IN (?, ?...))` clauses for each filtered field on
    the current user."""
    user = g.get('current_user')
    filt = _row_filter_for_category(user, category)
    for field, allowed in filt.items():
        if not allowed:
            continue
        ph = ','.join(['?' for _ in allowed])
        wheres.append(f'({field} IN ({ph}))')
        params.extend(allowed)


def _upload_visible_to_current_user(filename):
    """Return True when an upload filename belongs to a visible row.

    Upload URLs are intentionally opaque UUID-ish names, but they still
    need the same category + row-filter privacy model as the list/detail
    pages. This checks fixed file columns, JSON document lists, and
    property topic images before serving `/uploads/...` or thumbnails.
    """
    name = (filename or '').strip()
    if not name or '/' in name or '\\' in name or name.startswith('.'):
        return False
    if not g.get('current_user'):
        return False
    allowed = g.get('allowed_cats') or set()
    if not allowed:
        return False
    db = get_db()

    for cat, info in CATEGORIES.items():
        if cat not in allowed:
            continue
        table = info['table']
        try:
            cols = {
                r['name']
                for r in db.execute(f"PRAGMA table_info({table})").fetchall()
            }
        except sqlite3.OperationalError:
            continue

        file_cols = [
            f['name'] for f in FIELDS.get(cat, [])
            if f.get('type') == 'file' and f['name'] in cols
        ]
        if file_cols:
            wheres = ['(' + ' OR '.join(f"{c} = ?" for c in file_cols) + ')']
            params = [name] * len(file_cols)
            _apply_row_filter_clauses(cat, wheres, params)
            where_clause = ' AND '.join(wheres)
            try:
                row = db.execute(
                    f"SELECT id FROM {table} WHERE {where_clause} LIMIT 1",
                    params,
                ).fetchone()
            except sqlite3.OperationalError:
                row = None
            if row:
                return True

        try:
            doc_refs = db.execute(
                "SELECT record_id FROM record_documents "
                "WHERE category = ? AND filename = ?",
                [cat, name],
            ).fetchall()
        except sqlite3.OperationalError:
            doc_refs = []
        for ref in doc_refs:
            try:
                row = db.execute(
                    f"SELECT * FROM {table} WHERE id = ?",
                    [ref['record_id']],
                ).fetchone()
            except sqlite3.OperationalError:
                row = None
            if row and _user_can_see_row(cat, row):
                return True

        doc_cols = [c for c in _docs_cols_for(cat) if c in cols]
        if doc_cols:
            wheres = [
                '(' + ' OR '.join(f"{c} LIKE ?" for c in doc_cols) + ')'
            ]
            params = [f'%{name}%'] * len(doc_cols)
            _apply_row_filter_clauses(cat, wheres, params)
            where_clause = ' AND '.join(wheres)
            try:
                rows = db.execute(
                    f"SELECT {', '.join(doc_cols)} FROM {table} "
                    f"WHERE {where_clause}",
                    params,
                ).fetchall()
            except sqlite3.OperationalError:
                rows = []
            for row in rows:
                for col in doc_cols:
                    try:
                        docs = json.loads(row[col] or '[]')
                    except (TypeError, ValueError):
                        continue
                    if not isinstance(docs, list):
                        continue
                    for d in docs:
                        if isinstance(d, dict) and \
                                (d.get('filename') or '').strip() == name:
                            return True

    # Property topic images live in topics.image rather than the regular
    # category file fields. They inherit visibility from the parent
    # property row.
    if 'properties' in allowed:
        try:
            rows = db.execute(
                "SELECT p.* FROM topics t "
                "JOIN properties p ON p.id = t.property_id "
                "WHERE t.image = ?",
                [name],
            ).fetchall()
        except sqlite3.OperationalError:
            rows = []
        for row in rows:
            if _user_can_see_row('properties', row):
                return True

    return False


# Endpoints that everyone gets to hit regardless of category access.
# Uploaded files and generated thumbnails are NOT exempt: the route
# handlers enforce category + row-filter access before serving bytes.
_AUTH_EXEMPT_ENDPOINTS = {'static'}


@app.before_request
def _load_user_and_authorize():
    """Identify the user, attach to flask.g, and 403 if they don't have
    access to whichever category the URL targets. Owner-only routes
    check g.current_user.role themselves."""
    if request.endpoint in _AUTH_EXEMPT_ENDPOINTS:
        return
    db = get_db()
    email = _resolve_user_email()
    g.user_email = email
    row = db.execute(
        "SELECT * FROM users WHERE LOWER(email) = ?", [email]
    ).fetchone()
    if not row:
        # Fail closed: unknown email → 403, no app access.
        g.current_user = None
        g.allowed_cats = set()
        return Response(
            f"<h1>403 Forbidden</h1>"
            f"<p>Your email ({email}) isn't registered with this app. "
            f"Ask the owner to grant access.</p>",
            status=403, mimetype='text/html'
        )
    g.current_user = dict(row)
    g.allowed_cats = _expand_categories(row['categories'], row['role'])
    # Tenant clamp — even a user with '*' access (e.g. a cross-tenant
    # admin) sees only the tenant's slice on this deployment, so the
    # nav, list views, and pills match what the tenant owner sees.
    if TENANT_CATEGORIES is not None:
        g.allowed_cats = g.allowed_cats & TENANT_CATEGORIES
    # Anything under /admin is owner-only.
    if (request.path or '').startswith('/admin') and \
            g.current_user['role'] != 'owner':
        abort(403)
    # Path-based category gate. Catches both /<category>/... routes and
    # category-prefixed routes like /coins/<id>/lookup-specs.
    if g.current_user['role'] != 'owner':
        first = (request.path or '/').strip('/').split('/', 1)[0]
        if first in CATEGORIES and first not in g.allowed_cats:
            abort(403)


_SAFE_METHODS = {'GET', 'HEAD', 'OPTIONS', 'TRACE'}


@app.before_request
def _reject_cross_site_writes():
    """CSRF guard. Auth here is ambient (a cookie set by Cloudflare
    Access), so a state-changing request forged by another site would
    otherwise ride the owner's session. Block any write whose Origin is a
    different host, or that the browser tags Sec-Fetch-Site: cross-site.

    Deliberately lenient on absent headers: server-to-server calls, the
    iOS app, and curl send neither Origin nor Sec-Fetch-Site, and must
    keep working — only a *present, mismatched* signal is treated as an
    attack, so this can't lock out a legitimate client."""
    if request.method in _SAFE_METHODS:
        return
    origin = request.headers.get('Origin')
    if origin:
        from urllib.parse import urlparse
        if urlparse(origin).netloc and urlparse(origin).netloc != request.host:
            abort(403, description='Cross-site request blocked.')
        return
    if request.headers.get('Sec-Fetch-Site') == 'cross-site':
        abort(403, description='Cross-site request blocked.')


def require_owner():
    """Call inside an owner-only route to 403 non-owners."""
    if not g.get('current_user') or g.current_user.get('role') != 'owner':
        abort(403)


# ---------------------------------------------------------------------------
# Missing-rows import endpoints (coins + watches). Safe to re-run.
# ---------------------------------------------------------------------------

# Second factor on the admin/import/backup routes, on top of the CF Access
# auth. Set STUFFAPP_ADMIN_SECRET in the environment to rotate it away from
# this in-source default (which should be treated as already-compromised).
IMPORT_MISSING_SECRET = os.environ.get(
    'STUFFAPP_ADMIN_SECRET') or 'stuffapp-bulk-import-2026'


# One-shot maintenance endpoints that run a single UPDATE and report the
# row count. Each was its own near-identical route; they're registered
# from this table instead. Columns: (rule, endpoint, sql, use_now,
# total_table). use_now binds datetime.utcnow().isoformat() as the sole
# `?` param (for the updated_at column); total_table adds a
# COUNT(*)-of-that-table 'total' to the response. SQL is verbatim from
# the original routes — a change here changes what the endpoint does.
_BULK_UPDATE_ROUTES = (
    ('/admin/pens-owner-mark', 'pens_owner_mark',
     "UPDATE pens SET owner='Mark'", False, 'pens'),
    ('/admin/coins-owner-mark', 'coins_owner_mark',
     "UPDATE coins SET owner='Mark', updated_at=? "
     "WHERE owner IS NULL OR TRIM(owner) = '' OR owner != 'Mark'", True, 'coins'),
    ('/admin/audio-owner-ym', 'audio_owner_ym',
     "UPDATE audio SET owner='YM', updated_at=? "
     "WHERE owner IS NULL OR TRIM(owner) = '' OR owner != 'YM'", True, 'audio'),
    ('/admin/cameras-owner-mark', 'cameras_owner_mark',
     "UPDATE cameras SET owner='Mark', updated_at=? "
     "WHERE owner IS NULL OR TRIM(owner) = '' OR owner != 'Mark'", True, 'cameras'),
    ('/admin/lenses-owner-mark', 'lenses_owner_mark',
     "UPDATE lenses SET owner='Mark', updated_at=? "
     "WHERE owner IS NULL OR TRIM(owner) = '' OR owner != 'Mark'", True, 'lenses'),
    ('/admin/vehicles-default-sold', 'vehicles_default_sold',
     "UPDATE vehicles SET status='Sold' WHERE status IS NULL OR status=''",
     False, 'vehicles'),
    ('/admin/backfill-property-status-own', 'backfill_property_status_own',
     "UPDATE properties SET status = 'Own' "
     "WHERE status IS NULL OR TRIM(status) = ''", False, None),
    ('/admin/set-all-recording-status-own', 'set_all_recording_status_own',
     "UPDATE recordings SET status = 'Own'", False, None),
    ('/admin/rename-recording-type-lp-to-vinyl', 'rename_recording_type_lp_to_vinyl',
     "UPDATE recordings SET type = 'Vinyl' WHERE type = 'LP'", False, None),
    ('/admin/clear-recording-numeric-notes', 'clear_recording_numeric_notes',
     "UPDATE recordings SET notes = NULL "
     "WHERE notes IS NOT NULL "
     "  AND TRIM(notes) NOT LIKE '% %' "
     "  AND LENGTH(TRIM(notes)) < 12 "
     "  AND CAST(TRIM(notes) AS REAL) >= 0 "
     "  AND TRIM(notes) GLOB '[0-9]*'", False, None),
    ('/admin/backfill-camera-status-own', 'backfill_camera_status_own',
     "UPDATE cameras SET status = 'Own' "
     "WHERE status IS NULL OR TRIM(status) = ''", False, None),
    ('/admin/backfill-property-owner-ym', 'backfill_property_owner_ym',
     "UPDATE properties SET owner = 'YM' "
     "WHERE status = 'Own' AND type IN ('Residential', 'Commercial')",
     False, None),
)


def _make_bulk_update_route(sql, use_now, total_table):
    def view():
        if request.form.get('secret') != IMPORT_MISSING_SECRET:
            abort(403)
        db = get_db()
        params = [datetime.utcnow().isoformat()] if use_now else []
        r = db.execute(sql, params)
        db.commit()
        payload = {'updated': r.rowcount}
        if total_table:
            payload['total'] = db.execute(
                f'SELECT COUNT(*) FROM {total_table}').fetchone()[0]
        return jsonify(**payload)
    return view


for _rule, _endpoint, _sql, _use_now, _total in _BULK_UPDATE_ROUTES:
    app.add_url_rule(
        _rule, _endpoint,
        _make_bulk_update_route(_sql, _use_now, _total),
        methods=['POST'],
    )


def _csv_rows(filename):
    import csv, io
    path = os.path.join(BASE_DIR, filename)
    with open(path, 'r', encoding='utf-8-sig') as f:
        content = f.read().replace('\r', '\n')
    return [r for r in csv.reader(io.StringIO(content)) if any(c.strip() for c in r)]


def _mclean(s):
    return (s or '').replace('\x0b', '\n').strip() or None


def _mnum(s, cast=float):
    s = (s or '').strip().replace(',', '').replace('$', '')
    try:
        return cast(s)
    except (ValueError, TypeError):
        return None


def _mdate(s):
    s = (s or '').strip().split(' ')[0]
    if not s:
        return None
    for fmt in ('%m/%d/%Y', '%Y-%m-%d', '%m/%d/%y'):
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None


def _mdatetime(s):
    s = (s or '').strip()
    if not s:
        return None
    for fmt in (
        '%m/%d/%Y %I:%M:%S %p', '%m/%d/%Y %I:%M %p',
        '%m/%d/%Y %H:%M:%S', '%m/%d/%Y %H:%M',
        '%Y-%m-%d %H:%M:%S', '%Y-%m-%d',
        '%m/%d/%Y',
    ):
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d %H:%M:%S')
        except ValueError:
            continue
    return None


@app.route('/admin/import-coins-missing', methods=['POST'])
def import_coins_missing():
    if request.form.get('secret') != IMPORT_MISSING_SECRET:
        abort(403)
    db = get_db()
    existing_coin_ids = {r['coin_id'] for r in db.execute(
        "SELECT coin_id FROM coins WHERE coin_id IS NOT NULL AND coin_id != ''")}
    existing_ids = {(r['id'] or '').lower() for r in db.execute("SELECT id FROM coins")}

    inserted = 0
    skipped_existing = 0
    skipped_bad = 0
    now = datetime.utcnow().isoformat()

    for row in _csv_rows('Coin.csv'):
        if len(row) < 45:
            skipped_bad += 1
            continue
        coin_id = _mclean(row[1])
        csv_uuid = _mclean(row[29])
        if coin_id:
            if coin_id in existing_coin_ids:
                skipped_existing += 1
                continue
            record_id = str(uuid.uuid4())
        else:
            if not csv_uuid:
                skipped_bad += 1
                continue
            if csv_uuid.lower() in existing_ids:
                skipped_existing += 1
                continue
            record_id = csv_uuid

        d1_text = row[11].strip().split(' - ', 1)[0].strip() if row[11] else ''

        db.execute('''
            INSERT INTO coins (
                id, coin_id, authority, print_field, notes,
                date_1, date_1_text, date_2, date_2_text,
                denomination, obv_rev, die_axis, grade, metal,
                mint, description, owner, price,
                property_name, purchase_date, coin_references,
                region, sheldon, size, status, strike, surface,
                vendor, weight, created_at, updated_at
            ) VALUES (?,?,?,?,?, ?,?,?,?, ?,?,?,?,?, ?,?,?,?, ?,?,?, ?,?,?,?,?,?, ?,?, ?,?)
        ''', (
            record_id, coin_id, _mclean(row[0]), _mclean(row[2]), _mclean(row[4]),
            _mnum(row[10], int), _mclean(d1_text), _mnum(row[12], int), _mclean(row[13]),
            _mclean(row[14]), _mclean(row[15]), _mclean(row[17]), _mclean(row[18]), _mclean(row[20]),
            _mclean(row[21]), _mclean(row[24]), _mclean(row[27]), _mnum(row[28]),
            _mclean(row[31]), _mdate(row[32]), _mclean(row[34]),
            _mclean(row[35]), _mclean(row[36]), _mnum(row[38]), _mclean(row[39]),
            _mnum(row[40]), _mnum(row[41]), _mclean(row[43]), _mnum(row[44]),
            now, now,
        ))
        inserted += 1
        if coin_id:
            existing_coin_ids.add(coin_id)
        existing_ids.add(record_id.lower())

    db.commit()
    total = db.execute('SELECT COUNT(*) FROM coins').fetchone()[0]
    return jsonify(inserted=inserted, skipped_existing=skipped_existing,
                   skipped_bad=skipped_bad, total=total)


@app.route('/admin/import-watches-missing', methods=['POST'])
def import_watches_missing():
    """Insert any rows from Watch.csv that aren't already in the
    watches table. Dedupe key: (reference, case_num, movement_num).

    `dry=1` reports what WOULD be inserted (brand / model / ref /
    case / mvt / year for each missing row) without writing — useful
    when the live count has dropped to spot-check whether the diff
    is recoverable accidental loss versus intentional deletions you
    DON'T want resurrected. Default behaviour is unchanged: actual
    insert."""
    if request.form.get('secret') != IMPORT_MISSING_SECRET:
        abort(403)
    dry = request.form.get('dry') == '1'
    db = get_db()
    existing = set()
    for r in db.execute("SELECT reference, case_num, movement_num FROM watches"):
        existing.add(((r['reference'] or '').strip(),
                      (r['case_num'] or '').strip(),
                      (r['movement_num'] or '').strip()))
    # Secondary index for the no-paperwork CSV rows. Every entry in
    # Watch.csv where all three of (reference, case_num, movement_num)
    # are blank — the vintage / orphan pieces — falls through the
    # primary dedupe (which can't tell ('','','') keys apart) and
    # would otherwise be silently dropped. We also dedupe those by
    # case-insensitive (brand, model) so we restore them once and
    # only once.
    existing_by_brand_model = set()
    for r in db.execute("SELECT brand, model FROM watches"):
        existing_by_brand_model.add(
            ((r['brand'] or '').strip().lower(),
             (r['model'] or '').strip().lower()))

    inserted = 0
    skipped_existing = 0
    skipped_bad = 0
    now = datetime.utcnow().isoformat()
    would_insert = []  # dry-run only

    for row in _csv_rows('Watch.csv'):
        if len(row) < 38:
            skipped_bad += 1
            continue
        reference = _mclean(row[28])
        case_num = _mclean(row[3])
        movement_num = _mclean(row[19])
        key = ((reference or '').strip(), (case_num or '').strip(), (movement_num or '').strip())
        brand_v = _mclean(row[1])
        model_v = _mclean(row[11])
        bm_key = ((brand_v or '').strip().lower(),
                  (model_v or '').strip().lower())

        if not any(key):
            # No-paperwork row — fall back to (brand, model) dedupe.
            # Skip if we can't even identify the piece by name.
            if not (bm_key[0] or bm_key[1]):
                skipped_bad += 1
                continue
            if bm_key in existing_by_brand_model:
                skipped_existing += 1
                continue
        elif key in existing:
            skipped_existing += 1
            continue

        if dry:
            would_insert.append({
                'brand':        brand_v,
                'model':        model_v,
                'reference':    reference,
                'case_num':     case_num,
                'movement_num': movement_num,
                'year':         _mnum(row[37], int),
                'matched_by':   '(brand, model)' if not any(key) else '(ref, case, mvt)',
            })
            if any(key):
                existing.add(key)
            else:
                existing_by_brand_model.add(bm_key)
            continue

        db.execute('''
            INSERT INTO watches (
                id, brand, model, reference, metal, case_diameter,
                dial_color, case_num, movement_num, edition, year,
                calibre, movement_type, movement_origin,
                beat, reserve, complications, clasp_type,
                strap_material, strap_color,
                date, price, vendor, description,
                owner, property, status,
                created_at, updated_at
            ) VALUES (?,?,?,?,?,?, ?,?,?,?,?, ?,?,?, ?,?,?,?, ?,?, ?,?,?,?, ?,?,?, ?,?)
        ''', (
            str(uuid.uuid4()),
            _mclean(row[1]), _mclean(row[11]), reference,
            _mclean(row[16]), _mnum(row[4]),
            _mclean(row[12]), case_num, movement_num,
            _mclean(row[15]), _mnum(row[37], int),
            _mclean(row[2]), _mclean(row[22]), _mclean(row[21]),
            _mnum(row[0], int), _mnum(row[13]),
            _mclean(row[6]), _mclean(row[5]),
            _mclean(row[35]), _mclean(row[34]),
            _mdate(row[10]), _mnum(row[25]), _mclean(row[36]), _mclean(row[23]),
            _mclean(row[24]), _mclean(row[27]), _mclean(row[33]),
            now, now,
        ))
        inserted += 1
        if any(key):
            existing.add(key)
        else:
            existing_by_brand_model.add(bm_key)

    if not dry:
        db.commit()
    total = db.execute('SELECT COUNT(*) FROM watches').fetchone()[0]
    return jsonify(inserted=inserted, skipped_existing=skipped_existing,
                   skipped_bad=skipped_bad, total=total,
                   dry_run=dry,
                   would_insert=would_insert if dry else None)


@app.route('/coins/print-pdf')
def coins_print_pdf():
    from reportlab.pdfgen import canvas
    from reportlab.lib.pagesizes import letter
    from reportlab.lib.units import mm
    import io

    db = get_db()
    q = (request.args.get('q') or '').strip()
    coin_filter = (request.args.get('filter') or '').strip() or None
    ids_raw = (request.args.get('ids') or '').strip()
    selected_ids = []
    seen_ids = set()
    if ids_raw:
        for part in ids_raw.split(','):
            coin_id = part.strip()
            if not coin_id or coin_id in seen_ids or len(coin_id) > 80:
                continue
            selected_ids.append(coin_id)
            seen_ids.add(coin_id)
            if len(selected_ids) >= 500:
                break

    if selected_ids:
        placeholders = ','.join('?' for _ in selected_ids)
        selected_rows = db.execute(
            f"SELECT * FROM coins WHERE id IN ({placeholders})",
            selected_ids,
        ).fetchall()
        rows_by_id = {str(row['id']): row for row in selected_rows}
        rows = [
            rows_by_id[coin_id]
            for coin_id in selected_ids
            if coin_id in rows_by_id and _user_can_see_row('coins', rows_by_id[coin_id])
        ]
    else:
        wheres, params = [], []
        if q:
            # Same multi-term AND logic as build_search_query: each
            # whitespace-separated term must match at least one column.
            search_cols = ['coin_id', 'authority', 'region', 'denomination',
                           'mint', 'obv_rev', 'description']
            terms = [t for t in q.split() if t.strip()]
            for term in terms:
                conditions = ' OR '.join([f'{c} LIKE ?' for c in search_cols])
                wheres.append(f"({conditions})")
                params += [f'%{term}%'] * len(search_cols)
        cat_filters = CATEGORY_FILTERS.get('coins', {})
        if coin_filter and coin_filter in cat_filters:
            clause, extra = cat_filters[coin_filter]
            wheres.append(f"({clause})")
            params += list(extra)
        _apply_row_filter_clauses('coins', wheres, params)

        where_sql = f"WHERE {' AND '.join(wheres)}" if wheres else ''
        rows = db.execute(
            f"SELECT * FROM coins {where_sql}", params).fetchall()
    # Recompute display-position bins for the print set: existing C\d+(\w*)
    # bins are preserved; new (no-bin / non-conforming) coins get a letter
    # suffix slotted between their neighbours per region/authority/mint.
    rows, _ = _recompute_coin_bins(db, rows, total=False)

    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    W, H = letter
    card = 35 * mm  # 35mm square (coin-tray label size)
    gap = 0  # cards abut each other for easier cutting
    cols = int(W // card)
    rows_per_page = int(H // card)
    total_w = cols * card
    total_h = rows_per_page * card
    left = (W - total_w) / 2
    top = (H + total_h) / 2  # top of grid

    per_page = cols * rows_per_page
    for idx, coin in enumerate(rows):
        slot = idx % per_page
        if idx > 0 and slot == 0:
            c.showPage()
        col_i = slot % cols
        row_i = slot // cols
        x = left + col_i * (card + gap)
        y = top - (row_i + 1) * card - row_i * gap
        _draw_coin_card(c, coin, x, y, card, card)
    c.save()
    buf.seek(0)
    filename = 'coin-tray.pdf' if selected_ids else 'coins.pdf'
    return Response(buf.read(), mimetype='application/pdf',
                    headers={'Content-Disposition': f'inline; filename="{filename}"'})


COIN_BIN_PREFIXES = ('C', 'CM', 'N', 'NM')
# Alternation order: longer prefixes first so "CM5" hits the CM branch
# instead of C with leftover M5.
COIN_BIN_RE = re.compile(
    r'^(CM|NM|C|N)\s*(\d+)\s*([a-z]*)$',
    re.IGNORECASE,
)


def _parse_coin_bin(s):
    """Return (prefix, numeric, letter_suffix_lower) for a bin matching
    the C / CM / N / NM scheme; None otherwise."""
    if not s:
        return None
    m = COIN_BIN_RE.match(s.strip())
    if not m:
        return None
    return (m.group(1).upper(), int(m.group(2)), (m.group(3) or '').lower())


def _coin_bin_prefix(coin):
    """Bin prefix from property + date_1 — Carp/NY × Ancient/Modern.
    Ancient drops the 'A': Carp Ancient → C, Carp Modern → CM,
    NYC Ancient → N, NYC Modern → NM. None when either axis is
    unmappable (no recognisable property, or no date_1).

    Reads property+date_1 directly rather than parsing cat_id — the
    flat C001..Cn cat_id no longer carries location/era info."""
    p = (coin['property_name'] or '').strip().lower()
    if p in ('carp', 'carpinteria'):
        loc = 'C'
    elif p in ('nyc', 'new york', 'ny'):
        loc = 'N'
    else:
        return None
    d = coin['date_1']
    if d in (None, ''):
        # No date → assume modern (mirrors the cat-id-fixer fallback).
        return loc + 'M'
    try:
        n = int(d)
    except (TypeError, ValueError):
        return None
    return loc if n < 500 else loc + 'M'


def _coin_renumber_sort_key(row):
    """Sort key for display-position renumbering. Empty fields sort last
    so positioned-up coins lead. Case-insensitive on the text fields."""
    return (
        ((row['region'] or '').strip().lower() or 'zzz'),
        ((row['authority'] or '').strip().lower() or 'zzz'),
        ((row['mint'] or '').strip().lower() or 'zzz'),
        ((row['cat_id'] or '').strip().lower() or 'zzz'),
    )


def _recompute_coin_bins(db, rows, total=False):
    """Assign display-position bins partitioned by location/era prefix
    (C / CM / N / NM, derived from property + date_1). Each prefix has
    its own 1..n sequence — Carpinteria Ancient coins are C1, C2, C2a;
    Carpinteria Modern are CM1, CM2, CM2a; NYC follows the same shape
    with N / NM.

    `total=True`: clean reassignment within each prefix group, ordered
    by region / authority / mint / cat_id. Letter suffixes are wiped.

    `total=False` (default — what the print route calls): preserve any
    coin already labelled with a conforming `<prefix><n>(<letters>)?`
    bin. Coins without a conforming bin slot between their neighbours
    with a letter suffix tied to the previous numeric anchor in the
    same prefix group — a Carp-Ancient coin between C15 and C16
    becomes C15a, a second one C15b.

    Special case: when a prefix group has zero conforming bins (first
    run on that group, or after a scheme change) the group is treated
    as a fresh total renumber so coins start at <prefix>1 instead of
    <prefix>0a.

    Returns (sorted_rows_as_dicts, updates_count). Coins with no
    mappable prefix appear in the returned list (in sort order) with
    their existing bin untouched."""
    by_prefix = {p: [] for p in COIN_BIN_PREFIXES}
    no_prefix = []
    for r in rows:
        p = _coin_bin_prefix(r)
        if p:
            by_prefix[p].append(r)
        else:
            no_prefix.append(r)

    out = []
    updates = []
    now = datetime.utcnow().isoformat()

    for prefix in COIN_BIN_PREFIXES:
        group = sorted(by_prefix[prefix], key=_coin_renumber_sort_key)
        if not group:
            continue
        has_conforming = any(
            _parse_coin_bin(r['bin']) and _parse_coin_bin(r['bin'])[0] == prefix
            for r in group
        )
        if total or not has_conforming:
            for i, r in enumerate(group, start=1):
                d = dict(r)
                new_bin = f'{prefix}{i}'
                if (d.get('bin') or '').strip() != new_bin:
                    updates.append((d['id'], new_bin))
                    d['bin'] = new_bin
                out.append(d)
        else:
            prev_anchor = None    # int — last numeric anchor in this prefix
            used_letters = set()  # letters already used at prev_anchor
            for r in group:
                d = dict(r)
                parsed = _parse_coin_bin(d.get('bin'))
                if parsed and parsed[0] == prefix:
                    _, num, letters = parsed
                    canonical = f'{prefix}{num}{letters}'
                    if (d.get('bin') or '').strip() != canonical:
                        updates.append((d['id'], canonical))
                        d['bin'] = canonical
                    if letters:
                        if num == prev_anchor and len(letters) == 1:
                            used_letters.add(letters)
                    else:
                        prev_anchor = num
                        used_letters = set()
                else:
                    letter = None
                    for i in range(26):
                        cand = chr(ord('a') + i)
                        if cand not in used_letters:
                            letter = cand
                            break
                    if letter is None:
                        letter = 'z'
                    base = prev_anchor if prev_anchor is not None else 0
                    new_bin = f'{prefix}{base}{letter}'
                    updates.append((d['id'], new_bin))
                    used_letters.add(letter)
                    d['bin'] = new_bin
                out.append(d)

    for r in sorted(no_prefix, key=_coin_renumber_sort_key):
        out.append(dict(r))

    if updates:
        db.executemany(
            "UPDATE coins SET bin = ?, updated_at = ? WHERE id = ?",
            [(b, now, i) for (i, b) in updates]
        )
        db.commit()
    return out, len(updates)


def _metal_short(metal):
    if not metal:
        return ''
    return metal.split(' ')[0] if ' ' in metal else metal


def _fit_text(c, text, max_width, font_name, font_size):
    from reportlab.pdfbase.pdfmetrics import stringWidth
    if not text:
        return ''
    while text and stringWidth(text, font_name, font_size) > max_width:
        text = text[:-1]
    return text


def _card_image_reader(path):
    """Downscale a source image to ~card size before handing to ReportLab.

    Why: the card prints at 35mm (~414px at 300dpi). Decoding a full-resolution
    source JPEG per coin is the PDF's bottleneck.

    Transparent source images (RGBA / palette-with-alpha) are flattened onto
    a WHITE background — without this, PIL's RGBA→RGB conversion fills
    transparent pixels with black, painting a black square behind every coin.
    """
    from io import BytesIO
    from PIL import Image
    from reportlab.lib.utils import ImageReader
    try:
        im = Image.open(path)
        im.thumbnail((512, 512))
        # Promote palette-with-transparency to RGBA so the alpha-aware
        # branch below catches it.
        if im.mode == 'P' and 'transparency' in im.info:
            im = im.convert('RGBA')
        if im.mode in ('RGBA', 'LA'):
            bg = Image.new('RGB', im.size, (255, 255, 255))
            alpha = im.split()[-1]
            bg.paste(im.convert('RGB'), mask=alpha)
            im = bg
        elif im.mode not in ('RGB', 'L'):
            im = im.convert('RGB')
        buf = BytesIO()
        im.save(buf, format='JPEG', quality=85)
        buf.seek(0)
        return ImageReader(buf)
    except Exception:
        return None


def _coin_date_range_text(d1, d2):
    """Format a coin date range tightly. When both dates share an era
    suffix (BC / BCE / AD / CE), the suffix appears only on the second
    date with no space — e.g. '480 - 440BC' instead of '480 BC - 440 BC'."""
    d1 = (d1 or '').strip()
    d2 = (d2 or '').strip()
    if d1 and d2:
        for era in ('BCE', 'BC', 'CE', 'AD'):
            if d1.upper().endswith(era) and d2.upper().endswith(era):
                d1 = d1[:-len(era)].rstrip()
                d2 = d2[:-len(era)].rstrip() + era
                break
        return f'{d1} - {d2}'
    return d1 or d2


def _format_die_axis(v):
    """Render die axis as '<n>h'. Accepts numeric strings, ints, floats,
    or already-formatted '12h'. Returns '' for blank/unparseable input."""
    if v is None:
        return ''
    s = str(v).strip()
    if not s:
        return ''
    if s.lower().endswith('h'):
        return s
    try:
        f = float(s)
        if f.is_integer():
            return f'{int(f)}h'
        return f'{f:g}h'
    except (TypeError, ValueError):
        return s


def _draw_coin_card(c, coin, x, y, w, h):
    c.setStrokeColorRGB(0.25, 0.25, 0.25)
    c.setLineWidth(0.9)
    c.rect(x, y, w, h, stroke=1, fill=0)

    pad = 3
    inner_w = w - 2 * pad

    # Top-left: region (bold). Falls back to authority when region is blank.
    title = (coin['region'] or coin['authority'] or '').strip()

    # Top-right: tight date range — shared era folds onto the trailing date
    date_range = _coin_date_range_text(coin['date_1_text'], coin['date_2_text'])

    top_y = y + h - pad - 7
    c.setFont('Helvetica-Bold', 7)
    c.drawString(x + pad, top_y, _fit_text(c, title, inner_w * 0.5, 'Helvetica-Bold', 7))
    c.setFont('Helvetica', 7)
    # Wider date allowance so the BC tail isn't truncated.
    c.drawRightString(x + w - pad, top_y, _fit_text(c, date_range, inner_w * 0.55, 'Helvetica', 7))

    # Description (obv_rev), full-width under title — 7pt to match the
    # date and the right-side spec stack.
    obv = (coin['obv_rev'] or '').strip()
    desc_y = top_y - 9
    if obv:
        c.setFont('Helvetica', 7)
        c.drawString(x + pad, desc_y, _fit_text(c, obv, inner_w, 'Helvetica', 7))

    # Bottom-right ident: "<cat_id> / <bin>" — cat_id regular, bin bold.
    # The display-position bin is the visually distinguishing handle when
    # locating a card in a tray, so it gets the weight.
    from reportlab.pdfbase.pdfmetrics import stringWidth
    bin_label = (coin['bin'] or '').strip()
    if bin_label:
        bin_label = re.sub(r'\s+', '', bin_label)
    cat_id = (coin['cat_id'] or '').strip()

    bottom_y = y + pad
    ident_font_size = 7
    right_x = x + w - pad
    if bin_label and cat_id:
        c.setFont('Helvetica-Bold', ident_font_size)
        c.drawRightString(right_x, bottom_y, bin_label)
        bold_w = stringWidth(bin_label, 'Helvetica-Bold', ident_font_size)
        prefix = f'{cat_id} / '
        c.setFont('Helvetica', ident_font_size)
        c.drawRightString(right_x - bold_w, bottom_y,
                          _fit_text(c, prefix, inner_w - bold_w,
                                    'Helvetica', ident_font_size))
    else:
        fallback = bin_label or cat_id or (coin['coin_id'] or '').strip()
        if fallback:
            c.setFont('Helvetica-Bold', ident_font_size)
            c.drawRightString(right_x, bottom_y,
                              _fit_text(c, fallback, inner_w,
                                        'Helvetica-Bold', ident_font_size))

    # Middle area: image (left) + specs stack (right). Bottom row holds the
    # ident, so the image bottom must clear it.
    mid_top = desc_y - 3
    mid_bottom = bottom_y + 9
    mid_h = mid_top - mid_bottom
    if mid_h < 10:
        return
    # Image takes ~62% of card width — coin renders ~58pt across, up
    # from ~52pt before. Spec column still has ~38% (≈34pt).
    img_w = w * 0.62

    # Image
    img_path = None
    for fld in ('image_1', 'image_2'):
        if coin[fld]:
            p = os.path.join(UPLOAD_FOLDER, coin[fld])
            if os.path.exists(p):
                img_path = p
                break
    if img_path:
        reader = _card_image_reader(img_path)
        if reader:
            try:
                c.drawImage(reader, x + pad, mid_bottom,
                            width=img_w - pad, height=mid_h,
                            preserveAspectRatio=True, mask='auto')
            except Exception:
                pass

    # Right-side specs (top-down): denomination, metal, mint, weight, mm, die axis.
    # Font bumps to 7pt; "Tetradrachm" is the widest typical denomination
    # and still fits the 34pt spec column at this size.
    specs = []
    if coin['denomination']: specs.append(coin['denomination'].strip())
    m = _metal_short(coin['metal'])
    if m: specs.append(m)
    if coin['mint']: specs.append(coin['mint'].strip())
    if coin['weight'] is not None: specs.append(f"{coin['weight']:.2f}g")
    if coin['size'] is not None: specs.append(f"{coin['size']:.1f}mm")
    da = _format_die_axis(coin['die_axis'])
    if da: specs.append(da)

    spec_font_size = 7
    c.setFont('Helvetica', spec_font_size)
    spec_count = len(specs)
    if spec_count:
        spec_w = w - img_w - pad
        # Squeeze line-height when there are many specs.
        step = min(9, max(7, mid_h / max(spec_count, 1)))
        # Vertically center the stack on the image. Total visible height ≈
        # last-baseline → first-cap = (count-1)*step + font_size; the empty
        # band above gets half the leftover so the column visually balances.
        stack_height = (spec_count - 1) * step + spec_font_size
        top_offset = max(0, (mid_h - stack_height) / 2)
        sy = mid_top - top_offset - spec_font_size
        for s in specs:
            c.drawRightString(x + w - pad,
                              sy,
                              _fit_text(c, s, spec_w, 'Helvetica', spec_font_size))
            sy -= step


@app.route('/admin/status-owned-to-own', methods=['POST'])
def status_owned_to_own():
    """Rename status='Owned' -> 'Own' across every table that has a status column."""
    if request.form.get('secret') != IMPORT_MISSING_SECRET:
        abort(403)
    db = get_db()
    tables = [r['name'] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")]
    per_table = {}
    total = 0
    for t in tables:
        cols = [r['name'] for r in db.execute(f"PRAGMA table_info({t})").fetchall()]
        if 'status' in cols:
            r = db.execute(
                f"UPDATE {t} SET status='Own' "
                "WHERE LOWER(TRIM(COALESCE(status, ''))) = 'owned'"
            )
            if r.rowcount:
                per_table[t] = r.rowcount
            total += r.rowcount
    db.commit()
    return jsonify(updated=total, per_table=per_table)


@app.route('/admin/dedupe-watches', methods=['POST'])
def dedupe_watches():
    """Collapse watch duplicates created by sweep auto-create when the
    matcher couldn't see "A. Lange & Söhne" and "A. Lange Sohne" as the
    same brand. Groups rows by (_norm(brand), _norm(model), _norm(ref))
    so spelling drift (diacritics, ampersands, dots) collapses into one
    bucket.

    Winner per group = the row with the most non-NULL fields (the
    "original" rich record). Tiebreaker: the spelling with more
    diacritics + ampersands. Sibling fields fill in where the winner
    is NULL — never overwrites real data — and siblings are deleted.

    Default: dry-run. Pass ?dry=0 to actually merge + delete.
    Always returns a JSON report of what was (or would be) done."""
    if request.form.get('secret') != IMPORT_MISSING_SECRET:
        abort(403)
    dry = request.args.get('dry', '1') != '0'
    db = get_db()
    cols = [c['name'] for c in db.execute("PRAGMA table_info(watches)").fetchall()]
    rows = [dict(r) for r in db.execute("SELECT * FROM watches").fetchall()]

    groups = {}
    for r in rows:
        key = (_norm(r.get('brand') or ''),
               _norm(r.get('model') or ''),
               _norm(r.get('reference') or ''))
        # Skip empty-brand rows — too risky to merge blind, the user
        # should look at those manually.
        if not key[0]:
            continue
        groups.setdefault(key, []).append(r)

    def fancy_count(s):
        """Diacritics + ampersands — markers of the canonical spelling."""
        s = s or ''
        return sum(1 for c in s if (not c.isascii()) or c == '&')

    def score(m):
        """Higher = better winner."""
        non_null = sum(1 for c in cols
                       if m.get(c) not in (None, '', 0))
        brand = m.get('brand') or ''
        return (non_null, fancy_count(brand), len(brand))

    actions = []
    rows_deleted = 0
    fields_filled = 0
    brands_canonicalized = 0
    for key, members in groups.items():
        if len(members) < 2:
            continue
        members.sort(key=score, reverse=True)
        winner = members[0]
        siblings = members[1:]

        # Canonical brand for the group = the spelling with the most
        # diacritics + ampersands across ALL members. Picks
        # "A. Lange & Söhne" over "A. Lange Sohne" even when the
        # richest-data row carries the impoverished spelling.
        canonical_brand = max(
            (m.get('brand') or '' for m in members),
            key=lambda b: (fancy_count(b), len(b)),
        )
        brand_change = None
        if canonical_brand and (winner.get('brand') or '') != canonical_brand:
            brand_change = {'from': winner.get('brand'), 'to': canonical_brand}
            winner['brand'] = canonical_brand
            brands_canonicalized += 1

        merge_updates = {}
        if brand_change:
            merge_updates['brand'] = canonical_brand
        for sib in siblings:
            for c in cols:
                if c in ('id', 'created_at'):
                    continue
                w = winner.get(c)
                if w in (None, '') and sib.get(c) not in (None, ''):
                    merge_updates[c] = sib[c]
                    winner[c] = sib[c]  # prevent later siblings overwriting

        actions.append({
            'norm_key':       ' | '.join(key),
            'winner_id':      winner['id'],
            'winner_brand':   winner.get('brand'),
            'winner_model':   winner.get('model'),
            'winner_ref':     winner.get('reference'),
            'sibling_ids':    [s['id'] for s in siblings],
            'sibling_brands': [s.get('brand') for s in siblings],
            'brand_change':   brand_change,
            'fields_filled':  sorted(merge_updates.keys()),
        })
        rows_deleted += len(siblings)
        fields_filled += len(merge_updates)

        if not dry:
            if merge_updates:
                set_sql = ', '.join(f"{c} = ?" for c in merge_updates)
                db.execute(
                    f"UPDATE watches SET {set_sql}, updated_at = ? WHERE id = ?",
                    list(merge_updates.values())
                    + [datetime.utcnow().isoformat(), winner['id']]
                )
            for sib in siblings:
                db.execute("DELETE FROM watches WHERE id = ?", [sib['id']])

    if not dry:
        db.commit()

    return jsonify({
        'dry_run':              dry,
        'groups_with_dupes':    len(actions),
        'rows_would_delete':    rows_deleted,
        'fields_would_fill':    fields_filled,
        'brands_canonicalized': brands_canonicalized,
        'actions':              actions,
    })


@app.route('/admin/canonicalize-watch-brands', methods=['POST'])
def canonicalize_watch_brands():
    """Standalone brand-spelling cleanup for watches that already
    DON'T have duplicates — i.e., a single row whose brand is spelled
    "A. Lange Sohne" when the canonical name is "A. Lange & Söhne".

    Groups every watch by _norm(brand). For each normalized group,
    picks the spelling with the most diacritics + ampersands as
    canonical and rewrites every row in the group to use it.

    Defaults to dry-run; pass ?dry=0 to apply.

    Note: dedupe-watches already canonicalizes brand for groups it
    collapses; this endpoint covers the rest."""
    if request.form.get('secret') != IMPORT_MISSING_SECRET:
        abort(403)
    dry = request.args.get('dry', '1') != '0'
    db = get_db()
    rows = [dict(r) for r in db.execute(
        "SELECT id, brand FROM watches WHERE COALESCE(brand, '') != ''"
    ).fetchall()]

    def fancy_count(s):
        s = s or ''
        return sum(1 for c in s if (not c.isascii()) or c == '&')

    groups = {}
    for r in rows:
        groups.setdefault(_norm(r['brand']), []).append(r)

    actions = []
    rows_changed = 0
    for nb, members in groups.items():
        if not nb:
            continue
        canonical = max(
            (m['brand'] for m in members),
            key=lambda b: (fancy_count(b), len(b)),
        )
        affected = [m for m in members if m['brand'] != canonical]
        if not affected:
            continue
        actions.append({
            'norm_brand':     nb,
            'canonical':      canonical,
            'rows_changed':   len(affected),
            'sample_changes': sorted({(m['brand'], canonical) for m in affected}),
        })
        rows_changed += len(affected)
        if not dry:
            for m in affected:
                db.execute(
                    "UPDATE watches SET brand = ?, updated_at = ? WHERE id = ?",
                    [canonical, datetime.utcnow().isoformat(), m['id']],
                )
    if not dry:
        db.commit()
    return jsonify({
        'dry_run':       dry,
        'groups_fixed':  len(actions),
        'rows_changed':  rows_changed,
        'actions':       actions,
    })


@app.route('/admin/watches-needing-relocation', methods=['GET'])
def watches_needing_relocation():
    """Diagnostic: list every watch whose status is Ordered, Loaned, or
    Consigned. Before the bucket-fix commit these routed under
    StuffFiles/Watches/No longer Owned/<brand>/ on disk; from now on
    they land in the main Watches/<brand>/ folder. Auto-purge is off,
    so the old copies stay behind for manual cleanup — this endpoint
    tells the user exactly which folders to drag to the Trash."""
    user = g.get('current_user') or {}
    if user.get('role') != 'owner':
        abort(403)
    db = get_db()
    rows = db.execute(
        "SELECT * FROM watches "
        "WHERE LOWER(TRIM(COALESCE(status,''))) IN ('ordered','loaned','consigned') "
        "ORDER BY brand COLLATE NODIACRITIC"
    ).fetchall()
    plan = EXPORT_LAYOUT['watches']
    file_specs = plan['files']           # [(field, default_label, title_field), …]
    docs_cols  = _docs_cols_for('watches') or []
    affected = []
    file_count = 0
    for r in rows:
        brand_raw = plan['group'](r)
        ident_raw = plan['ident'](r)
        # _safe_path matches what the actual export does — accents and
        # punctuation get sanitized identically so the paths reported
        # here are byte-equal to what's actually on disk.
        brand_safe, ident_safe = _safe_path(brand_raw, ident_raw)

        files = []

        def _emit(label, fname):
            """Build the same '<ident> — <label><ext>' leaf the export
            writes, then pair the No-longer-Owned path (where it lives
            now) with the main path (where the next sync will land it)."""
            if not fname:
                return
            label_safe = _safe_path(label)[0]
            ext = os.path.splitext(fname)[1] or ''
            leaf = (f'{ident_safe} — {label_safe}{ext}'
                    if label_safe else f'{ident_safe}{ext}')
            files.append({
                'label':    label_safe or label,
                'old_path': f'StuffFiles/Watches/No longer Owned/{brand_safe}/{leaf}',
                'new_path': f'StuffFiles/Watches/{brand_safe}/{leaf}',
            })

        # Fixed file slots (image_obv / image_rev / receipt). Mirrors
        # the per-row dedupe in the export so the same upload referenced
        # from two columns is reported once.
        seen = set()
        for field, default_label, title_field in file_specs:
            try:
                fname = (r[field] or '').strip()
            except (KeyError, IndexError):
                continue
            if not fname or fname in seen:
                continue
            seen.add(fname)
            label = default_label
            if title_field:
                try:
                    t = (r[title_field] or '').strip()
                    if t:
                        label = t
                except (KeyError, IndexError):
                    pass
            _emit(label, fname)

        # Dynamic documents — read from record_documents (the source of
        # truth) via _docs_load so this preview matches the real export.
        for json_col in docs_cols:
            docs = _docs_load(db, 'watches', r['id'], json_col) or []
            for i, d in enumerate(docs, 1):
                if not isinstance(d, dict):
                    continue
                fname = (d.get('filename') or '').strip()
                if not fname:
                    continue
                label = (d.get('title') or '').strip() or f'Doc {i}'
                _emit(label, fname)

        file_count += len(files)
        affected.append({
            'brand':  brand_safe,
            'ident':  ident_safe,
            'status': r['status'],
            'files':  files,
        })
    return jsonify(watch_count=len(affected),
                   file_count=file_count,
                   affected=affected)


def _backfill_serial_cat_ids(table, prefix):
    """Assign cat_ids to every row in `table` that doesn't have one,
    using the same flat W###/A### scheme as live inserts. Walks rows
    deterministically (id ASC) so re-runs are stable. Returns
    (assigned_count, sample_assignments).

    Side effect to flag to the user before running: every record that
    gets a fresh cat_id will have its file path in StuffFiles change
    on the next sync (because EXPORT_LAYOUT prefers cat_id when set).
    Old paths stay on disk for manual cleanup since auto-purge is
    off — typically dozens-to-hundreds of orphaned files."""
    db = get_db()
    rows = db.execute(
        f"SELECT id FROM {table} WHERE COALESCE(cat_id, '') = '' "
        f"ORDER BY id"
    ).fetchall()
    sample = []
    assigned = 0
    for r in rows:
        new_id = next_serial_cat_id(db, table, prefix)
        db.execute(
            f"UPDATE {table} SET cat_id = ?, updated_at = ? WHERE id = ?",
            (new_id, datetime.utcnow().isoformat(timespec='seconds'), r['id']),
        )
        if len(sample) < 10:
            sample.append({'id': r['id'], 'cat_id': new_id})
        assigned += 1
    db.commit()
    return assigned, sample


